COLLDATA("asabahur","ur",[[10063,"§۱۱۴۵۳ ۔ عائشہ بنت جریر\n(1) بن عمرو بن رزاح انصاریہ، بنو سلمہ سے ہیں، ابن حبیب نے بیعت کرنے والی خواتین میں ان کا ذکر کیا ہے، فرماتے ہیں: ابومنذر یزید بن عامر بن حدیدہ کی زوجہ تھیں۔","",{"fn":"(1) اسد الغابة (۷۰۸۶) تجرید (۲۸۶/۲)"}],[10064,"§۱۱۴۵۴ ۔ عائشہ بنت سعد\n(1) بن ابو وقاص زہریہ، ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے۔ صحیحین میں سعد بن ابو وقاص سے مروی ہے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے فرمایا، جب آپ صلی اللہ علیہ وسلم تشریف لائے، فتح کے سال یا حجتہ الوداع میں وہ مکہ میں بیمار تھے، میری ایک بیٹی کے علاوہ کوئی وارث نہیں۔ نووی رحمہ اللہ نے مبہمات میں فرمایا: ان کا نام عائشہ ہے، تجرید میں اس کا تعاقب کیا گیا ہے کہ عائشہ بنت سعد تابعیہ ہیں، وہ اتنا عرصہ زندہ رہیں کہ حضرت مالک رحمہ اللہ کی ان سے ملاقات ہوئی، یہ تعاقب ناپسندیدہ ہے۔ کیونکہ جن کا سیدنا سعد نے ذکر کیا ہے، بڑی ہیں، وہ جن سے مالک کی ملاقات ہوئی صغری ہیں۔ امام مالک رحمہ اللہ اور اہل علم میں سے کسی نے حضرت عائشہ بنت سعد کبری کے طبقہ کا زمانہ نہیں پایا، اور رہی صغریٰ تو وہ نبی کریم صلی اللہ علیہ وسلم کے بہت عرصے بعد پیدا ہوئیں، انہوں نے ان کا عنوان قائم نہیں کیا، کیونکہ انہوں نے بعض امہات المومنین کا زمانہ پایا۔","",{"fn":"(1) تجرید (۲۸۶/۲)"}],[10065,"§۱۱۴۵۵ ۔ عائشہ بنت ابی سفیان\n(1) بن حارث بن زید انصاریہ، بنوعبد الاشہل سے ہیں، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۰۸۸) تجرید (۲۸۶/۲)"}],[10066,"§۱۱۴۵۶ ۔ عائشہ بنت شیبہ\nبن ربیعہ بن عبد شمس۔ ان کے والد بدر میں قتل ہوئے، ان کا ذکر ہے، ابوزناد فقیہ مدنی کی مولاۃ ہیں۔"],[10067,"§۱۱۴۵۷ ۔ عائشہ بنت عبد الرحمن\n(1) بن عتیک نظریہ، ان کے شوہر رفاعہ کے سوانح میں ان کا ذکر گزر چکا ہے۔ یہ ابوموسیٰ کا قول ہے۔","",{"fn":"(1) اسد الغابة (۷۰۸۹) تجرید (۲۸۶/۲)"}],[10068,"§۱۱۴۵۸ ۔ عائشہ بنت عمیر\n(1) بن حارث بن ثعلبہ انصاریہ، بنو حرام سے ہیں۔ ابن حبیب نے بیعت کرنے والی خواتین میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۰۹۱)"}],[10069,"§۱۱۴۵۹ ۔ عائشہ بنت قدامہ\n(1) بن مظعون قرشیہ جمحیہ۔ ان کے چچا عثمان بن مظعون کے سوانح میں ان کا نسب گزر چکا ہے۔ ابوعمر(2) کا قول ہے: بیعت کرنے والوں میں سے ہیں، اہل مدینہ میں ان کا شمار ہے۔ میں کہتا ہوں: مکیہ ہیں اور مذکورہ بیعت مکہ میں ہوئی۔ امام احمد(3) رحمہ اللہ نے ان کی حدیث عبدالرحمن بن عثمان بن ابراہیم بن محمد بن طالب کے طریق سے روایت کی ہے، وہ فرماتے ہیں: مجھ سے میرے والد نے بحوالہ اپنی والدہ عائشہ بنت قدامہ روایت کیا، فرماتی ہیں: میں اپنی والدہ رابطہ بنت سفیان کے ساتھ تھی اور نبی کریم صلی اللہ علیہ وسلم عورتوں سے بیعت لے رہے تھے۔ فرمایا: “کیا تم اس بات پر بیعت کرتی ہو کہ اللہ کے ساتھ کسی کو شریک نہ ٹھہراؤ گی۔ (الحدیث) اس میں ہے: “تم بھلائی کے کاموں میں میری نافرمانی نہ کرو گی۔” انہوں نے سر جھکا لیا۔ فرماتے ہیں، انہوں نے کہا: “جہاں تک ہم سے ہو سکا۔ وہ یہ الفاظ کہہ رہی تھیں اور میں بھی ان کے ساتھ کہہ رہی تھی، میری والدہ نے مجھے تلقین کی، اس لیے جیسا وہ کہہ رہی تھیں میں بھی وہی کہنے لگی۔ ہم نے عالی سند سے ابن مندہ کی کتاب معرفہ میں دوسرے طریق سے اسے روایت کیا ہے۔ بحوالہ عبدالرحمن بن عثمان، اس میں ہے: اپنی والدہ رابطہ بنت سفیان جو خزاعہ کی خاتون ہیں۔ ابو نعیم نے دوسرے طریق سے اس سند کے ساتھ دو احادیث بحوالہ عائشہ بنت قدامہ نقل کی ہیں۔ وہ ان دونوں میں فرماتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا، اور وہ ابن سعد کے اس قول پر رد ہے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت نہیں کی، ان کی روایت میں ہے: ان کی والدہ فاطمہ بنت سفیان ہیں، شائد یہ اس نسخے سے ہو، صحیح یہ ہے، رابطہ بنت سفیان بن حارث بن امیہ بن فضل بن منقذ خزاعیہ، فرمایا: سیدہ عائشہ رضی اللہ عنہا کا نکاح ابراہیم بن محمد بن حاطب سے ہوا، ان سے اولاد ہوئی۔","",{"fn":"(1) اسد الغابة (۷۰۹۲) الاستيعاب (۳۴۷۸) تجرید (۲۸۶/۲)\n(2) الاستيعاب (۱۸۸۶/۴)\n(3) مسند احمد (۳۶۵/۶)"}],[10070,"§۱۱۴۶۰ ۔ عائشہ بنت معاویہ\n(1) بن مغیرہ بن ابو عاص بن امیہ، عبدالملک بن مروان کی والدہ ہیں۔ ان کے والد اُحد میں حالت کفر میں قتل ہوئے، ان کی والدہ فاطمہ بنت عامر جمحی ہیں، ابن اسحاق کا قول ہے: جب نبی کریم صلی اللہ علیہ وسلم اور آپ صلی اللہ علیہ وسلم کے اصحاب واقعہ اُحد کے بعد حمراء الاسد کی طرف روانہ ہوئے اس اندیشے سے کہ ابو سفیان اور اس کے حواری لوٹ نہ آئیں، انہیں ابوعزہ جمحی اور معاویہ بن مغیرہ جن کا ذکر ہے، ملے۔ آپ صلی اللہ علیہ وسلم نے عاصم بن ثابت کو ابو عزہ کے قتل کا حکم دیا اور سیدنا عثمان بن عفان رضی اللہ عنہ نے معاویہ کو اس شرط پر امان دی کہ وہ تین دن کے بعد نظر نہ آئے۔ نبی کریم صلی اللہ علیہ وسلم نے اس کے بعد سیدنا زید بن حارثہ اور عمار بن یاسر کو بھیجا، اور انہیں فرمایا: تم دونوں اسے فلاں مقام پر مقتول پاؤ گے۔ میں کہتا ہوں: ان سیدہ عائشہ رضی اللہ عنہا نے نبی کریم صلی اللہ علیہ وسلم کی زندگی میں سات برس کا زمانہ پایا۔ پہلے گزر چکا ہے کہ مکہ میں حجتہ الوداع کے موقع پر قریش کے تمام لوگ اسلام لا چکے تھے اور حاضر تھے۔","",{"fn":"(1) تجرید (۲۸۷/۲)"}],[10071,"§۱۱۴۶۱ ۔ عبادہ بنت ابی نائلہ\n(1) بن سلامہ بن وقش انصاریہ۔ ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے۔ ابن حبیب نے بیعت کرنے والوں میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۰۹۳) تجرید (۲۸۷/۲)"}],[10072,"§۱۱۴۶۲ ۔ عتبہ بنت زرارہ\n(1) بن عدس انصاریہ، ابن حبیب نے بیعت کرنے والوں میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۰۹۴) تجرید (۲۸۷/۲)"}],[10073,"§۱۱۴۶۳ ۔ عجلہ بنت عجلان اللیثیہ\nبنو لیث بن سعد بن بکر بن عبد مناة بن کنانہ سے ہیں۔ رکانہ بن عبد یزید اور ان کے بھائیوں کی والدہ ہیں، یہ وہی ہیں جنہیں ابو رکانہ نے طلاق دی اور نبی کریم صلی اللہ علیہ وسلم نے انہیں ان پر لوٹا دیا تھا، عبد یزید کے سوانح میں ان کا ذکر گزر چکا ہے۔"],[10074,"§۱۱۴۶۴ ۔ العجماء الانصاریہ\n(1) ابوامامہ بن سہل بن حنیف کی خالہ ہیں، ابوامامہ نے اپنی خالہ عجماء سے روایت کیا، فرماتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: “بوڑھا اور بڑھیا جب زنا کریں تو انہیں یقینا رجم کیا جائے، اس لیے کہ انہوں نے لذت اٹھائی۔” طبرانی(2) رحمہ اللہ اور ابن مندہ نے اسے نقل کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۰۹۵) تجرید (۲۸۷/۲)\n(2) المعجم الكبير (۸۶۷/۲۴)"}],[10075,"§۱۱۴۶۵ ۔ عدیہ بنت سعد\nبن خلیفہ بن اشرف انصاریہ بنو حارث بن خزرج بن ساعدہ سے ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔"],[10076,"§۱۱۴۶۶ ۔ عزہ بنت الحارث الہلالیہ\n(1) میمونہ کی بہن ہیں۔ ابو عمر(2) نے مختصر ان کا ذکر کیا ہے۔ اور فرمایا: میرے خیال میں کسی نے صحابہ رضی اللہ عنہم میں ان کا ذکر نہیں کیا۔ میں کہتا ہوں: ابن سعد نے غرائب میں صحابیہ خواتین میں ان کی ماں شریک بہنوں کے ساتھ ان کا ذکر کیا ہے، اور کہا ہے وہ سیدہ میمونہ ام المومنین کی بہن ہیں۔ ان کا نکاح عبد اللہ بن مالک بن ہرم سے ہوا جس سے زیادہ، عبدالرحمن، برزہ پیدا ہوئے۔ برزہ سے اسہم جو یزید کے والد ہیں پیدا ہوئے۔ بعض کا قول ہے: یزید بن اسہم کی والدہ ہیں، فرماتے ہیں، بعض کا قول ہے: برزہ، عزہ کی ماں شریک بہن ہیں۔ فرماتے ہیں، بعض نے کہا: عزہ بنو کلاب کے ایک شخص کے نکاح میں تھیں، ان سے اولاد ہوئی۔","",{"fn":"(1) اسد الغابة (۷۰۹۹) الاستيعاب (۳۴۷۹) تجرید (۲۸۷/۲)\n(2) الاستيعاب (۱۸۸۶/۴)"}],[10077,"§۱۱۴۶۷ ۔ عزہ بنت خابل\n(1) ابو عمرہ(2) نے ذکر کیا ہے کہ عزہ بنت کامل، پہلا قول صحیح ہے۔ ابن ابو عاصم اور طبرانی نے اوسط میں موسیٰ بن یعقوب کے طریق سے، عطاء بن مسعود کعبی سے بحوالہ ان کی پھوپھی عزہ بنت خابل نقل کیا ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں، اور ان سے اس بات پر بیعت کی کہ اللہ کے ساتھ کسی کو شریک نہ ٹھہرائیں گی، نہ چوری کریں گی، نہ زنا کریں گی، نہ یہ اذیت دیں گی، نہ کسی بچی کو زندہ درگور کریں گی نہ چھپائیں گی۔ عزہ فرماتی ہیں: مجھے معلوم ہے داد تو اولاد کا قتل کرتا ہے، رہا خفی، تو وہ مجھے معلوم نہیں، میں نے رسول اللہ صلی اللہ علیہ وسلم سے اس کے بارے میں سوال نہیں کیا، میرے دل میں آیا کہ اس سے مراد بچے کو ضائع کرنا ہے۔ اللہ کی قسم! میں نے اپنا کوئی بچہ ضائع نہیں کیا۔ ابو عمر فرماتے ہیں: ان سے ایک حدیث مروی ہے، جس کی سند درست نہیں۔","",{"fn":"(1) اسد الغابة (۷۱۰۰) الاستيعاب (۳۴۸۱) تجرید (۲۸۷/۲)\n(2) الاستيعاب (۱۸۸۶/۴)"}],[10078,"§۱۱۴۶۸ ۔ عزہ بنت ابی سفیان\n(1) بن حرب امویہ، ام حبیبہ جو نبی کریم صلی اللہ علیہ وسلم کی زوجہ ہیں، ان کی بہن ہیں۔ یہ ثابت ہے کہ یہ وہی ہیں جنہیں ام المومنین نے نبی کریم صلی اللہ علیہ وسلم پر نکاح کے لیے پیش کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: “وہ میرے لیے حلال نہیں”۔ وہ کہنے لگیں: ہمیں معلوم ہوا ہے کہ آپ ابوسلمہ کی بیٹی سے نکاح کریں گے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “وہ اگر میری پرورش میں نہ ہوتی تب بھی حلال نہ تھی، کیونکہ وہ میرے رضاعی بھائی کی بیٹی ہے، مجھ پر اپنی بیٹیوں اور بہنوں کو نکاح کے لیے پیش نہ کرو۔” لیٹ کی روایت میں بحوالہ یزید بن ابو حبیب، انہوں نے زہری سے انہوں نے زینب بنت ابوسلمہ سے، انہوں نے ام حبیبہ(2) سے ان کا نام عزہ ذکر کیا ہے، جو مسلم اور نسائی میں ہے۔ حرف دال میں ان کا نام درہ گزر چکا ہے، ہو سکتا ہے کہ ان دونوں ناموں میں سے ایک ان کا لقب ہو، محفوظ روایت یہ ہے کہ ابو سلمہ کی بیٹی کا نام دُرّہ ہے۔ صحیح میں بھی ان کا نام مذکور ہے۔","",{"fn":"(1) اسد الغابة (۷۱۰۱) الاستيعاب (۳۴۸۰)\n(2) مسلم (۳۵۷۱)"}],[10079,"§۱۱۴۶۹ ۔ عزہ بنت ابی لہب\nبن عبدالمطلب ہاشمیہ۔ دار قطنی رحمہ اللہ نے کتاب الاخوۃ میں ان کا ذکر کیا ہے۔ اور فرمایا: ان سے حدیث مروی نہیں۔ ابن سعد فرماتے ہیں: ان سے اوفی بن حکیم بن امیہ بن حارثہ بن اوقص سلمی نے نکاح کیا جس سے عبیدہ، سعید اور ابراہیم پیدا ہوئے جو اوفی کے بیٹے ہیں۔"],[10080,"§۱۱۴۷۰ ۔ عزہ الاشجعیہ\n(1) ابو حازم کی مولاۃ ہیں، جنہوں نے انہیں آزاد کیا۔ ابو عمر(2) کا قول ہے۔ اشعث بن سوار کے پاس بحوالہ منصور ان کی حدیث ہے، انہوں نے ابو حازم اشجعی سے روایت کیا انہوں نے اپنی مولاۃ عزہ سے روایت کیا، فرماتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: “تمہارے لیے دو سرخ چیزوں میں ہلاکت ہے: سونا اور زعفران۔”(3)","",{"fn":"(1) اسد الغابة (۷۰۹۸) الاستيعاب (۳۴۸۲) تجرید (۲۸۷/۲)\n(2) الاستيعاب (۱۸۸۶/۴)\n(3) جامع المسانيد والسنن (۶۱۱/۱۵)"}],[10081,"§۱۱۴۷۱ ۔ عزیزہ بنت ابی تجراہ\nعبدریہ، برہ کی بہن ہیں۔ بلاذری نے ان کا ذکر کیا ہے، اور ابن سعد اور ولید بن صالح دونوں سے بحوالہ واقدی نقل کیا ہے۔ انہوں نے عمیرہ بنت عبد اللہ بن کعب سے، انہوں نے عزیزہ بنت ابو تجراۃ سے روایت کیا ہے۔ فرماتی ہیں: قریش چاشت کی نماز سے واقف نہیں تھے، اور مسلمان پانچ نمازوں کے فرض ہونے سے پہلے چاشت اور عصر کی نماز پڑھتے تھے۔ نبی کریم صلی اللہ علیہ وسلم اور آپ کے اصحاب جب دن کے آخری حصے میں نماز پڑھنا ہوتی تو گھاٹیوں میں چلے جاتے اور تنہا نماز ادا کرتے۔"],[10082,"§۱۱۴۷۲ ۔ عصماء بنت الحارث الہلالیہ\nام خالد بن ولید ہیں، انہیں لبابہ صغری کہا جاتا ہے، ابن کلبی نے یہ ذکر کیا ہے، حرف لام میں اس کا ذکر آئے گا۔"],[10083,"§۱۱۴۷۳ ۔ عصمہ بنت حبان\n(1) بن صحر بن خنساء انصاریہ، بنو حرام سے ہیں۔ ابن حبیب نے بیعت کرنے والوں میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۰۲) تجرید (۲۸۷/۲)"}],[10084,"§۱۱۴۷۴ ۔ عصیمہ\n(1) تصغیر کے ساتھ ہے، بنت افلح، ابن سعد نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۲۸۷/۲)"}],[10085,"§۱۱۴۷۵ ۔ عفراء بنت السکن\n(1) بن رافع بن معاویہ بن عبید، بنو خزرج سے ہیں، اسعد بن زرارہ کی والدہ ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۰۳) تجرید (۲۸۷/۲)"}],[10086,"§۱۱۴۷۶ ۔ عفراء بنت عبید\n(1) بن ثعلبہ بن سواد بن غنم، بعض کا قول ہے: ثعلبہ بن عبید بن ثعلبہ بن غنم بن مالک بن نجار۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ معاذ اور معوذ اور عوف جو بنو حارث کے بیٹے ہیں ان کی والدہ ہیں۔ بعض کا قول ہے: ان میں سے ہر ایک عفراء کا بیٹا ہے۔ ابن سعد(2) رحمہ اللہ کا قول ہے: ان کی والدہ رعاثہ بنت عدی بن معاذ ہیں۔ ان سے حارث بن رفاعہ بن حارث بن سواد نے نکاح کیا، جس سے اولاد ہوئی۔ ابن کلبی فرماتے ہیں: معاذ اور معوذ شہید ہوئے تو ان کی والدہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں اور کہنے لگیں: یا رسول اللہ! کیا عوف بن حارث کے بیٹوں میں سے یہ شریر تو نہیں ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “نہیں”۔ ابن اثیر(3) کا قول ہے: ابن کلبی کو اس قول سے اتفاق نہیں کہ معاذ بدر کے دن شہید ہوئے۔ میں کہتا ہوں: ان عفراء کو ایسی خصوصیت حاصل ہے جو کسی اور کو حاصل نہیں۔ انہوں نے حارث کے بعد بکیر بن یالیل لیثی سے نکاح کیا، ان سے چار بیٹے پیدا ہوئے: ایاس، عاقل، خالد، عامر، سب بدر میں شہید ہوئے۔ ان کے ماں شریک بھائی جو حارث کے بیٹے ہیں، شہید ہوئے، اس سے معلوم ہوا کہ یہ وہ صحابیہ خاتون ہیں جن کے سات بیٹے ہیں اور سب نبی کریم صلی اللہ علیہ وسلم کے ساتھ جہاد کرتے ہوئے شہید ہو گئے۔","",{"fn":"(1) اسد الغابة (۷۱۰۴) تجرید (۲۸۷/۲)\n(2) الطبقات الكبرى (۳۲۵/۸)\n(3) اسد الغابة (۳۴۶/۵)"}],[10087,"§۱۱۴۷۷ ۔ عقرب بنت السکن\n(1) بن رافع۔ ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، مجھے معلوم نہیں، یہ عفراء ہیں جن کے نام میں لفظی غلطی ہو گئی یا ان کی بہن ہیں۔","",{"fn":"(1) تجرید (۲۸۸/۲)\n(2) الطبقات الكبرى (۲۷۰/۸)"}],[10088,"§۱۱۴۷۸ ۔ عقرب بنت سلامہ\n(1) بن وقش، ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ فرماتے ہیں: ان کی والدہ سہیمہ بنت عبداللہ واقفیہ ہیں، ان کا نکاح رافع بن یزید اشہلی سے ہوا، جس سے اسید پیدا ہوئے۔","",{"fn":"(1) اسد الغابة (۷۱۰۵) تجرید (۲۸۸/۲)\n(2) الطبقات الكبرى (۲۳۵/۸)"}],[10089,"§۱۱۴۷۹ ۔ عقرب بنت معاذ\n(1) بن نعمان بن امرئ القیس بن زید بن عبد الاشہل، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ فرماتے ہیں: قیس بن عظیم کی زوجہ ہیں، یزید بن قیس اور ان کے بھائی ثابت بن قیس کی والدہ ہیں۔ ابن سعد(2) کا قول ہے: سعد بن معاذ کی سگی بہن ہیں، اسلام لائیں اور بیعت کی، ان کا نکاح یزید بن گرز بن زعوراء بن عبد الاشہل سے ہوا، جن سے رافع اور حواء پیدا ہوئے، ان کے بعد قیس بن خطیم سے نکاح ہوا، جس سے ثابت اور یزید پیدا ہوئے، اسی سے ان کی کنیت ہے، جسر کے دن شہید ہوئے۔","",{"fn":"(1) اسد الغابة (۷۱۰۶) تجرید (۲۸۸/۲)\n(2) الطبقات الكبرى (۱۳۱/۸)"}],[10090,"§۱۱۴۸۰ ۔ عقیلہ بنت عتیک\nبن حارث عتوریہ، ابوعمر کا قول ہے: ہجرت کرنے والی اور بیعت کرنے والی خاتون ہیں۔ مدینے کی رہنے والی ہیں۔ ان کی حدیث موسیٰ بن عقبہ کے ہاں ہے۔ میں کہتا ہوں: طبرانی نے اسے بکار بن عبداللہ بن عبیدہ عبدی کے طریق سے بحوالہ ان کے چچا موسیٰ بن عبیدہ روایت کیا ہے۔ وہ فرماتے ہیں: مجھ سے زید بن عبدالرحمن بن ابوسلامہ نے بحوالہ اپنی والدہ حجتہ بنت قریط انہوں نے ان دونوں کی والدہ عقیلہ بنت عتیک بن حارث سے نقل کیا ہے، فرماتی ہیں: میں اور میری والدہ بریرہ بنت حارث عتوریہ مہاجر خواتین کے ساتھ آئیں، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی، آپ صلی اللہ علیہ وسلم نے مقام ابطح میں ایک خیمہ لگایا ہوا تھا۔ آپ صلی اللہ علیہ وسلم نے ہم سے یہ شرط رکھی کہ ہم اللہ کے ساتھ کسی کو شریک نہ ٹھہرائیں گی، نہ چوری کریں گی ... (الحدیث) اس میں ہے: ہم نے اپنے ہاتھ بیعت کرنے کے لیے بڑھائے، آپ صلی اللہ علیہ وسلم نے فرمایا: “میں عورتوں سے ہاتھ نہیں ملاتا۔” آپ صلی اللہ علیہ وسلم نے ہمارے لیے بخشش کی دعا کی، یہ ہماری بیعت تھی۔ طبرانی رحمہ اللہ نے اسی طرح زید بن حباب کے طریق سے بحوالہ موسیٰ بن عبیدہ روایت کیا ہے، اور ان سے مروی روایت میں فرمایا: زید بن عبداللہ، حدیث میں ان کی جو یہ بات ہے کہ آپ صلی اللہ علیہ وسلم ... یہ بات دلالت کرتی ہے کہ وہ مکہ میں تھے۔ ابو موسیٰ ذیل میں فرماتے ہیں: بخاری اور طبرانی رحمہ اللہ نے اسے عقیلہ ذکر کیا ہے، اور ابن مندہ نے غفیلہ ذکر کیا ہے۔ میں کہتا ہوں: ابونعیم نے درست کہا، اسی طرح خطیب نے مؤتلف میں فرمایا، اور ان کی حدیث زید بن حباب کے طریق سے نقل کی ہے، اور اپنی روایت میں فرمایا: میں اور میری والدہ فروہ دونوں اکٹھی ہوئیں (یہ نام ف اور واؤ سے پہلے را ساکن کے ساتھ ہے) یہ وہم ہے۔"],[10091,"§۱۱۴۸۱ ۔ عکناء\n(1) نون یاث کے ساتھ، بنت ابوصفرہ اسدیہ، مہلب کی بہن ہیں۔ ابن مندہ کا قول ہے: ہمیں محمد بن محمد بن یعقوب نے بتایا، وہ فرماتے ہیں: ہمیں ابن صاعد نے بتایا وہ فرماتے ہیں: ہم سے محمد بن یحی ازدی نے روایت کی، انہوں نے فرمایا: ہم سے ہشام بن سفیان نے، وہ فرماتے ہیں ہم سے عبید اللہ بن عبداللہ نے، بحوالہ ابوشعثاء روایت کی، فرمایا: عکناء یا عکثاء بنت ابوصفرہ، مہلب کی بہن فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم نے دس تاریخ کو عاشوراء کا روزہ رکھنے کا حکم دیا، میں نے ان سے ابوشعثاء کے بارے میں دریافت کیا، انہوں نے فرمایا: “وہ مجہول شیخ ہیں اور جابر بن زید نہیں”۔(2) میں کہتا ہوں: ابواحمد حاکم نے کنیتوں میں ان ابو الشعثاء کا ذکر نہیں کیا، ابن حبان نے ثقات میں ہشام بن سفیان کا ذکر کیا، اور چوتھے طبقے میں فرماتے ہیں: ہشام بن سفیان محروزی وہ عبید اللہ بن عبد اللہ علکی سے بحوالہ ابو بریدہ روایت کرتے ہیں: ان کی ابوالشعثاء سے روایت کا ذکر نہیں کیا، اور تابعین کی کنیتوں میں ابوشعثاء کے ذکر پر اعتماد نہیں کیا۔","",{"fn":"(1) اسد الغابة (۷۱۰۸) تجرید (۲۸۸/۲)\n(2) جامع المسانيد والسنن (۶۱۳/۱۵)"}],[10092,"§۱۱۴۸۲ ۔ علیہ\n(1) بنت شریح حضرمی، سائب بن زید کی ماں شریک بہن ہیں۔ مخرمہ بن شریح کی بہن ہیں جن کا ذکر نبی کریم صلی اللہ علیہ وسلم کے سامنے ہوا تو آپ صلی اللہ علیہ وسلم نے فرمایا: “وہ ایسا شخص ہے جو قرآن کو تکیہ نہیں بناتا۔”(2)","",{"fn":"(1) اسد الغابة (۷۱۱۰) تجرید (۲۸۸/۲)\n(2) نسائی (۱۷۸۲) احمد (۴۴۹/۳) طبرانی (۶۶۵۴/۷)"}],[10093,"§۱۱۴۸۳ ۔ عمارہ بنت حباشہ\n(1) بن جبیر، ابن سعد نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۲۸۸/۲)"}],[10094,"§۱۱۴۸۴ ۔ عمارہ بنت حمزہ\n(1) بن عبدالمطلب، سلمی بنت عمیس کے سوانح میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۱۱) تجرید (۲۸۸/۲)"}],[10095,"§۱۱۴۸۵ ۔ عمارہ بنت ابی ایوب\n(1) خالد بن زید انصاریہ۔ ابن حبیب نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ ابن سعد نے بھی ان کا ذکر کیا اور فرمایا: ان سے صفوان بن اوس بن جابر بن قرط نے جو بنو معاویہ بن مالک بن نجار سے ہیں، نکاح کیا، ان سے خالد بن صفوان پیدا ہوئے۔","",{"fn":"(1) تجرید (۲۸۸/۲)"}],[10096,"§۱۱۴۸۶ ۔ عمرہ بنت البرصاء\nبنت حارث ہیں، جن کا ذکر آ رہا ہے۔"],[10097,"§۱۱۴۸۷ ۔ عمرہ بنت الحارث\n(1) بن ابوضرار خزاعیہ، مصطلقیہ۔ ام المؤمنین سیدہ جویریہ رضی اللہ عنہا کی بہن ہیں۔ محمد بن عمرو بن ابوضرار سے بحوالہ ان کی پھوپھی عمرہ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی ہے: “دنیا میٹھی اور سرسبز ہے، جس نے اس سے حلال طریقے سے کوئی شے حاصل کی، اسے اس میں برکت دی جاتی ہے۔ بہت سے لوگ اللہ اور اس کے رسول صلی اللہ علیہ وسلم کے مال میں ملوث ہوتے ہیں جن کے لیے قیامت کے روز جہنم ہے۔” ابن ابو عاصم(2) اور عبداللہ بن احمد نے اسے زیادات زہد میں اور ابن مندہ نے خالد بن سلمہ کی روایت سے بحوالہ محمد بن عمرو بن حارث نقل کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۱۵) الاستيعاب (۳۴۸۶) تجرید (۲۸۹/۲)\n(2) الآحاد والمثاني (۸۵/۶)"}],[10098,"§۱۱۴۸۸ ۔ عمرہ بنت الحارث\nبن ابی عوف، قرصافہ کی بہن ہیں۔ مرزبانی نے ان کی بہن اور والدہ برصاء کے ساتھ ان کا ذکر کیا ہے۔ بعض کا قول ہے: ان کا نام امامہ ہے۔"],[10099,"§۱۱۴۸۹ ۔ عمرہ بنت حارثہ\nبن نعمان انصاریہ، بنو مالک بن نجار سے ہیں۔ ابن سعد فرماتے ہیں: ان سے قیس بن عمرو بن سہل بن ثعلبہ نے نکاح کیا جو بنو عمرو بن عوف سے ہیں، اسلام لائیں اور بیعت کی۔"],[10100,"§۱۱۴۹۰ ۔ عمرہ بنت حرام\n(1) بعض کا قول ہے: بنت حزم، انصاریہ۔ سعد بن ربیع کی زوجہ ہیں۔ حدیث جابر میں ان کا ذکر ہے جسے ابن ابو عاصم(2) اور طبرانی(3) وغیرہ نے یحی بن ایوب کے طریق سے بحوالہ محمد بن ثابت بنانی، انہوں نے محمد بن منکدر سے، انہوں نے جابر سے، انہوں نے عمرہ بنت حزم سے روایت کیا ہے۔ آپ صلی اللہ علیہ وسلم کے لیے بکری ذبح کی گئی، آپ صلی اللہ علیہ وسلم نے اس سے کھایا اور وضو کیا پھر ظہر کی نماز پڑھی، پھر آپ صلی اللہ علیہ وسلم کے سامنے یہ گوشت پیش کیا گیا، آپ صلی اللہ علیہ وسلم نے تناول فرمایا اور عصر کی نماز ادا کی، پھر دوبارہ وضو نہیں کیا۔ طبرانی رحمہ اللہ نے بنت حرام اور دوسرے راویوں نے بنت حزم لکھا ہے۔ ابو عمر(4) نے اسی کا یقین کیا ہے اور اسے مختصر ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۱۶) الاستيعاب (۳۴۸۷) تجرید (۲۸۹/۲)\n(2) الآحاد والمثاني (۲۶۳/۶)\n(3) المعجم الكبير (۸۴۸/۲۴)\n(4) الاستيعاب (۱۸۸۷/۴)"}],[10101,"§۱۱۴۹۱ ۔ عمرہ بنت حزم الانصاریہ\nجابر نے ان سے آگ پر پکی ہوئی چیز کھانے کے بعد وضو نہ کرنے کے بارے میں حدیث ذکر کی ہے، ابن مندہ کا قول ہے: اسے عبداللہ بن محمد بن عقیل نے بحوالہ جابر روایت کیا ہے اور ان کا نام نہیں لیا۔ ابن سعد نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، فرماتے ہیں: عمرہ بنت حزام بن زید بن لوذان بن عمرو بن عبد بن عوف بن غنم بن مالک بن نجار، فرماتے ہیں: عمرو بن حزم کی بہن اور ان کے دونوں بھائیوں عمارہ اور معمر کی سگی بہن ہیں، ان کی والدہ خالدہ بنت ابوانس ہیں۔"],[10102,"§۱۱۴۹۲ ۔ عمرہ بنت الربیع\n(1) بن نعمان بن سیاف انصاریہ، بنو مالک بن نجار سے ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، فرماتے ہیں: ان کا نام عمیرہ ہے۔","",{"fn":"(1) اسد الغابة (۷۱۱۷) تجرید (۲۸۹/۲)"}],[10103,"§۱۱۴۹۳ ۔ عمرہ بنت رواحہ الانصاریہ\n(1) ان کے بھائی عبداللہ بن رواحہ کے سوانح میں ان کا نسب گزر چکا ہے۔ بشیر بن سعد کی زوجہ ہیں جو نعمان کے والد ہیں۔ یہ وہی ہیں جنہوں نے بشیر سے سوال کیا کہ ان کے بیٹے کو اس کے دوسرے بھائیوں سے علیحدہ خاص عطیہ دے۔ نبی کریم صلی اللہ علیہ وسلم نے اسے رد کر دیا، صحیحین(2) میں حدیث ہے۔ یہ وہی ہیں جن کا قیس بن خطیم نے اپنے قصیدے کی تشبیب میں ذکر کیا ہے۔ انہوں نے کہا: “عمرہ ان سردار عورتوں میں سے ہے جس کی آستینیں خوشبو سے مہکتی رہتی ہیں۔”(3) بعض کا قول ہے: قیس بن خطیم نے ان سے نکاح کیا، جب حسان نے عمرہ کے بارے میں جو قیس کی بہن ہیں شعر کہے تو قیس نے ان کے بارے میں شعر کہے، بعض کا قول ہے قیس کی بہن کا نام لیلی ہے۔ وہ صحیح ہے۔ بعض نے کہا: جس کے بارے میں سیدنا حسان نے شعر کہے وہ عمرہ بنت صامت بن خالد بن عطیہ ہے جسے انہوں نے طلاق دے دی تھی پھر انہیں دل سے نہ بھلا سکے۔ زبیر بن بکار نے یہ اپنے چچا مصعب سے نقل کیا ہے، مسند طیالسی(4) نے بحوالہ شعبہ، انہوں نے محمد بن نعمان سے، انہوں نے طلحہ یامی سے، انہوں نے عبد القیس کی زوجہ سے، انہوں نے عبداللہ بن رواحہ کی بہن سے نقل کیا۔ فرماتی ہیں: “ہر بالغہ عورت پر نکلنا واجب قرار دیا گیا، یعنی نماز عید وغیرہ کے لیے۔”","",{"fn":"(1) اسد الغابة (۷۱۱۸) تجرید (۲۸۹/۲)\n(2) بخاری (۲۵۸۷، ۲۶۵۰) مسلم (۴۱۶۱)\n(3) دیوان قیس بن خطیم (۲۴، ۲۵) (۱۹۸، ۱۹۹)\n(4) مسند طيالسي (۱۶۲۲)"}],[10104,"§۱۱۴۹۴ ۔ عمرہ بنت سعد\nبن عمرو بن زید مناة بن عدی بن عمرو بن مالک بن نجار، بعض نے کہا: بنت سعد بن قیس، ابوموسیٰ کا قول ہے: سعد بن عبادہ کی والدہ ہیں، بعض نے کہا: عمرہ بنت مسعود ان کا ذکر آگے آ رہا ہے۔"],[10105,"§۱۱۴۹۵ ۔ عمرہ بنت سعد\nبن مالک بن خالد ساعدی سہل بن سعد کی بہن ہیں، عمیرہ میں ان کا ذکر آئے گا۔"],[10106,"§۱۱۴۹۶ ۔ عمرہ بنت السعدی\n(1) بن وقدان بن عبد شمس عامریہ۔ ان کے بھائی عبد اللہ بن سعدی کے سوانح میں ان کا نسب گزر چکا ہے۔ ابن اسحاق(2) نے حبشہ کی سرزمین کی طرف ہجرت کرنے والوں میں ان کا ذکر کیا ہے۔ فرماتے ہیں: مالک بن قیس بن ربیعہ اور ان کے ساتھ ان کی زوجہ عمرہ بنت سعدی ہیں، بعض نے کہا: ان کا نام عمیرہ ہے۔","",{"fn":"(1) اسد الغابة (۷۱۲۰) تجرید (۲۸۹/۲)\n(2) السيرة النبوية (۲۶۰/۱) (۹۰۵/۴)"}],[10107,"§۱۱۴۹۷ ۔ عمرہ بنت عویم\n(1) مستغفری رحمہ اللہ نے بخاری رحمہ اللہ کے حوالے سے ان کا ذکر کیا ہے اور ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۲۱) تجرید (۲۸۹/۲)"}],[10108,"§۱۱۴۹۸ ۔ عمرہ بنت قیس\n(1) بن عمرو انصاریہ۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ ابو شیخ بن ثابت کی والدہ ہیں جو حسان کے بھائی ہیں، یہ ابن حبیب کا قول ہے۔ ابن سعد(2) نے اس کی مخالفت کی ہے، فرماتے ہیں: ان کے والد کا نام مسعود ہے جیسا کہ آگے آ رہا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۲۲) تجرید (۲۸۹/۲)\n(2) الطبقات الكبرى (۲۹۹/۸)"}],[10109,"§۱۱۴۹۹ ۔ عمرہ بنت مرثد\n(1) اسماء کی بہن ہیں، ابن حبیب(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۲۳) تجرید (۲۸۹/۲)\n(2) المحبر (۴۱۳)"}],[10110,"§۱۱۵۰۰ ۔ عمرہ بنت مسعود\n(1) بن اوس بن مالک بن سواد بن ظفر انصاریہ۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، فرماتے ہیں: عبد اللہ بن محمد بن سلمہ کی والدہ ہیں۔","",{"fn":"(1) اسد الغابة (۷۱۲۴) الاستيعاب (۳۴۸۹) تجرید (۲۸۹/۲)"}],[10111,"§۱۱۵۰۱ ۔ عمرہ بنت مسعود\n(1) بن حارث بن رفاعہ انصاریہ، بنو نجار سے ہیں، ابن حبیب(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۲۵) تجرید (۲۸۹/۲)\n(2) المحبر (۴۳۱)"}],[10112,"§۱۱۵۰۲ ۔ عمرہ بنت مسعود\n(1) بن زرارہ بن عدی انصاریہ، بنو مالک بن نجار سے ہیں، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ ابن سعد فرماتے ہیں: اسعد بن زرارہ کی بھتیجی ہیں، ان کی والدہ مخزومیہ ہیں۔ ان سے علقمہ بن عمرو بن یغوث بن مالک بن مبذول نے نکاح کیا، عمرہ اسلام لائیں اور بیعت کی۔","",{"fn":"(1) اسد الغابة (۷۱۲۶) تجرید (۲۸۹/۲)"}],[10113,"§۱۱۵۰۳ ۔ عمرہ بنت مسعود بن قیس\n(1) بن عمرو بن زید مناة بن عدی بن عمرو بن مالک بن نجار سعد بن عبادہ کی والدہ ہیں۔ نبی کریم صلی اللہ علیہ وسلم کی حیات مبارکہ میں ۵ھ میں وفات پائی۔ ابن سعد رحمہ اللہ کا قول ہے: انہوں نے وفات پائی اور نبی کریم صلی اللہ علیہ وسلم غزوہ دومۃ الجندل میں تھے، یہ ربیع الاول کا واقعہ ہے، جب نبی کریم صلی اللہ علیہ وسلم مدینہ تشریف لائے تو ان کی قبر پر آئے ان کی نماز جنازہ پڑھی۔ میں کہتا ہوں: یہ ثابت ہے کہ انہوں نے وفات پائی تو نبی کریم صلی اللہ علیہ وسلم سے ان کے بیٹے نے ان کی طرف سے صدقہ کرنے کے بارے میں پوچھا۔","",{"fn":"(1) اسد الغابة (۷۱۲۶) تجرید (۲۸۹/۲)"}],[10114,"§۱۱۵۰۴ ۔ عمرہ بنت مسعود الصغری\n(1) سعد بن عبادہ کی خالہ ہیں۔ اوس بن زید بن اصرم بن زید بن ثعلبہ بن غنم کی زوجہ تھیں، ان سے ابومحمد پیدا ہوئے، ان کا نام مسعود بن اوس تھا، ان سے اس کے بعد سہل بن ثعلبہ بن حارث بن زید نے نکاح کیا، جس سے عمر، رغیبہ پیدا ہوئے، اسلام لائیں اور بیعت کی۔","",{"fn":"(1) تجرید (۲۸۹/۲)"}],[10115,"§۱۱۵۰۵ ۔ عمرہ بنت مسعود\n(1) بن قیس انصاریہ۔ ان دونوں کی بہن ہیں جو پہلے گزر چکی ہیں۔ ابن سعد کا قول ہے، یہ پانچ بہنیں تھیں، ان میں سے ہر ایک کا نام عمرہ تھا، اسلام لائیں اور بیعت کی، یہ تیسری ہیں، ان کی والدہ عمیرہ بنت عمرو بن حرام بن زید مناہ تھا۔ ثابت بن منذر بن حرام نے جو حمان اور ان کے بھائیوں کے والد ہیں، ان سے نکاح کیا، جس سے ابو شیخ بن ثابت پیدا ہوئے، جن کا نام ابی تھا، وہ بدر میں شریک تھے۔ اسلام لائے اور بیعت کی۔","",{"fn":"(1) تجرید (۲۸۹/۲)"}],[10116,"§۱۱۵۰۶ ۔ عمرہ بنت مسعود\n(1) بن قیس رابعہ، اپنے سے پہلے والی کی سگی بہن ہیں۔ زید بن مالک بن عبدود بن کعب بن عبد الاشہل نے ان سے نکاح کیا۔ ان سے سعد اور ثابت پیدا ہوئے۔","",{"fn":"(1) تجرید (۲۸۹/۲)"}],[10117,"§۱۱۵۰۷ ۔ عمرہ بنت مسعود\n(1) بن قیس خامسہ ہیں، اپنے سے پہلے والی دو عمرہ کی سگی بہنیں ہیں، قیس بن عمرو جو بنو نجار سے ہیں ان کی والدہ ہیں۔","",{"fn":"(1) تجرید (۲۸۹/۲)"}],[10118,"§۱۱۵۰۸ ۔ عمرہ بنت معاویہ الکندیہ\n(1) ابونعیم نے ان خواتین میں ان کا ذکر کیا ہے جن سے نبی کریم صلی اللہ علیہ وسلم نے نکاح کیا اور رخصتی نہیں ہوئی، محمد بن اسحاق کے طریق سے بحوالہ حکیم بن حکیم، انہوں نے محمد بن علی بن حسین سے، انہوں نے اپنے والد سے نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے کندہ سے، عمرہ بنت معاویہ سے نکاح کیا۔ مجالد کے طریق سے بحوالہ شعبی رحمہ اللہ یہ نقل کیا ہے۔ نبی کریم صلی اللہ علیہ وسلم نے کندہ کی ایک خاتون سے نکاح کیا، وہ نبی کریم صلی اللہ علیہ وسلم کی وفات کے بعد لائی گئیں۔","",{"fn":"(1) اسد الغابة (۷۱۲۷) تجرید (۲۹۰/۲)"}],[10119,"§۱۱۵۰۹ ۔ عمرہ بنت ہرال\n(1) بن عمرو بن اوس انصاریہ، بنو عمرو بن عوف بن خزرج سے ہیں۔ ابن حبیب(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۲۸) تجرید (۲۹۰/۲)\n(2) المحبر (۴۲۴)"}],[10120,"§۱۱۵۱۰ ۔ عمرہ بنت یزید الکلابیہ\n(1) ابن اسحاق(2) نے یونس بن بکیر کی روایت سے ان کا ذکر ان خواتین میں کیا ہے جن سے نبی کریم صلی اللہ علیہ وسلم نے نکاح کیا، فرماتے ہیں: عمرہ بنت یزید سے جو بنوابوبکر بن کلاب کی ایک خاتون تھیں، نبی کریم صلی اللہ علیہ وسلم نے نکاح کیا، یہ بنو وحید کی شاخ ہے، فضل بن عباس بن عبد المطلب نے ان سے نکاح کیا پھر طلاق دے دی۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے رخصتی سے قبل انہیں طلاق دے دی تھی۔ ان کے نسب کے بارے میں کہا گیا: عمرہ بنت یزید بن عبید بن اوس بن کلاب۔","",{"fn":"(1) اسد الغابة (۷۱۲۹) الاستيعاب (۳۴۹۰) تجرید (۲۹۰/۲)\n(2) اسد الغابة (۷۱۲۹) تجرید (۲۹۰/۲)"}],[10121,"§۱۱۵۱۱ ۔ عمرہ بنت یزید بن الجون\n(1) بعض کا قول ہے: رسول اللہ صلی اللہ علیہ وسلم نے ان سے نکاح کیا، آپ صلی اللہ علیہ وسلم کو یہ بات پہنچی کہ انہیں برص کا مرض ہے، تو آپ صلی اللہ علیہ وسلم نے انہیں طلاق دے دی، ان کی رخصتی نہیں ہوئی۔ بعض کا قول ہے: انہوں نے آپ صلی اللہ علیہ وسلم سے پناہ مانگی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “تمہیں پناہ دینے والے کی پناہ ملی”۔ پھر انہیں طلاق دے دی، اور اسامہ بن زید کو حکم دیا کہ انہیں تین کپڑے دے دیں، اسے ہشام بن عروہ نے بحوالہ ان کے والد سیدہ عائشہ رضی اللہ عنہا سے روایت کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۲۹) تجرید (۲۹۰/۲)"}],[10122,"§۱۱۵۱۲ ۔ عمرہ بنت یزید بن السکن\n(1) بن رافع بن امرئ القیس اشہلیہ۔ ابن حبیب(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۳۰) تجرید (۲۹۰/۲)\n(2) المحبر (۴۱۶)"}],[10123,"§۱۱۵۱۳ ۔ عمرہ بنت یسار\n(1) بن ازمہر۔ ابو موسیٰ نے ذیل میں ان کا ذکر بحوالہ مستغفری کیا ہے اور فرمایا: انہیں شرف صحابیت حاصل ہے۔","",{"fn":"(1) اسد الغابة (۷۱۳۱) الاستيعاب (۳۴۹۱) تجرید (۲۹۰/۲)"}],[10124,"§۱۱۵۱۴ ۔ عمرہ بنت یعار\n(1) بعض کا قول ہے: یہ وہی ہیں جنہوں نے سالم مولی ابو حذیفہ کو آزاد کیا، مشہور ہے کہ ان کا نام ثبیتہ ہے۔","",{"fn":"(1) اسد الغابة (۷۱۳۲) تجرید (۲۹۰/۲)"}],[10125,"§۱۱۵۱۵ ۔ عمرہ الاشہلیہ\n(1) ابن مندہ نے ان کا ذکر کیا ہے اور یوسف بن نافع کے طریق سے، بحوالہ عبیدہ رائی، انہوں نے عمرہ اشہلیہ سے نقل کیا ہے، فرماتی ہیں: ہمارے پاس رسول اللہ صلی اللہ علیہ وسلم تشریف لائے اور ہماری مسجد میں ظہر اور عصر کی نماز پڑھی۔ آپ صلی اللہ علیہ وسلم ایک روزہ سے تھے، جب سورج غروب ہوا، موذن نے اذان دی، آپ صلی اللہ علیہ وسلم کے پاس افطاری کے لیے بازو اور کندھے کا بھنا ہوا گوشت لایا گیا، آپ صلی اللہ علیہ وسلم اسے دانتوں سے کاٹ کر کھانے لگے، پھر مؤذن نے اذان دی، انہوں نے ایک کپڑے سے اپنے ہاتھ صاف کیے، کھڑے ہوئے اور نماز ادا کی، جبکہ پانی سے اعضاء نہیں دھوئے۔ آگ پر پکی ہوئی چیز کھانے کے بعد وضو نہ کرنے کے بارے میں عمرہ بنت حزم کی حدیث گزر چکی ہے۔ شاید وہ یہی ہیں۔ دونوں حدیثوں کے سیاق میں تعدد ہے (یعنی وہ الگ ہے اور یہ الگ)۔","",{"fn":"(1) اسد الغابة (۷۱۱۲) تجرید (۲۸۸/۲)"}],[10126,"§۱۱۵۱۶ ۔ عمیرہ\n(1) بنت ثابت بن نعمان ظفریہ، ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۲۹۰/۲)\n(2) الطبقات الكبرى (۲۴۹/۸)"}],[10127,"§۱۱۵۱۷ ۔ عمیرہ بنت جبیر\n(1) بن صخر بن امیہ بن خنساء بن عبید بن عدی بن غنم بن کعب بن سلمہ سلمیہ۔ ابن سعد نے ان کا ذکر کیا ہے۔ اور فرمایا: ان سے کعب بن مالک نے نکاح کیا، جس سے عبداللہ، فضالہ، وہب، معبد، خولہ، سعاد پیدا ہوئے۔ عمیرہ نے بیعت کی اور دونوں قبلوں کی جانب نماز پڑھی، ان کے بارے میں مروی ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے حدیث سنی۔","",{"fn":"(1) تجرید (۲۹۰/۲)"}],[10128,"§۱۱۵۱۸ ۔ عمیرہ بنت الحارث بن عبد رزاح ظفریہ\n(1)","",{"fn":"(1) تجرید (۲۹۰/۲)"}],[10129,"§۱۱۵۱۹ ۔ عمیرہ بنت ابی الحکم\n(1) رافع بن سنان، ان سے بکر بن بکار نے بحوالہ عبدالحمید بن جعفر روایت کیا، مجھ سے میرے والد اور ہماری قوم کے کئی لوگوں نے روایت کیا کہ ابوالحکم اسلام لائے اور ان کی زوجہ اسلام نہیں لائی، وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئی اور کہنے لگی: ابوالحکم نے میری بیٹی لے لی ہے اور اسے اپنے پاس روکا ہوا ہے، آپ صلی اللہ علیہ وسلم نے ابوالحکم کو حکم دیا وہ ایک کونے میں بیٹھ گئے، اور عورت کو حکم دیا وہ دوسرے کونے میں بیٹھ گئی، ان دونوں کے درمیان اس بچی کو رکھا، پھر فرمایا: “تم دونوں اسے بلاؤ۔” ان دونوں نے اسے بلایا، وہ بچی اپنی والدہ کی طرف مائل ہوئی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: اے اللہ! اسے ہدایت دے۔ وہ اپنے والد کی طرف چلی گئی۔ انہوں نے اسے لے لیا، ان کا نام عمیرہ ہے۔(2) ابو نعیم اور ابو موسیٰ نے اپنے طریق سے اسے نقل کیا ہے، اور دار قطنی رحمہ اللہ نے دوسرے طریق سے اسے بحوالہ عبدالحمید بن جعفر، انہوں نے اپنے والد، انہوں نے اپنے دادا سے نقل کیا ہے۔ نسائی، ابن ماجہ دوسرے طریق سے بحوالہ عثمان البتی اسے نقل کیا ہے، فرمایا: بحوالہ عبدالحمید بن سلمہ، انہوں نے اپنے والد سے، انہوں نے اپنے دادا سے بعض نے اسے مرسل روایت کیا ہے۔ ابو موسیٰ فرماتے ہیں: اس طریق کے علاوہ منقول ہے، اور لڑکی کا نام نہیں لیا۔","",{"fn":"(1) اسد الغابة (۷۱۳۳) تجرید (۲۹۰/۲)\n(2) ابوداؤد (۲۲۴۴) نسائی (۳۴۹۵) ابن ماجہ (۲۳۵۲) مسند احمد (۴۴۶/۵)"}],[10130,"§۱۱۵۲۰ ۔ عمیرہ بنت خماشہ\n(1) یا خباشہ انصاریہ، بنو خطمہ سے ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۳۴) تجرید (۲۰۹/۲)"}],[10131,"§۱۱۵۲۱ ۔ عمیرہ بنت ابی خیثمہ\n(1) عبد اللہ بن سماعہ کے سوانح میں ان کا ذکر ہے، امیمہ بنت ابو خیثمہ کی بہن ہیں، حرف ہمزہ میں جن کا ذکر گزر چکا ہے۔ ابن سعد کا قول ہے: اسلام لائیں اور بیعت کی، ان سے یزید بن اسید بن ساعدہ نے نکاح کیا وہ ان کے چچا زاد ہیں، اس کے بعد یزید بن زید بن بوع بن زید ظفری نے ان سے نکاح کیا۔","",{"fn":"(1) تجرید (۲۹۰/۲)"}],[10132,"§۱۱۵۲۲ ۔ عمیرہ بنت الربیع\nبن راساف، عمرہ میں ان کا ذکر گزر چکا ہے۔"],[10133,"§۱۱۵۲۳ ۔ عمیرہ بنت سعد\n(1) بن عامر بن عدی بن جشم انصاریہ۔ ابن سعد نے بیعت کرنے والی خواتین میں ان کا ذکر کیا ہے، اور فرمایا: ان سے کباشہ بن اوس بن قیلی بن عمرو بن زید بن جشم نے نکاح کیا۔","",{"fn":"(1) تجرید (۲۹۰/۲)"}],[10134,"§۱۱۵۲۵ ۔ عمیرہ بنت السعدی\nعمرہ میں ان کا ذکر گزر چکا ہے۔"],[10135,"§۱۱۵۲۶ ۔ عمیرہ بنت سہل\n(1) بن رافع، دو صاع صدقہ کرنے والے ہیں، جنہیں منافقین نے طعنہ دیا تھا۔ ابن مندہ فرماتے ہیں: انہوں نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا ہے۔ ابو عمر(2) کا قول ہے: سیدنا سہل اپنی بیٹی عمیرہ اور ایک صاع کھجور لے کر آئے اور عرض کیا: یا رسول اللہ! مجھے ایک حاجت ہے، آپ صلی اللہ علیہ وسلم نے پوچھا: “وہ کیا؟” عرض کیا: آپ اللہ سے میرے لیے اور میری بیٹی کے لیے دعا کریں اور اس کے سر پر ہاتھ پھیریں، اس کے علاوہ میری کوئی اولاد نہیں۔ عمیرہ فرماتی ہیں: آپ صلی اللہ علیہ وسلم نے اپنی ہتھیلی میرے سر پر رکھی، اللہ کی قسم! آپ صلی اللہ علیہ وسلم کے ہاتھ کی ٹھنڈک مجھے جگر تک پہنچی ہوئی(3) محسوس ہوتی ہے۔ میں کہتا ہوں: اسے ابن مندہ نے عیسی بن یونس کے طریق سے، سعید بن عثمان بلوی سے بحوالہ ان کی دادی روایت کیا ہے، عمیرہ بنت سہل نے ان سے حدیث بیان کی کہ ان کے والد دو صاع کھجور صدقہ، اور اپنی بیٹی عمیرہ کو لے کر نکلے، یہاں تک کہ نبی کریم صلی اللہ علیہ وسلم کے پاس پہنچے، وہ دو صاع انڈیل دیئے... پھر باقی حدیث انہی الفاظ کے ساتھ ذکر کی ہے۔","",{"fn":"(1) اسد الغابة (۷۱۳۶) تجرید (۲۹۱/۲)\n(2) الاستيعاب (۱۸۸۸/۴)\n(3) طبرانی (۸۴۹/۲۴) الحديث (۵۶۵۰/۱) مجمع الزوائد (۳۳/۷) جامع المسانيد والسنن (۶۱۹/۱۵)"}],[10136,"§۱۱۵۲۷ ۔ عمیرہ بنت سہیل\n(1) بن ثعلبہ بن حارث بن زید بن ثعلبہ بن غنم بن مالک بن نجار انصاریہ۔ ابن سعد نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے اور فرمایا: امیمہ بنت عمرو بن حارث بن قیس بن وقش ساعدیہ ان کی والدہ ہیں، ان سے ابوامامہ اسعد بن زرارہ نے نکاح کیا، جس سے ان کی بیٹیاں، فریعہ، کبشہ اور حبیبہ پیدا ہوئیں، ان سب نے بیعت کی۔","",{"fn":"(1) تجرید (۲۹۱/۲)"}],[10137,"§۱۱۵۲۸ ۔ عمیرہ بنت ظہیر\n(1) بن رافع بن عدی انصاریہ، بنو بکشم سے ہیں، ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے، ابن سعد(2) اور ابن حبیب نے بیعت کرنے والوں میں ان کا ذکر کیا ہے۔ ابن سعد کا قول ہے: ان کی والدہ فاطمہ بنت بشر بن عدی ہیں جو مربع بن قیلی کی زوجہ ہیں۔","",{"fn":"(1) اسد الغابة (۷۱۳۷)، تجرید (۲۹۱/۲)\n(2) الطبقات (۲۳۹/۵)"}],[10138,"§۱۱۵۲۹ ۔ عمیرہ بنت عبد سعد\n(1) بن عامر بن عدی: ابن سعد اور ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۳۸)، تجرید (۲۹۱/۲)"}],[10139,"§۱۱۵۳۰ ۔ عمیرہ بنت عبید\n(1) بن معروف یا مطروف بن حارث بن زید بن عبید انصاریہ، بنو عمرو بن عوف سے ہیں، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۳۹)، تجرید (۲۹۱/۲)"}],[10140,"§۱۱۵۳۱ ۔ عمیرہ بنت عقبہ\n(1) بن انتیجہ انصاریہ، بنو تجھی سے ہیں، ابن حبیب(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۴۰)، تجرید (۲۹۱/۲)\n(2) المحبر (۴۱۸)"}],[10141,"§۱۱۵۳۲ ۔ عمیرہ بنت عمیر\n(1) بن ساعدہ بن عائش انصاریہ، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۲۹۱/۲)"}],[10142,"§۱۱۵۳۳ ۔ عمیرہ بنت فرظہ\n(1) بن خنساء بن سنان، بنو حرام سے ہیں، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۴۱)، تجرید (۲۹۱/۲)"}],[10143,"§۱۱۵۳۴ ۔ عمیرہ بنت قیس\n(1) بن عمرو بن عبید بن مالک بن عدی بن حارث بن سلیط بن قیس انصاریہ: ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، ابن سعد(2) کا قول ہے: محمد بن عمر نے ذکر کیا کہ اسلام لائیں اور بیعت کی، میں نے قابل اعتماد نسخے میں میم کے زبر کے ساتھ لکھا ہوا پایا۔","",{"fn":"(1) اسد الغابة (۷۱۴۲)، تجرید (۲۹۱/۲)\n(2) الطبقات (۳۰۹/۸)"}],[10144,"§۱۱۵۳۵ ۔ عمیرہ بنت قیس\n(1) بن ابو کعب انصاریہ، بنو سواد سے ہیں، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، سہل بن قیس کی بہن ہیں جو اُحد کے دن شہید ہوئے۔","",{"fn":"(1) اسد الغابة (۷۱۴۳)، تجرید (۲۹۱/۲)"}],[10145,"§۱۱۵۳۶ ۔ عمیرہ بنت کلثوم\n(1) بن عدم انصاریہ: ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے، ابن سعد(2) اور ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۴۴)، تجرید (۲۹۱/۲)\n(2) الطبقات (۲۵۵/۸)"}],[10146,"§۱۱۵۳۷ ۔ عمیرہ بنت محمد\nبن سلمہ انصاریہ ان کے والد کے سوانح میں ان کا ذکر گزر چکا ہے۔ قرطبی رحمہ اللہ نے تفسیر میں بیان کیا ان کے بارے میں یہ آیت نازل ہوئی۔ “مرد عورتوں پر حاکم ہیں... بلند اور بڑا ہے۔”(1) میں نے اسے ثعلبی رحمہ اللہ کی تفسیر میں ابن کلبی کے طریق سے پایا، فرماتے ہیں: سعد بن ربیع نے اپنی زوجہ عمیرہ کو تھپڑ مارا، وہ نبی کریم صلی اللہ علیہ وسلم کے پاس شکایت لے کر گئیں، آپ صلی اللہ علیہ وسلم نے فرمایا: قصاص ہے، تو یہ آیت نازل ہوئی۔ میں نے دوسرے دو اقوال کا ذکر کیا ہے جن کے بارے میں آیت نازل ہوئی اور کلبی نہایت کمزور راوی ہے۔","",{"fn":"(1) سورة النساء الآية ۳۴"}],[10147,"§۱۱۵۳۸ ۔ عمیرہ بنت مرثد\n(1) بن جبیر بن مالک انصاریہ، اسماء کی بہن ہیں: ابن سعد کا قول ہے: اسلام لائیں اور بیعت کی، سلامہ بنت مسعود بن کعب ان کی والدہ ہیں، سوید بن نعمان سے ان کا نکاح ہوا۔","",{"fn":"(1) تجرید (۲۹۱/۲)"}],[10148,"§۱۱۵۳۹ ۔ عمیرہ بنت مسعود الانصاریہ\n(1) ابونعیم اور ابوموسیٰ نے اپنے طریق سے اس کا ذکر کیا ہے۔ پھر ابوعروبہ حرانی کے طریق سے، وہ فرماتے ہیں: ہم سے ہلال بن بشر نے بیان کیا۔ وہ فرماتے ہیں: ہم سے اسحاق بن ادریس نے بیان کیا، وہ فرماتے ہیں ہم سے ابراہیم بن جعفر بن محمود بن محمد بن سلمہ نے بیان کیا کہ ان کی دادی عمیرہ بنت مسعود نے ان سے بیان کیا کہ وہ اور ان کی پانچ بہنیں رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں۔ انہوں نے آپ صلی اللہ علیہ وسلم سے بیعت کی، دیکھا کہ آپ صلی اللہ علیہ وسلم گوشت کھا رہے ہیں آپ صلی اللہ علیہ وسلم نے ان کے لیے گوشت چبایا اور پھر انہیں دیا جسے انہوں نے آپس میں تقسیم کر لیا، اور ہر ایک نے وہ بوٹی چبائی، مرتے دم تک ان کے منہ سے بد بو پیدا نہیں ہوئی اور نہ انہیں منہ کی کوئی بیماری پیدا ہوئی۔(2)","",{"fn":"(1) اسد الغابة (۷۱۴۵)، تجرید (۲۹۱/۲)\n(2) المعجم الكبير (۸۵۲/۲۴)، مجمع الزوائد (۲۸۳/۸)، جامع المسانيد والسنن (۶۲۱/۱۵)"}],[10149,"§۱۱۵۴۰ ۔ عمیرہ بنت معاذ الانصاریہ\nروح بن ثابت کی زوجہ ہیں جو نبی کریم صلی اللہ علیہ وسلم کے کاتب ہیں، ان کا ذکر گزر چکا ہے۔"],[10150,"§۱۱۵۴۱ ۔ عمیرہ بنت معوذ\nبن عفراء، ربیع کی بہن ہیں، ابن سعد نے بیعت کرنے والی خواتین میں ان کا ذکر کیا ہے، ان کا نسب ان کے والد کا نام ربیع کے سوانح میں گزر چکا ہے، ابن سعد فرماتے ہیں: ان سے ابو حسن بن عبد عمرو مازنی نے نکاح کیا، جس سے عمارہ، عمر اور شتر یہ پیدا ہوئے۔"],[10151,"§۱۱۵۴۲ ۔ عمیرہ بنت یزید\n(1) بن سکن ابن رافع بن امری القیس بن زید بن عبدالاشہل اشہلیہ، ابن سعد(2) نے ان کا ذکر کیا ہے اور فرمایا: اسلام لائیں اور بیعت کی، ان کی والدہ ام سعد بنت حرام بن مسعود ہیں۔ ان سے منظور بن لبید بن عقبہ نے نکاح کیا، جس سے حارث اور عشیرہ پیدا ہوئے۔","",{"fn":"(1) اسد الغابة (۷۱۳۰)، (۳۴۹۰)، تجرید (۲۹۰/۲)\n(2) الطبقات الكبرى (۲۳۳/۸)"}],[10152,"§۱۱۵۴۳ ۔ عنبہ (بے نسبت)\n(1) ابو نعیم نے ان کا ذکر کیا ہے اور ابوبکر مقری کے حوالے سے محمد بن قارن سے، انہوں نے ابوزرعہ سے، انہوں نے غسان بن فضل سے روایت کیا ہے، وہ فرماتے ہیں: ہم سے صبیح بن سعید نجاشی ۱۸۰ھ میں روایت کیا ہے۔ ان کا گمان ہے کہ وہ ۱۵۷ھ تک کا سن رکھتے ہیں میں نے اپنی والدہ سے فرماتے ہوئے سنا: ان کا نام عنبہ تھا، بدل کر رسول اللہ صلی اللہ علیہ وسلم نے عنقودہ(2) رکھ دیا۔ خطیب نے اسے مؤتلف میں دوسری سند سے بحوالہ محمد بن قارن نقل کیا ہے، صبیح مذکورہ جو راوی ہے یحیی بن معین نے اسے جھوٹا کہا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۴۶)، تجرید (۲۹۱/۲)\n(2) جامع المسانيد السنن (۶۲۱/۱۵)"}],[10153,"§۱۱۵۴۴ ۔ عنقودہ\n(1) پہلے والے میں گزر چکی ہیں۔","",{"fn":"(1) اسد الغابة (۷۱۴۶)، تجرید (۲۹۱/۲)"}],[10154,"§۱۱۵۴۵ ۔ عُنقودہ\n(1) دوسری ہیں، سیدہ عائشہ رضی اللہ عنہا کی لونڈی ہیں۔ ابوموسی نے ذیل میں مستغفری کے حوالے سے ان کا ذکر کیا ہے، فرمایا: ان کی حدیث کی اسناد میں تردد ہے۔ یزید بن قیس بن جراح کے طریق سے بحوالہ صبیح، انہوں نے علی بن حمید سے، انہوں نے اپنے والد حمید بن حوشب سے، انہوں نے حسن سے، انہوں نے علی سے روایت کی، فرماتے ہیں: جب رسول اللہ صلی اللہ علیہ وسلم نے سیدنا معاذ رضی اللہ عنہ کو یمن کی طرف بھیجنے کا ارادہ کیا تو فرمایا: یمن کے لیے کون تیار ہے؟ سیدنا ابوبکر رضی اللہ عنہ نے عرض کیا: میں، آپ صلی اللہ علیہ وسلم خاموش ہو گئے، آپ صلی اللہ علیہ وسلم نے پھر فرمایا: یمن کے لیے کون تیار ہے؟ سیدنا معاذ رضی اللہ عنہ نے عرض کیا: میں، آپ صلی اللہ علیہ وسلم نے فرمایا: تم اس کے لیے ہو اور وہ تمہارے لیے ہے، انہوں نے سامان تیار کیا اور آپ علیہ السلام نے انہیں الوداع کرتے ہوئے فرمایا: اے معاذ! میں تمہیں اللہ تعالیٰ سے ڈرنے، حسن عمل، کلام کی نرمی، سچی بات کرنے، اور امانت کی ادائیگی کی وصیت کرتا ہوں، اے معاذ! آسانی پیدا کرو، مشکل پیدا نہ کرنا۔ پھر نبی کریم صلی اللہ علیہ وسلم کی وفات اور سیدنا معاذ رضی اللہ عنہ کے یمن سے لوٹنے مدینہ داخل ہونے اور نبی کریم صلی اللہ علیہ وسلم کے گھر رات کے وقت آنے کے بارے میں طویل حدیث ذکر کی، اور یہ کہ انہوں نے دروازہ کھٹکھٹایا تو سیدہ عائشہ رضی اللہ عنہا نے فرمایا: یہ کون ہے جو رات کو ہمارے دروازے پر دستک دے رہا ہے؟ انہوں نے فرمایا: میں معاذ ہوں، سیدہ عائشہ رضی اللہ عنہا نے کہا: اے عنقودہ! دروازہ کھولو(2)...... پھر انہوں نے نبی کریم صلی اللہ علیہ وسلم کی وفات کے بارے میں طویل حدیث ذکر کی۔ ابوموسیٰ فرماتے ہیں: حدیث ابن عمر سے طوالات میں املا کراتی ہے۔ لیکن سیدہ عائشہ رضی اللہ عنہا کی لونڈی کا نام عُنفیرہ لیا ہے، تجرید(3) میں فرماتے ہیں: یہ حدیث منکر ہے، اور پہلی اولی ہیں۔ میں کہتا ہوں: اس میں کوئی شک نہیں کہ یہ گھڑی ہوئی ہے، اس میں رکیک الفاظ ہیں جو سیدنا معاذ رضی اللہ عنہ اور عمار، عائشہ فاطمہ، حسین رضی اللہ عنہم کی طرف منسوب ہیں۔ اس میں ہے کہ سیدنا معاذ رضی اللہ عنہ نے سیدہ عائشہ رضی اللہ عنہا سے پوچھا: آپ نے نبی کریم صلی اللہ علیہ وسلم کو بیماری اور وفات میں کیسا پایا، وہ کہنے لگیں: اے معاذ! میں آپ صلی اللہ علیہ وسلم کی وفات کے وقت موجود نہ تھی، یہ فاطمہ ہیں ان سے پوچھ لو، اس میں ہے: سیدنا معاذ رضی اللہ عنہ نے رات کے وقت غیبی آواز سنی” اے معاذ! تمہیں کیسے میٹھی نیند آتی ہے، اور محبوب نبی حضور محمد صلی اللہ علیہ وسلم مٹی کی تہوں کے درمیان ہیں۔ (یعنی لحد میں) سیدنا معاذ رضی اللہ عنہ نے اپنا ہاتھ اپنے سر پر رکھا، اور صنعاء کی گلیوں میں پھرنے لگے، وہ کہہ رہے تھے، اے اہل یمن! مجھے چھوڑو! مجھے تمہارے پڑوس کی ضرورت نہیں، وہ برے دن ہیں جو تمہارے پڑوس میں گزرے، مجھ سے میرے حبیب محمد صلی اللہ علیہ وسلم جدا ہو گئے ہیں، پھر صبح کے وقت سواری پر بیٹھے اور قسم کھائی کہ سوائے نماز کے اوقات کے اس سے نہ اتریں گے یہاں تک کہ مدینہ جا پہنچیں۔","",{"fn":"(1) اسد الغابة (۷۱۴۷)، تجرید (۲۹۱/۲)\n(2) اتحاف السادة المتقين (۲۶۱/۶)\n(3) اسد الغابة (۷۱۴۸)، تجرید (۲۹۲/۲)"}],[10155,"§۱۱۵۴۶ ۔ العوراء بنت ابی جھل\nیہ وہی ہیں جنہیں سیدنا علی رضی اللہ عنہ نے نکاح کا پیغام دیا، حکیم ترمذی فرماتے ہیں: جزء ثانی میں ابو رزق ہمدانی کی حدیث میں ان کا ذکر پہلے گزر چکا ہے کہ ان کا نام جوہریہ ہے، ہو سکتا ہے عوراء ان کا لقب ہو۔"],[10156,"§۱۱۵۴۷ ۔ غویش\nنبی کریم صلی اللہ علیہ وسلم نے ام المؤمنین سیدہ عائشہ رضی اللہ عنہا کو اس نام سے مخاطب کیا تھا۔ طبرانی نے عشرہ میں اسے مسلم بن یسار کے طریق سے نقل کیا ہے، فرماتے ہیں: مجھے یہ بات پہنچی ہے کہ نبی کریم صلی اللہ علیہ وسلم سیدہ عائشہ رضی اللہ عنہا کے پاس تشریف لائے اور فرمایا: “اے غویش! کیا وجہ ہے کہ تمہارا چہرہ بہت روشن ہے۔”۔۔۔۔۔ الحديث"],[10157,"§۱۱۵۴۸ ۔ غُوَیمرہ بنت غُوَیم\n(1) بن ساعدہ انصاریہ: ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) التجرید (۱۹۲)"}],[10158,"§۱۱۵۴۹ ۔ غَیساء بنت الحارث الانصاریہ\n(1) انس بن فضالہ کی زوجہ ہیں: ابن سعد(2) نے ان کا ذکر کیا ہے۔ تجرید میں بھی غویمرہ کے بعد ان کا ذکر ہے۔","",{"fn":"(1) تجرید (۲۹۲/۲)\n(2) الطبقات الکبریٰ (۲۵۰/۸)"}],[10159,"§۱۱۵۵۰ ۔ عائشہ بنت سعد\nاور عائشہ بنت شیبہ اور عائشہ بنت معاویہ، عبیدہ بنت صعصعہ بن ناجیہ تمیمیہ، فرزدق کی پھوپھی ہیں، ام حمزہ ہیں، زبرقان بن بدر کی زوجہ ہیں، کتاب ابو الفرج میں حطیہ کے سوانح میں ان کا ذکر ہے، یہ وہی ہیں کہ زبرقان نے حطیہ کو ان کے فروکش ہونے کو کہا تھا یہاں تک کہ وہ سفر سے واپس آ جائیں۔ لیکن انہوں نے کوتاہی کی جو حطیہ کی طرف سے زبرقان کی ہجو کا سبب بنا۔"],[10160,"§۱۱۵۵۱ ۔ عمرہ بنت درید\nبن صمہ: فرماتی ہیں: انہوں نے اپنے والد کا مرثیہ کہا: ربیعہ بن رفیع جو ابن دغنیہ کے نام سے مشہور ہے اس نے انہیں قتل کیا۔ اللہ تعالیٰ میری طرف سے بنی سلیم کو ان کے کیے کا بدلہ دے کہ یہ اپنے والدین کے نافرمان بیٹے ہیں۔ اور ملاقات کے وقت جب ہم ان سے قصاص لیں تو ان کے بہترین لوگوں کا خون پلائے۔(1)","",{"fn":"(1) الأغانی (۳۳۲/۱۰)"}],[10161,"§۱۱۵۵۲ ۔ عائشہ بنت عجرہ\n(1) اسد الغابہ میں یہ نام عائشہ بنت عجر دکھا ہے۔ ہم وہیں سے نقل کرتے ہیں۔ یحییٰ بن معین کا قول ہے کہ صاحب قیاس و فقہ ابوحنیفہ نے عائشہ سے سنا فرماتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: زمین میں اللہ تعالیٰ کا سب سے بکثرت لشکر ٹڈیاں ہیں (جو فصلیں کھاتی ہیں جن کی لمبائی تقریباً تین انچ سے پانچ انچ تک ہوتی ہے، جسے “ٹڈی دل” بھی کہا جاتا ہے، اس سے مراد گھروں میں پائی جانے والی زہریلی ٹڈیاں نہیں ہیں) نہ میں انہیں کھاتا ہوں اور نہ حرام قرار دیتا ہوں۔ ان کی روایت بواسطہ ابوحنیفہ عثمان بن راشد بواسطہ عائشہ بنت عجر بحوالہ ابن عباس رضی اللہ عنہما نقل کی گئی ہے۔ اکثر علماء نے تابعات میں ان کا ذکر کیا ہے۔ ابوموسیٰ نے ان کا تذکرہ کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۰۹۰)"}],[10162,"§۱۱۵۵۳ ۔ غاثنہ\n(1) ابن مندہ کا قول ہے: ابن وہب نے بحوالہ عثمان بن عطاء خراسانی انہوں نے اپنے والد سے نقل کیا ہے کہ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں اور کہنے لگیں: میری والدہ وفات پا گئی ہیں اور انہوں نے کعبے کی طرف پیدل جانے کی نذر مانی تھی، آپ صلی اللہ علیہ وسلم نے فرمایا: “ان کی طرف سے نذر پوری کرو۔”(2)","",{"fn":"(1) اسد الغابۃ (۷۱۴۹) الاستيعاب (۳۴۹۳) تجرید (۲۹۲/۲)\n(2) اسد الغابۃ (۳۵۶/۵)"}],[10163,"§۱۱۵۵۴ ۔ غزیلہ\nبعض کا قول ہے: غزیہ، ام شریک ہیں اور اپنی کنیت سے معروف ہیں، کنیتوں میں ان کے حالات آئیں گے، ابن سعد رحمہ اللہ نے بحوالہ واقدی رحمہ اللہ، سلیمان بن یسار سے مرسلاً نقل کیا ہے، فرماتے ہیں: جب نبی کریم صلی اللہ علیہ وسلم نے کندیہ سے نکاح کیا، عامریہ خواتین کے ہاں نکاح کا پیغام بھیجا، ام شریک غزیہ بنت جابر نے اپنے آپ کو آپ صلی اللہ علیہ وسلم کو ہبہ کر دیا، آپ صلی اللہ علیہ وسلم کی ازواج کہنے لگیں: اگر آپ صلی اللہ علیہ وسلم نے خاندان سے باہر شادی کی تو آپ صلی اللہ علیہ وسلم کو ہماری حاجت نہیں ہو گی۔۔۔۔۔ الحديث"],[10164,"§۱۱۵۵۵ ۔ غفیرہ\n(1) بنت رباح، سیدنا بلال رضی اللہ عنہ (جو مؤذن ہیں) اور ان کے بھائی خالد کی بہن ہیں۔ مستغفری نے ان کا ذکر کیا ہے اور فرمایا: وہ دو بھائی اور ایک بہن ہے، یہ بخاری کا قول ہے، طحاوی میں اسناد کے درمیان ہے: بحوالہ عمیر مولیٰ غفیرہ بنت رباح جو سیدنا بلال رضی اللہ عنہ کی بہن ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۱۵۱)، تجرید (۲۹۲)"}],[10165,"§۱۱۵۵۶ ۔ غفیرہ\nعنقودہ میں گزر چکی ہیں۔"],[10166,"§۱۱۵۵۷ ۔ غفیلہ\nاسی طرح ہیں، لیکن راء کے بدلے لام کے ساتھ، عین مہملہ میں ان کا ذکر گزر چکا ہے۔"],[10167,"§۱۱۵۵۸ ۔ الغمیصاء بنت ملحان الانصاریہ\n(1) بعض کا قول ہے: ام سلیم، سیدنا انس رضی اللہ عنہ کی والدہ ہیں۔ وہ اپنی کنیت سے مشہور ہیں: امام احمد(2) نے اپنی مسند میں فرمایا: ہم سے یحییٰ قطان نے، وہ فرماتے ہیں: ہم سے حمید نے بحوالہ انس رضی اللہ عنہ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا، فرمایا: میں جنت میں داخل ہوا تو میں نے چلنے کی آواز سنی، میں نے کہا: یہ کون ہے، تو فرشتے نے کہا: “غمیصاء بنت ملحان”۔ میں کہتا ہوں: حرف راء میں دوسری سند سے بحوالہ انس یہ گزر چکا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۵۴)، تجرید (۲۹۲/۲)\n(2) مسند احمد (۱۲۵/۳)"}],[10168,"§۱۱۵۵۹ ۔ الغمیصاء\n(1) یا رمیصاء، عمرو بن حزم کی زوجہ ہیں: ابو نعیم نے حماد بن سلمہ کے طریق سے بحوالہ ہشام بن عروہ، انہوں نے اپنے والد سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے نقل کیا ہے: کہ عمرو بن حزم نے غمیصاء کو طلاق دی، ان سے ایک شخص نے نکاح کیا اور مس کرنے سے پہلے طلاق دے دی، وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں اور پوچھا کہ کیا وہ پہلے شوہر کی طرف لوٹ سکتی ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: یہاں تک کہ دوسرا ان کا........(2) الحدیث۔ ابو موسیٰ فرماتے ہیں: یہ ام سلیم کے علاوہ کوئی اور ہیں: ابن عباس رضی اللہ عنہما نے ابوموسیٰ سے حدیث روایت کی، فرمایا: غمیصاء یا رمیصاء ہیں، اور ان کے شوہر کا نام نہیں لیا۔(3) ابن مندہ نے ام سلیم کے سوانح میں حدیث نقل کی ہے، ابن اثیر فرماتے ہیں: ابوموسیٰ کا قول درست ہے۔ میں کہتا ہوں: حرف راء میں سیدنا ابن عباس رضی اللہ عنہما کی حدیث گزر چکی ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۵۵)، تجرید (۲۹۲/۲)\n(2) مسند احمد (۳۷/۶) المعجم الکبیر (۸۶۹/۲۴)\n(3) مسند احمد (۲۱۴/۱) مسند ابویعلیٰ (۶۷۱۸) مجمع الزوائد (۳۴۰/۴)"}],[10169,"§۱۱۵۶۰ ۔ غنیہ بنت ابی اہاب\nیہ ام یحییٰ ہیں، جن سے عقبہ بن حارث نوفلی نے نکاح کیا، ان سے ایک حبشی باندی نے کہا، میں نے تم دونوں کو دودھ پلایا ہے، جیسا کہ کنیتوں میں آئے گا۔"],[10170,"§۱۱۵۶۱ ۔ فاختہ بنت الاسود\n(1) بن مطلب بن اسد بن عبدالعزیٰ قریشیہ اسدیہ: صفوان بن امیہ بن خلف کی زوجہ تھیں، اپنے باپ کے بعد ان سے نکاح کیا، اسلام نے ان دونوں کے درمیان جدائی کرا دی۔ مستغفری نے محمد بن ثور کے طریق سے بحوالہ ابن جریج نقل کیا ہے، فرمایا: اسلام نے چار عورتوں اور ان کے خاوند کے بیٹوں کے درمیان جدائی کرائی، پھر ان کا ذکر کیا۔(2)","",{"fn":"(1) اسد الغابۃ (۷۱۵۶)، تجرید (۲۹۲/۲)\n(2) طبری فی تفسیرہ (۱۳۳/۸)، تفسیر ابن کثیر (۲۱۴/۱۲)"}],[10171,"§۱۱۵۶۲ ۔ فاختہ بنت خارجہ\nبن زید بن ابو زہیر انصاریہ، ابوبکر صدیق کی زوجہ ہیں: دار قطنی نے کتاب الاخوہ میں ان کا نام لیا ہے۔ یہ ابوبکر رضی اللہ عنہ کے اس قول سے مراد ہیں جو انہوں نے اپنی وفات کے وقت سیدہ عائشہ رضی اللہ عنہا سے فرمایا: بطن والی خارجہ کی بیٹی ہے۔ بعض کا قول ہے: کہ ان کا نام حبیبہ ہے۔"],[10172,"§۱۱۵۶۳ ۔ فاختہ بنت ابی احیحہ\n(1) سعد بن العاص بن امیہ، ابوالعاص بن ربیع کی زوجہ ہیں۔ نبی کریم صلی اللہ علیہ وسلم کی صاحبزادی سیدہ زینب رضی اللہ عنہا کے بعد ان سے نکاح کیا، جس سے ان کی بیٹی مریم پیدا ہوئیں، زبیر نے ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۲۹۲/۲)"}],[10173,"§۱۱۵۶۴ ۔ فاختہ بنت ابی طالب\nبن عبد المطلب بن ہاشم ہاشمیہ، ام ہانی ہیں، سیدنا علی رضی اللہ عنہ کی بہن ہیں اور اپنی کنیت سے معروف ہیں، بعض کا قول ہے، ان کا نام ہند ہے، پہلا نام مشہور ہے۔"],[10174,"§۱۱۵۶۵ ۔ فاختہ بنت قرظہ\nبن عبد عمرو بن نوفل بن عبد مناف قرشیہ، نوفلیہ، معاویہ بن ابو سفیان کی زوجہ ہیں، ان کے والد کا صحابہ میں تذکرہ نہیں، وہ جاہلیت میں فوت ہوئے، ہونا تو یہ چاہیے تھا کہ ان کا تذکرہ عہد نبوی صلی اللہ علیہ وسلم میں ہوتا اور ان کے قریبی بچوں کو شرف صحابیت حاصل ہوتا۔ زبیر بن بکار نے نسبت میں ذکر کیا ہے کہ امیر معاویہ رضی اللہ عنہ نے کنود بن قرظہ مذکور سے نکاح کیا تھا پھر ان کی بہن فاختہ سے نکاح کیا۔ امیر معاویہ کے سوانح میں ان کے والد قرظہ کے کئی واقعات مذکور ہیں ان میں سے ایک یہ کہ انہوں نے ان کے ساتھ غزوہ قبرس میں شرکت کی، یہ صحیح میں سیدہ ام حرام کی حدیث میں ہے جو سیدنا انس رضی اللہ عنہ کی خالہ ہیں، مجھے معلوم نہیں یہ دونوں بہنوں میں سے کون سی ہیں۔"],[10175,"§۱۱۵۶۶ ۔ فاختہ بنت عمرو الزہریہ\n(1) نبی کریم صلی اللہ علیہ وسلم کی خالہ ہیں: طبرانی رحمہ اللہ نے عبدالرحمن بن عثمان وقاصی کے طریق سے بحوالہ ابن المنکدر، انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کیا ہے: فرماتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: میں نے اپنی خالہ فاختہ بنت عمرو کو ایک خدمت گار لڑکا ہبہ کرتے ہوئے کہا کہ اسے قصاب، سنار اور سینگی لگانے والا نہ بنانا۔(2) وقاصی ضعیف راوی ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۵۸)، تجرید (۲۹۲/۲)\n(2) المعجم الکبیر (۱۰۷۳/۲۴) مجمع الزوائد (۹۳/۴)"}],[10176,"§۱۱۵۶۷ ۔ فاختہ بنت غزوان\nعقبہ کی بہن ہیں: جن کے سوانح میں ان کا نسب گزر چکا ہے، ہجرت کرنے والی صحابیات میں سے ہیں۔"],[10177,"§۱۱۵۶۸ ۔ فاختہ بنت الولید\n(1) بن مغیرہ مخزومیہ، خالد بن ولید کی بہن ہیں، ان کے سوانح(2) میں ان کا نسب گزر چکا ہے، صفوان بن امیہ کی زوجہ ہیں، فتح کے دن اسلام لائیں اور بیعت کی، ابو عمر(3) کا قول ہے: اپنے شوہر کے اسلام لانے سے ایک ماہ پہلے اسلام لائیں، یہ داؤد بن حصین کا قول ہے، ابن مندہ فرماتے ہیں: ان کا ذکر ہے لیکن حدیث مروی نہیں۔ ابو نعیم نے ابراہیم بن سعد کے طریق سے بحوالہ ابن اسحاق انہوں نے عبدالعزیز بن عبدالرحمن امامی سے، انہوں نے زہری سے نقل کیا ہے، فرماتے ہیں: سیدہ فاختہ بنت ولید صفوان بن امیہ کی زوجہ تھیں، اور ام حکیم بنت حارث عکرمہ کی زوجہ تھیں، فتح کے دن(4) دونوں اسلام لائیں۔","",{"fn":"(1) اسد الغابۃ (۷۵/۹)، الاستيعاب (۳۴۹۵)، تجرید (۲۹۳/۲)\n(2) مجمع الزوائد (۹۳/۴)\n(3) الاستيعاب (۱۸۸۹/۴)\n(4) اسد الغابۃ (۳۵۹/۵)"}],[10178,"§۱۱۵۶۹ ۔ فارعہ بنت ابی امامہ\n(1) سعد بن زرارہ انصاریہ، ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے، بعض کا قول ہے: ان کا نام فریعہ ہے، ان کی بیٹی زینب بنت نبط کے سوانح میں ان کا ذکر گزر چکا ہے، جو انس بن مالک کی زوجہ ہیں۔ ابو عمر(2) فرماتے ہیں: ابو امامہ نے اپنی بیٹیوں فارعہ، حبیبہ اور کبشہ کو نبی کریم صلی اللہ علیہ وسلم کے پاس جانے کی وصیت کی، رسول اللہ صلی اللہ علیہ وسلم نے فارعہ کی شادی نبیط بن جابر سے جو بنو مالک بن نجار سے ہیں، کر دی۔ ابن مندہ نے ابراہیم بن محمد بن ابو یحییٰ سے بحوالہ محمد بن عمارہ بن عمرو بن حزم نقل کیا ہے، کہ انہوں نے زینب بنت نبیط سے جو سیدنا انس رضی اللہ عنہ کی زوجہ ہیں سنا، وہ اپنی والدہ فریعہ بنت ابو امامہ سے روایت کرتی ہیں، فرماتی ہیں: نبی کریم صلی اللہ علیہ وسلم کے پاس سونے کے زیور، رعاث آئے، آپ صلی اللہ علیہ وسلم نے میری دو بہنوں حبیبہ اور کبشہ کو اس میں سے پہنائے، اور اس سے زکوۃ نہیں لی گئی، ابن سعد(3) فرماتے ہیں: ان کی والدہ عمیرہ بنت سھل ہیں، سیدہ فریعہ سیدنا اسعد بن زرارہ کی بیٹیوں میں بڑی تھیں جب بڑی ہوئیں، نبیط بن جابر نے انہیں نکاح کا پیغام دیا، جب ان کی رخصتی ہوئی تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: “کہو ہم تمہارے پاس آئے تم یتیم پر سلامتی بھیجو، ہم تمہارے اوپر سلامتی بھیجتے ہیں۔” سیدنا نبیط کا ان سے بیٹا عبدالملک پیدا ہوا۔ رسول اللہ صلی اللہ علیہ وسلم نے اس کا نام رکھا اور برکت کی دعا دی، سیدہ فریعہ بیعت کرنے والی صحابیات میں سے ہیں، ابن اثیر(4) نے معافی بن عمران کے طریق سے نقل کیا ہے، کہ انہوں نے اپنی تاریخ میں بحوالہ ابو عقیل جو نھیہ والے ہیں، انہوں نے نہیہ سے بحوالہ سیدہ عائشہ رضی اللہ عنہا روایت کیا ہے، فرماتی ہیں: ہم نے انصار میں سے ایک یتیمہ لڑکی کی رخصتی کی، جب ہم واپس آئے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “تم نے کیا؟” ہم نے کہا: ہم نے سپرد کیا اور لوٹ آئے، آپ صلی اللہ علیہ وسلم نے فرمایا: “انصار کو ترنم پسند ہے، اے عائشہ، تم نے یہ کیوں نہیں کیا: ہم تمہارے پاس آئے، ہم تمہارے پاس آئے، ہم پر اور تم پر سلامتی ہو۔”(5) میں کہتا ہوں: یہ فریعہ فارعہ بنت اسعد بن زرارہ ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۱۶۰)، الاستيعاب (۳۴۹۶) تجرید (۲۹۳/۲)\n(2) الاستيعاب (۱۸۸۹/۴)\n(3) الطبقات (۳۲۲/۸)\n(4) اسد الغابۃ (۳۵۹/۵)\n(5) ابن ماجہ (۱۹۰۰)، مسند احمد (۷۷/۴) (۷۸) مجمع الزوائد (۲۸۹/۴) زبیدی (۴۹۳/۶)"}],[10179,"§۱۱۵۷۰ ۔ فارعہ بنت ثابت\nبن منذر بن حرام انصاریہ، بنو نجار سے ہیں سیدنا حسان بن ثابت رضی اللہ عنہ جو شاعر رسول اللہ صلی اللہ علیہ وسلم ہیں، ان کی بہن ہیں، ابو حسن مدائنی نے ذکر کیا ہے کہ طویس نے عبد اللہ بن جعفر کے سامنے ایک شعر گنگنا کر کہا:............ یہ شعر کس کا ہے؟ کہنے لگے: فارعہ جو حسان کی بہن ہیں، اور عبدالرحمن بن حارث بن ہشام کے بارے میں ہے۔ میں کہتا ہوں: ان کے والد جاہلیت میں وفات پا گئے تھے اور عبدالرحمن بن حارث نبی کریم صلی اللہ علیہ وسلم کے زمانے میں کمسن تھے جیسا کہ ان کے سوانح میں گزر چکا ہے۔ لہذا ان کے متعلق تو شعر نہیں کہے جا سکتے ہاں جب وہ بالغ ہو گئے ہوں، اس لئے فارعہ اس قسم میں شامل ہے۔"],[10180,"§۱۱۵۷۱ ۔ فارعہ بنت زرارہ\n(1) بن عدی بن حرام انصاریہ، بنو مالک بن نجار سے ہیں، ابو موسیٰ نے یہ ذیل میں کہا، اسی طرح ابن اثیر(2) کا قول ہے۔ ذیل میں جو خط صریفینی میں ہے میں نے انہیں نہیں دیکھا، ممکن ہے جو ان سے پہلے ہیں وہ ان کے دادا کی طرف منسوب ہوں پھر مجھے معلوم ہوا کہ وہ ان کی پھوپھی ہیں۔ ابن سعد(3) کا قول ہے: الفارعہ، وہ فریعہ بنت زرارہ بن عدس بن عبید بن ثعلبہ بن غنم بن مالک بن نجار ہیں، ابو امامہ جو اسعد بن زرارہ ہیں ان کی سگی بہن ہیں، ان سے قیس بن عھد بن قیس بن ثعلبہ نے نکاح کیا، اسلام لائیں اور بیعت کی۔","",{"fn":"(1) اسد الغابۃ (۷۱۶۱)، الاستيعاب (۷۱۶۹)\n(2) اسد الغابۃ (۳۵۹/۵)\n(3) الطبقات (۳۲۱/۸)"}],[10181,"§۱۱۵۷۲ ۔ فارعہ بنت ابی سفیان\n(1) بن حرب بن امیہ امویہ: مستغفری نے ان کا ذکر کیا ہے، اور انس بن بکیر کے طریق سے بحوالہ ابن اسحاق نقل کیا ہے۔ فرماتے ہیں: سب سے پہلے حبشہ کی طرف ہجرت کرنے والے عبداللہ بن جحش ہیں جو بنو عبد شمس کے حلیف ہیں، انہوں نے اپنے گھر والوں اور بہن کے ساتھ ہجرت کی، ان کے پاس فارعہ بنت ابو سفیان بن حرب تھیں۔(2)","",{"fn":"(1) اسد الغابۃ (۷۱۶۲)، الاستيعاب (۷۱۷۰)، تجرید (۲۹۳/۲)\n(2) المعجم الکبیر (۲۱/۹)، السیرۃ النبویۃ (۸۶/۲)"}],[10182,"§۱۱۵۷۳ ۔ الفارعہ بنت ابی الصلت\n(1) امیہ بن ابو الصلت کی بہن ہیں، جو مشہور شاعر ہے، ابو عمر کا قول ہے، فتح طائف(2) کے بعد نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں وہ بڑی عقلمند پاکدامن اور حسین و جمیل خاتون تھیں، ان کے آنے سے آپ علیہ السلام خوش ہوتے تھے ایک دن ان سے فرمایا: کیا تمہیں اپنے بھائی کے کوئی اشعار یاد ہیں؟ چنانچہ انہوں نے ان کے بارے میں اور جو کچھ ان کے متعلق دیکھا، اور ان کے پیٹ چاک ہونے کا قصہ آپ علیہ السلام سے بیان کیا کہ وہ سو رہا تھا کہ اس کا دل نکال کر دوبارہ اس کے سینہ میں رکھ دیا گیا اور اس کے وہ اشعار سنائے جن کا مطلع یہ ہے۔ “میری پریشانیاں رات کے وقت گردش کرتی ہیں میں اپنی آنکھوں کو روکتا ہوں لیکن ان کے آنسو پہلے بہہ پڑتے ہیں۔ دل کو چاہے جتنی جینے کی آرزو ہو تھوڑا بہت جی بھی لے موت اس کے پیچھے لگی ہوئی ہے۔” یہ تقریباً تیرہ(۱۳) اشعار ہیں جن میں وہ کہتے ہیں: “جو شخص اپنی موت سے گریزاں ہے وہ کسی نہ کسی دھوکے سے اسے جا ملے گا۔ جو جوانی میں نہ مرا بڑھاپے میں جا مرے گا۔ موت ایسا پیالہ ہے جسے ہر شخص چکھنے والا ہے۔” اس نے معاینہ کے وقت یہ اشعار کہے تھے: “ہر زندگی خواہ اس کا دن لمبا ہو جائے ایک نہ ایک دن ختم ہونے والی ہے۔ کاش! جو کچھ میں نے دیکھا اس سے پہلے میں پہاڑوں کی چوٹیوں پر بکریاں چرا رہا ہوتا۔” رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: تمہارے بھائی کی مثال اس شخص کی سی ہے “اس شخص کا حال بیان کرو جسے ہم نے اپنی آیات کا علم دیا پھر وہ ان سے نکل گیا۔”(3) ابو عمر(4) فرماتے ہیں: میں نے اسے مختصر بیان کیا ہے اس کے چند نکات پر اکتفا کیا ہے پھر بسند وہیمہ بن موسیٰ بواسطہ سلمہ بن فضل، ابن اسحاق، ابن شہاب بحوالہ سعید بن المسیب روایت کی ہے کہ فارعہ آئیں۔ پھر مکمل روایت ذکر کی۔ میں کہتا ہوں: یہ قصہ ابو نعیم نے بطریق ثعلب بحوالہ ابن الاعرابی نقل کیا ہے کہ ابن اسحاق نے اسی سند سے اسی مفہوم کی روایت بیان کی ہے۔ ابن ابو عاصم(5) اور ابن مندہ نے اسے ابراہیم بن محمد بن یحییٰ سجری کے طریق سے بحوالہ اپنے والد، انہوں نے ابن اسحاق سے انہوں نے زہری سے، انہوں نے عبید اللہ بن عبداللہ سے، انہوں نے ابن اسحاق سے اسے نقل کیا ہے: کہ فارعہ بنت ابی الصلت ثقفی نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں تو آپ صلی اللہ علیہ وسلم نے ان سے ان کے والد اور بھائی کے بارے میں دریافت فرمایا: کہنے لگیں: میرا بھائی سفر سے ہمارے پاس آیا، پھر چار پائی پر سو گیا، دو پرندے آئے ان میں سے ایک اس کے سینے پر گرا، تو اس کا سینے سے سرین تک جسم چاک ہو گیا پھر اس کی موت کا طویل قصہ ذکر کیا۔ میں کہتا ہوں: دونوں سندوں میں جو ابن اسحاق رحمہ اللہ تک پہنچتی ہے ضعیف ہے اور کتاب مکہ میں فاکہی نے طویل قصہ کلبی کے طریق سے بحوالہ ابو صالح، انہوں نے ابن عباس سے نقل کیا ہے۔ ثعلبی نے اسے اپنی تفسیر میں نقل کیا ہے اس میں ہے: انہوں نے نبی کریم صلی اللہ علیہ وسلم کے سامنے ان کے کئی قصائد پڑھے جس میں ان کے ایمان اور قیامت کی وضاحت ہوتی ہے، ایک قصیدہ میں ہے: “تمام لوگوں کو حساب کے لئے ٹھہرایا جائے گا، ان میں سے بدبخت کو عذاب دیا جائے گا اور نیک بخت ہوں گے۔” ایک قصیدہ میں ہے: “اے ہمارے رب! تیرے لئے تمام تعریف نعمتیں اور فضل ہے۔ بزرگی میں تجھ سے بڑھ کر اور کوئی نہیں، آسمان کے عرش کا مالک ہے، نگہبان ہے، اس کی عزت کے لئے چہرے جھکتے اور سجدہ کرتے ہیں۔” ایک قصیدہ میں ہے: “جس دن ہم رحمن کے دربار میں حاضر ہوں گے، وہ رحیم ذات ہے، اس کے وعدہ کا وقت آنے والا ہے۔ اگر جرائم کی وجہ سے میرا مواخذہ ہوا تو مجھے سخت عذاب کا سامنا کرنا پڑے گا۔ اے میرے رب! اگر تو مجھ سے درگزر کرے تو میرا گمان بھی عافیت والا ہے، اور اگر تو مجھے عذاب دینا چاہے تو کسی بری کو تو نے عذاب نہیں دیا۔” آپ صلی اللہ علیہ وسلم نے ان سے فرمایا: اس کے شعروں سے تو ایمان کا پتہ چلتا ہے لیکن اس کا دل کافر تھا، اس کے بارے میں یہ آیت نازل ہوئی: ان کے سامنے اس شخص کا حال بیان کرو جسے ہم نے اپنی آیات کا علم عطا کیا تھا لیکن وہ ان کی پابندی سے نکل بھاگا۔۔۔۔۔ الآیۃ","",{"fn":"(1) اسد الغابۃ (۷۱۶۳)، الاستيعاب (۳۴۹۷)، تجرید (۲۹۳/۲)\n(2) الاستيعاب (۱۸۸۹/۴)\n(3) سورۃ الاعراف ۱۷۵\n(4) استيعاب (۱۸۹۰/۴)\n(5) الاحاد والمثانی (۲۴۷/۶)"}],[10183,"§۱۱۵۷۴ ۔ فارعہ بنت عبد الرحمن الخثعمیہ\n(1) صحابہ میں ان کا تذکرہ ہے، ان سے سرمی بن عبد الرحمن نے روایت کی، استیعاب میں اسی طرح مذکور ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۶۴)، الاستيعاب (۳۴۹۸)، تجرید (۲۹۳/۲)"}],[10184,"§۱۱۵۷۵ ۔ فارعہ بنت عتبہ\nبن عبد شمس عبشمیہ، ہند کی بہن اور معاویہ کی خالہ ہیں، حبیب بن عمرو بن حمہ دوسی کی زوجہ تھیں، بلاذری نے ان کا ذکر کیا ہے۔"],[10185,"§۱۱۵۷۶ ۔ فارعہ بنت مالک\nسنان خدریہ: فریعہ کے سوانح میں ان کا ذکر آئے گا۔"],[10186,"§۱۱۵۷۷ ۔ فارعہ الجنیہ\nحمزہ بن یوسف جرجانی نے تاریخ جرجان میں ان کا ذکر کیا ہے، فرماتے ہیں: ہمیں ابو احمد بن عدی نے بتایا، وہ فرماتے ہیں کہ ہمیں عبد المؤمن بن احمد نے، وہ فرماتے ہیں: ہمیں جعفر بن حکم نے، وہ فرماتے ہیں: ہمیں نصیعہ بن عبد اللہ بن لہیعہ نے بحوالہ اپنے والد بیان کیا، انہوں نے ابو زبیر سے، انہوں نے سیدنا جابر رضی اللہ عنہ سے نقل کیا ہے: کہ ایک جنیہ خاتون نبی کریم صلی اللہ علیہ وسلم کے پاس اپنی قوم کی عورتوں کے ساتھ آتی تھی، ایک مرتبہ انہیں تاخیر ہو گئی تو تھوڑی دیر بعد وہ آ گئیں، آپ صلی اللہ علیہ وسلم نے فرمایا: تمہیں کس وجہ سے تاخیر ہوئی؟ کہنے لگیں: ہند کی سرزمین میں ہماری فوتگی ہو گئی میں اس کی تعزیت کرنے گئی تھی، میں نے اپنے راستے میں ابلیس کو ایک چٹان پر نماز پڑھتے ہوئے دیکھا میں نے کہا: تمہیں حضرت آدم علیہ السلام کو گمراہ کرنے پر کس چیز نے آمادہ کیا؟ ابلیس نے کہا: جاؤ اپنا کام کرو، میں نے کہا: نماز اور تم! اس نے کہا: ہاں اے فارعہ: ایک بندے کی بیٹی، میں اپنے رب سے امید رکھتا ہوں کہ جب وہ اپنی قسم پوری کرے گا تو مجھے بخش دے گا، اس سند میں نامعلوم راوی ہیں، ابن جوزی نے موضوعات میں اسے نقل کیا ہے۔"],[10187,"§۱۱۵۷۸ ۔ فاضلہ\n(1) عبد اللہ بن انیس کی زوجہ ہیں، ان کے نام میں اختلاف ہے، ان کا ذکر گزر چکا ہے، ابن مندہ نے بھی ان کا ذکر کیا ہے۔ ابو عمر(2) فرماتے ہیں: فاضلہ انصاریہ، عبداللہ بن انیس جہنی کی زوجہ ہیں، اہل مدینہ کے ہاں ان کی حدیث ہے۔ فرماتی ہیں: نبی کریم صلی اللہ علیہ وسلم نے ہمیں خطبہ دیا اور صدقہ کرنے کی ترغیب دی۔(3) میں کہتا ہوں: حسن بن سفیان نے اپنی مسند میں اسے نقل کیا ہے، موسیٰ بن عبیدہ ربذی کے طریق سے جو ضعیف راوی ہیں، بحوالہ ان کے بھائی محمد بن عبیدہ، انہوں نے اپنے بھائی عبداللہ بن عبیدہ سے، انہوں نے یحییٰ بن عبد اللہ بن کعب بن مالک سے، انہوں نے اپنی والدہ سے اور وہ عبد اللہ بن انیس جہنی کی بیٹی ہیں۔ انہوں نے اپنی والدہ سے جو فاضلہ انصاریہ ہیں، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں خطبہ دیا، اور صدقہ کی ترغیب دی، میں نے آپ صلی اللہ علیہ وسلم کے پاس اپنے زیور بھیجے، اور کہا: وہ اللہ عزوجل کی راہ میں صدقہ ہیں، آپ صلی اللہ علیہ وسلم نے اسے واپس کر دیا اور فرمایا: ”میں عورت کا صدقہ اس کے شوہر کی اجازت سے قبول کرتا ہوں“ میں نے اسے اپنے شوہر کے ساتھ بھیجا، انہوں نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم کیا یہ زیور اس کا ہے، اور والد کی وراثت سے حاصل ہوا ہے، آپ صلی اللہ علیہ وسلم نے اسے قبول کر لیا۔","",{"fn":"(1) اسد الغابۃ (۷۱۶۷)، الاستيعاب (۳۴۹۹)، تجرید (۲۹۳/۲)\n(2) الاستيعاب (۱۸۹۰/۴)\n(3) جامع المسانید والسنن (۷/۱۶)"}],[10188,"§۱۱۵۷۹ ۔ فاطمہ الزھراء\n(1) امام المتقین رسول اللہ صلی اللہ علیہ وسلم کی صاحبزادی، جن کا اسم گرامی محمد بن عبداللہ بن عبدالمطلب بن ہاشم ہاشمی صلی اللہ علیہ وسلم ہے۔ ابن فتحون رحمہ اللہ نے کسی سے ب ساکن اس کے بعد نون نقل کیا ہے، جو غلط ہے، لقب زہراء تھا، آپ رضی اللہ عنہا اپنے والد سے، آپ سے آپ کے دونوں بیٹے، خاوند، سیدہ عائشہ، ام سلمہ، سلمیٰ، ام رافع اور سیدنا انس رضی اللہ عنہم روایت کرتے ہیں، فاطمہ بنت حسین آپ رضی اللہ عنہا سے مرسل روایت کرتی ہیں، عبدالرزاق بحوالہ ابن جریج لکھتے ہیں: مجھ سے کئی لوگوں نے بیان کیا کہ سیدہ فاطمہ رضی اللہ عنہا نبی کریم صلی اللہ علیہ وسلم کی سب سے چھوٹی اور آپ کو سب سے پیاری بیٹی تھیں۔ ابو عمر(2) لکھتے ہیں: کہ کم عمر ہونے میں اختلاف ہے۔ یقینی بات یہ ہے کہ سب سے بڑی سیدہ زینب رضی اللہ عنہا تھیں، ان سے چھوٹی رقیہ رضی اللہ عنہا، ان سے چھوٹی ام کلثوم رضی اللہ عنہا پھر سیدہ فاطمہ رضی اللہ عنہا تھیں، جس کی تھوڑی بہت تفصیل سیدہ رقیہ رضی اللہ عنہا کے حالات میں گزر چکی ہے، آپ رضی اللہ عنہا کے سن ولادت میں اختلاف ہے۔ چنانچہ واقدی، ابو جعفر باقر کے طریق سے روایت کرتے ہیں، فرمایا: کہ سیدنا عباس رضی اللہ عنہ کا قول ہے کہ جن ایام میں کعبہ کی تعمیر ہو رہی تھی، اسی سال سیدہ فاطمہ رضی اللہ عنہا پیدا ہوئیں، اور نبی علیہ الصلوۃ والسلام کی عمر پینتیس(۳۵) سال تھی، اسی پر مدائنی نے اعتماد کیا ہے۔ ابو عمر(3) عبید اللہ بن محمد بن سلیمان بن جعفر سے روایت کرتے ہیں: کہ سیدہ فاطمہ رضی اللہ عنہا نبی صلی اللہ علیہ وسلم کی ولادت کے اکتالیسویں برس پیدا ہوئیں، بعثت سے کچھ ہی عرصہ پہلے تقریباً سال یا سال سے زیادہ عرصہ میں پیدا ہوئیں، سیدہ عائشہ رضی اللہ عنہا سے پانچ برس بڑی ہیں، سیدہ عائشہ رضی اللہ عنہا کی رخصتی کے چار ماہ بعد محرم ۲ ھ میں سیدنا علی رضی اللہ عنہ سے شادی ہوئی۔ بعض نے کچھ اور مدت بھی بیان کی ہے نبی صلی اللہ علیہ وسلم کی نسل انہی سے چلی۔ ابن اسحاق رحمہ اللہ مغازی کبریٰ میں لکھتے ہیں: کہ مجھ سے ابن ابی نجیح نے بحوالہ سیدنا علی رضی اللہ عنہ بیان کیا: کہ انہوں نے سیدہ فاطمہ رضی اللہ عنہا کے لیے رشتہ بھیجا، نبی صلی اللہ علیہ وسلم (از روئے ظرافت) فرمانے لگے: “کچھ پاس بھی ہے؟” میں نے کہا: کچھ بھی نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: “اس زرہ کا کیا ہوا جو تمہیں ملی تھی۔”(4) یعنی بدر کی غنیمت سے۔ ابن سعد(5) لکھتے ہیں: کہ خالد بن مخلد نے بحوالہ سلیمان جو ابن بلال ہیں، ہمیں بتایا کہ مجھے جعفر بن محمد نے بحوالہ اپنے والد بتایا کہ سیدنا علی رضی اللہ عنہ نے لوہے کی ایک زرہ سیدہ فاطمہ رضی اللہ عنہا کو مہر میں دی تھی۔ حازم بحوالہ حماد بن زید وہ ایوب سے بحوالہ عکرمہ روایت کرتے ہیں: کہ نبی کریم صلی اللہ علیہ وسلم نے جب سیدہ فاطمہ رضی اللہ عنہا کی شادی سیدنا علی رضی اللہ عنہ سے کرنا چاہی تو ان سے فرمایا: “اسے اپنی حطمی زرہ دینا” یہ روایت مرسل، صحیح الاسناد ہے۔ یزید بن ہارون بواسطہ جریر بن حازم، ایوب سے اس سے زیادہ مکمل روایت کرتے ہیں۔ امام احمد نے اپنی مسند میں ابن ابی نجیح کے طریق سے، وہ بحوالہ اپنے والد اس شخص سے روایت کرتے ہیں جس نے سیدنا علی رضی اللہ عنہ کو یہ فرماتے سنا تھا: میں نے نبی صلی اللہ علیہ وسلم کے گھر آپ صلی اللہ علیہ وسلم کی بیٹی کے لیے رشتہ بھیجنا چاہا اور یہ بھی عرض کر دیا کہ واللہ، میرے پاس کچھ نہیں ہے، پھر میں نے آپ صلی اللہ علیہ وسلم کی صلہ رحمی اور مہربانی کو مدنظر رکھتے ہوئے رشتہ بھیج دیا، آپ صلی اللہ علیہ وسلم نے فرمایا: “تمہارے پاس کچھ ہے” میں نے عرض کیا: کچھ نہیں، آپ صلی اللہ علیہ وسلم فرمانے لگے: “وہ حطمیہ زرہ جو میں نے تمہیں فلاں دن دی تھی وہ کہاں ہے؟” میں نے کہا: وہ تو میرے پاس ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: “وہی اسے دے دینا”۔ ابوداؤد کی کتاب میں اس روایت کا شاہد حدیث انس سے موجود ہے، ابن سعد بحوالہ واقدی بطریق ابو جعفر روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم ابوایوب کے گھر ٹھہرے، جب سیدنا علی رضی اللہ عنہ کی سیدہ فاطمہ رضی اللہ عنہا سے شادی ہوئی تو آپ صلی اللہ علیہ وسلم نے ان سے فرمایا: “کوئی گھر تلاش کر لو” ایک گھر کا پچھلا حصہ ملا جہاں رخصتی ہوئی۔ آپ صلی اللہ علیہ وسلم سیدہ فاطمہ رضی اللہ عنہا کے ہاں تشریف لائے، سیدہ فاطمہ رضی اللہ عنہا آپ صلی اللہ علیہ وسلم سے عرض کرنے لگیں، حارثہ بن نعمان سے کہہ دیجئے! آپ صلی اللہ علیہ وسلم نے فرمایا: “میری وجہ سے وہ دوسرے مکان میں منتقل ہو گئے، مزید کہتے ہوئے شرم آتی ہے” ادھر سیدنا نعمان رضی اللہ عنہ کو پتہ چلا، حاضر ہو کر عرض کرنے لگے: یا رسول اللہ صلی اللہ علیہ وسلم! آپ مجھ سے کچھ لیں، یہ مجھے اس سے زیادہ محبوب ہے کہ آپ صلی اللہ علیہ وسلم مجھ سے کچھ نہ لیں، آپ صلی اللہ علیہ وسلم نے فرمایا: تم نے سچ کہا۔ اللہ تعالیٰ تمہیں برکت دے۔ چنانچہ سیدنا حارثہ رضی اللہ عنہ وہاں سے اپنے دوسرے مکان میں منتقل ہو گئے اور سیدنا علی رضی اللہ عنہ سیدہ فاطمہ رضی اللہ عنہا سمیت وہاں رہائش پذیر ہو گئے۔ عمر بن علی کے طریق سے مروی ہے کہ سیدنا علی کی شادی سیدہ فاطمہ سے ان کی مدینہ آمد کے موقع پر رجب میں ہوئی اور بدر سے واپسی پر رخصتی ہوئی۔ سیدہ فاطمہ رضی اللہ عنہا اس وقت اٹھارہ برس کی تھیں۔ صحیح بخاری میں سیدنا علی رضی اللہ عنہ سے ان دو اونٹنیوں کا قصہ منقول ہے جنہیں سیدنا حمزہ نے ذبح کر دیا سیدنا علی رخصتی کا ارادہ رکھتے تھے۔ اس سے اس شخص کے قول کی تردید ہو جاتی ہے جس کا گمان ہے کہ ان کی شادی احد کے بعد ہوئی تھی اس واسطے کہ سیدنا حمزہ تو احد میں ہی شہید ہوئے تھے۔ یزید بن زریع، بواسطہ روح بن قاسم، عمرو بن دینار سے روایت کرتے ہیں کہ سیدہ عائشہ رضی اللہ عنہا نے فرمایا: میں نے فاطمہ کے والد کے سوا ان سے زیادہ کسی کو افضل نہیں پایا۔ یہ روایت طبرانی نے ابراہیم بن ہاشم کے حالات میں معجم اوسط میں نقل کی ہے۔ جس کی سند عمر تک شیخین کی شرط کے مطابق صحیح ہے۔ عکرمہ بحوالہ ابن عباس رضی اللہ عنہما روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے چار خط بھیجے، اور فرمایا: “اہل جنت کی سب سے افضل خواتین خدیجہ، فاطمہ، مریم اور آسیہ رضی اللہ عنہن ہیں۔ ابو یزید مدائنی بحوالہ ابو ہریرہ رضی اللہ عنہ مرفوعاً فرماتے ہیں: دنیا کی سب سے بہتر خواتین چار ہیں: مریم، آسیہ، خدیجہ اور فاطمہ رضی اللہ عنہن۔” حضرت شعبی بحوالہ جابر فرماتے ہیں: ہمارے لیے دنیا کی چار عورتوں کی سیرت کافی ہے۔۔۔ پھر ان کا ذکر فرمایا: عبدالرحمن بن ابو نعیم بحوالہ ابو سعید خدری مرفوعاً فرماتے ہیں: “اہل جنت کی خواتین کی سردار سیدہ فاطمہ رضی اللہ عنہا ہیں۔ ہاں جو فضیلت حضرت مریم کو حاصل ہے۔ صحیحین میں بحوالہ مسور بن مخرمہ منقول ہے: میں نے رسول اللہ صلی اللہ علیہ وسلم سے منبر پر فرماتے ہوئے سنا: “فاطمہ میرے جسم کا ٹکڑا ہے، جس نے اسے تکلیف دی اس نے مجھے ایذا دی اور جس بات سے اسے دھوکہ ہوتا اس سے مجھے دھوکہ ہوتا ہے۔”(6) علی بن حسین بن علی سے بحوالہ ان کے والد، وہ سیدنا علی رضی اللہ عنہ سے روایت کرتے ہیں: فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے سیدہ فاطمہ رضی اللہ عنہا سے فرمایا: اللہ تعالیٰ تمہاری رضا کے ساتھ راضی ہے۔ دولابی نے “الذریۃ الظاہرۃ” میں جید سند سے بحوالہ عبداللہ بن بریدہ، انہوں نے اپنے والد سے نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے سیدہ فاطمہ رضی اللہ عنہا کی رخصتی کی رات فرمایا: کسی سے بات نہ کرنا یہاں تک کہ مجھ سے ملاقات کرو آپ صلی اللہ علیہ وسلم نے پانی منگوایا، اس سے وضو کیا، پھر ان دونوں پر ڈال دیا اور فرمایا: “اے اللہ ان میں برکت دے، اور ان پر برکت ڈال، اور ان کی نسل میں برکت دے۔”(7) سیدہ ام سلمہ رضی اللہ عنہا فرماتی ہیں: کہ میرے گھر میں یہ آیت نازل ہوئی “بے شک اللہ تعالیٰ ارادہ فرماتے ہیں کہ اے اہل بیت تم سے ناپاکی دور کریں۔”(8) ۔ الآیۃ فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم نے سیدہ فاطمہ رضی اللہ عنہا، سیدنا علی رضی اللہ عنہ، سیدنا حسن، سیدنا حسین رضی اللہ عنہم کی طرف پیغام بھیجا، پھر فرمایا: “یہ میرے اہل بیت ہیں۔”(9) ۔ الحدیث ترمذی رحمہ اللہ نے اور حاکم رحمہ اللہ نے مستدرک میں اسے نقل کیا ہے اور فرمایا: مسلم کی شرط کے مطابق صحیح ہے۔ مسروق رحمہ اللہ نے بحوالہ سیدہ عائشہ رضی اللہ عنہا فرمایا: سیدہ فاطمہ رضی اللہ عنہا چلتی ہوئی آئیں اور ان کا چلنا نبی کریم صلی اللہ علیہ وسلم کے چلنے کی طرح تھا، آپ صلی اللہ علیہ وسلم نے فرمایا: “میری بیٹی کو خوش آمدید” پھر اسے اپنی دائیں طرف بٹھایا اور چپکے سے انہیں کوئی بات کہی تو وہ رونے لگیں، پھر چپکے سے انہیں ایک اور بات کہی تو وہ ہنس پڑیں۔ میں نے کہا: میں نے آپ کو آج سے پہلے غم کے ساتھ ہنستے نہیں دیکھا! میں نے اس سے اس بارے میں سوال کیا تو کہنے لگیں: میں رسول اللہ صلی اللہ علیہ وسلم کے راز کو ظاہر نہیں کروں گی، جب آپ صلی اللہ علیہ وسلم کی وفات ہو گئی تو میں نے ان سے پوچھا، انہوں نے بتایا کہ آپ صلی اللہ علیہ وسلم نے فرمایا: “حضرت جبرائیل علیہ السلام ہر سال قرآن پاک کا ایک مرتبہ میرے ساتھ دور کرتے تھے، اس سال دو مرتبہ دور کیا ہے، میرا خیال ہے میری وفات کا وقت قریب آ گیا ہے، اور تم میرے اہل بیت میں سب سے پہلے مجھے آ ملو گی اور میں تمہارا اچھا پیشرو ہوں گا” تو میں رونے لگی، پھر آپ صلی اللہ علیہ وسلم نے فرمایا: “کیا تم اس پر راضی نہیں ہو کہ تمام جہان کی عورتوں کی سردار ہو” تو میں ہنسنے لگی۔ دونوں نے اسے نقل کیا ہے۔ سیدہ ام سلمہ رضی اللہ عنہا فرماتی ہیں کہ سیدہ فاطمہ رضی اللہ عنہا نبی کریم صلی اللہ علیہ وسلم سے آ کر پوچھنے لگیں: کہ مجھے بتائیں کہ آپ کا کیا حال ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: “اسی سال میری روح قبض ہو گی” جس پر وہ رونے لگیں، آپ صلی اللہ علیہ وسلم نے فرمایا: “تم سوائے مریم علیہا السلام کے جنت کی عورتوں کی سردار بن جاؤ” جس پر وہ خوش ہو کر ہنسنے لگیں، ابو یعلیٰ نے یہ روایت نقل کی ہے۔(10) ابن ابی عاصم عبداللہ بن عمرو بن سالم المفلوج سے بحوالہ اہل بیت کی سند سیدنا علی رضی اللہ عنہ سے نقل کرتے ہیں: کہ نبی کریم صلی اللہ علیہ وسلم نے سیدہ فاطمہ رضی اللہ عنہا سے فرمایا: “کہ اللہ تعالیٰ تمہاری ناراضگی سے ناراض اور تمہاری رضا مندی سے راضی ہوتا ہے۔”(11) امام ترمذی(12) نے حدیث زید بن ارقم کی حدیث سے نقل کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “علی، فاطمہ حسن اور حسین رضی اللہ عنہم سے جو شخص بھی لڑے گا، تو مقابلے میں مجھے پائے گا اور جو ان سے صلح کرے گا، میری اس سے صلح ہے۔” ابو عمر(13) سیدہ فاطمہ رضی اللہ عنہا کی وفات کے قصے میں نقل کرتے ہیں کہ سیدہ فاطمہ رضی اللہ عنہا نے سیدنا علی رضی اللہ عنہ کو یہ وصیت کر رکھی تھی کہ وہ اور سیدہ اسماء بنت عمیس رضی اللہ عنہا انہیں غسل دیں، ابن فتحون نے اس روایت کو بعید قرار دیا ہے، کیونکہ اس وقت سیدہ اسماء بنت عمیس رضی اللہ عنہا صدیق اکبر رضی اللہ عنہ کی اہلیہ تھیں، فرماتے ہیں: یہ کیسے ہو سکتا ہے کہ سیدہ فاطمہ رضی اللہ عنہا کے غسل کا حال سیدنا علی رضی اللہ عنہ کی موجودگی میں کیسے منکشف ہو سکتا ہے؟ یہ محل استبعاد ہے۔ مسند احمد میں ہے کہ انہوں نے اپنی موت سے تھوڑی دیر پہلے غسل کر لیا تھا اور یہ حکم دیا تھا کہ ان کا بدن نہ کھولا جائے اور اس غسل کو کافی سمجھا جائے یہ بھی بعید ہے۔ صحیح میں سیدہ عائشہ رضی اللہ عنہا کی حدیث سے ثابت ہے کہ سیدہ فاطمہ رضی اللہ عنہا نے نبی کریم صلی اللہ علیہ وسلم کے بعد چھ ماہ کا عرصہ حیات گزارا تھا۔ واقدی فرماتے ہیں یہی روایت ثابت ہے۔ حمیدی بواسطہ سفیان عمرو بن دینار سے روایت کرتے ہیں: کہ وہ نبی کریم صلی اللہ علیہ وسلم کے بعد تین ماہ حیات رہیں۔(14) جبکہ ان کے علاوہ مؤرخین کا قول چار ماہ کا ہے۔ ایک قول دو ماہ کا بھی ہے۔ دولابی کی کتاب “الذریۃ الظاہرۃ” میں لکھا ہے: سیدہ فاطمہ رضی اللہ عنہا نبی کریم صلی اللہ علیہ وسلم کے بعد پچانوے(۹۵) دن زندہ رہیں۔ اور عبداللہ بن حارث کا قول ہے کہ آٹھ ماہ حیات رہیں۔ ابن سعد اور امام احمد بن حنبل حدیث ام رافع سے روایت کرتے ہیں کہ سیدہ فاطمہ رضی اللہ عنہا بیمار ہو گئیں، جس دن آپ رضی اللہ عنہا کی وفات ہوئی اس دن فرمایا: اماں مجھے غسل کرائیں پھر انہوں نے اچھے طریقے سے غسل کر لیا اور نئے کپڑے پہن کے فرمانے لگیں: میری چار پائی صحن کے درمیان میں رکھ دو، اس پر قبلہ رخ ہو کر لیٹ گئیں اور فرمانے لگیں: اماں، میری روح قبض ہونے لگی ہے، میں غسل کر چکی ہوں تو ہرگز کوئی شخص میرا کپڑا نہ ہٹائے، چنانچہ پھر وہ فوت ہو گئیں، سیدنا علی رضی اللہ عنہ آئے میں نے انہیں صورتحال بتائی انہوں نے ان کا جنازہ اٹھایا اور اسی غسل پر اکتفاء کرتے ہوئے انہیں دفن کر دیا۔(15) ابن سعد، محمد بن موسیٰ کے طریق سے روایت کرتے ہیں: سیدنا علی رضی اللہ عنہ نے سیدہ فاطمہ رضی اللہ عنہا کو غسل دیا تھا، اور عبید اللہ بن ابی بکر کے طریق سے بحوالہ عمرہ نقل کیا ہے کہ سیدنا عباس رضی اللہ عنہ نے سیدہ فاطمہ رضی اللہ عنہا کا جنازہ پڑھایا، اور ان کی قبر میں سیدنا عباس، علی اور فضل بن عباس رضی اللہ عنہم اترے تھے۔ واقدی بطریق شعبی روایت کرتے ہیں کہ سیدہ فاطمہ رضی اللہ عنہا کا جنازہ سیدنا ابو بکر رضی اللہ عنہ نے پڑھایا تھا، اس سند میں ضعف اور انقطاع ہے۔ بعض متروک راوی حضرت مالک سے بحوالہ جعفر بن محمد وہ اپنے والد سے اس مفہوم کی روایت نقل کرتے ہیں، جسے دارقطنی اور ابن عدی نے فضول قرار دیا ہے۔ ابن سعد(16) بواسطہ عفان، حماد بن سلمہ، عطاء بن سائب وہ اپنے والد سے بحوالہ سیدنا علی رضی اللہ عنہ نقل کرتے ہیں، جب رسول اللہ صلی اللہ علیہ وسلم نے سیدہ فاطمہ رضی اللہ عنہا کی ان سے شادی کر دی، تو ان کے ساتھ بطور سامان جہیز ایک موٹی چادر، کھجور کی چھال کا ایک تکیہ، دو چکیاں اور دو مشکیزے بھیجے، فرماتے ہیں: ایک دن سیدنا علی رضی اللہ عنہ نے سیدہ فاطمہ رضی اللہ عنہا سے فرمایا: مشقت کرتے کرتے میرا دل تنگ پڑ گیا ہے۔ اور اللہ تعالیٰ ابھی کچھ قیدیوں کو لے آیا ہے، اپنے والد کے پاس جاؤ اور ان سے خادمہ کا سوال کرو، وہ کہنے لگیں: اللہ کی قسم! چکی پیستے پیستے میرے ہاتھوں میں بھی چھالے پڑ گئے ہیں، چنانچہ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں، آپ صلی اللہ علیہ وسلم نے فرمایا: “سناؤ، بیٹی کیسے آنا ہوا؟” عرض کرنے لگیں: ابا حضور! سلام کرنے آئی تھی، اور حیا کی وجہ سے بن مانگے واپس چلی گئیں، پھر دونوں آئے اور سیدنا علی رضی اللہ عنہ نے اپنی حالت زار بیان کی، آپ صلی اللہ علیہ وسلم نے فرمایا: اللہ کی قسم! یہ کیسے ہو سکتا ہے کہ میں تمہیں دوں اور اصحاب صفہ جن کے پیٹ بھوک سے دوہرے ہو رہے ہیں، انہیں نہ دوں۔ میرے پاس ان پر خرچ کرنے کے لیے کچھ نہیں ہے۔ یہ غلام بیچ کے میں انہیں خرچ دوں گا۔” چنانچہ یہ دونوں واپس لوٹ آئے، بعد میں آپ صلی اللہ علیہ وسلم دلجوئی کے لیے تشریف لے گئے، اتنے میں یہ لوگ بستروں میں دراز ہو چکے تھے، اور اس موٹی چادر کا طول کم تھا، ان کے چہرے ڈھکے ہوئے تھے اور پاؤں کھلے تھے، اور اگر وہ پاؤں ڈھکتے تو چہرہ کھل جاتا، آپ صلی اللہ علیہ وسلم کی آہٹ پا کر اٹھنے لگے، آپ صلی اللہ علیہ وسلم نے فرمایا: لیٹے رہو، دیکھو، میں تمہیں اس سے بہتر چیز نہ بتاؤں، جس کا تم نے سوال کیا تھا، وہ عرض کرنے لگے، کیوں نہیں، فرمایا: “چند کلمات ہیں جو مجھے جبرائیل نے سکھائے ہیں، ہر نماز کے بعد تم دونوں دس بار سبحان اللہ، دس بار الحمد للہ اور دس بار اللہ اکبر کہہ لیا کرو، اور جب سونے کا ارادہ کرو تو تینتیس(۳۳) بار سبحان اللہ، تینتیس(۳۳) بار الحمد للہ، چونتیس(۳۴) بار اللہ اکبر پڑھ لیا کرو” سیدنا علی رضی اللہ عنہ فرماتے ہیں: اللہ کی قسم! جب سے آپ صلی اللہ علیہ وسلم نے یہ کلمات مجھے سکھائے میں نے انہیں چھوڑا نہیں، آپ رضی اللہ عنہ سے ابن الکواء نے پوچھا: کیا صفین کی رات بھی نہیں؟ آپ رضی اللہ عنہ نے فرمایا: اے اہل طروق اللہ تمہیں ہلاک کرے! صفین کی رات بھی نہیں۔ فرمایا: ہمیں یزید بن ہارون نے خبر دی، وہ فرماتے ہیں، ہمیں جریر بن حازم نے بتایا، وہ فرماتے ہیں: کہ ہم سے عمرو بن سعید نے حدیث بیان کی، فرماتے ہیں: کہ سیدنا علی رضی اللہ عنہ کے رویے میں سیدہ فاطمہ رضی اللہ عنہا کے خلاف کچھ سختی تھی۔ سیدہ فاطمہ رضی اللہ عنہا کہنے لگیں: میں رسول اللہ صلی اللہ علیہ وسلم سے ضرور تمہاری شکایت کروں گی۔ چنانچہ وہ چل پڑیں سیدنا علی رضی اللہ عنہ بھی انہی کے پیچھے ہو لیے۔ آ کر آپ صلی اللہ علیہ وسلم سے گفتگو کی (سن کر) آپ صلی اللہ علیہ وسلم نے فرمایا: بیٹی! خوب کان لگا کر سنو اور سمجھو جو عورت اپنے خاوند کی مرضی پوری نہیں کرتی جبکہ اس کا خاوند خاموش ہو تو اس کی کوئی ولایت و اختیار نہیں” (یعنی اس کی شکایت سنے جانے کی گنجائش نہیں)۔ سیدنا علی رضی اللہ عنہ فرماتے ہیں پھر میں نے کوئی ایسی بات نہیں کی جو انہیں ناپسند ہوتی۔ ہمیں عبید اللہ بن موسیٰ نے بتایا وہ فرماتے ہیں: ہم سے عبد العزیز بن سیار نے بحوالہ حبیب بن ابی ثابت روایت کی، فرماتے ہیں: سیدنا علی اور فاطمہ رضی اللہ عنہما کے درمیان کوئی بات ہوئی، رسول اللہ صلی اللہ علیہ وسلم ان کے پاس آئے، آپ ان سے گفتگو فرماتے رہے یہاں تک کہ ان میں صلح کروا دی، پھر آپ صلی اللہ علیہ وسلم باہر تشریف لائے۔ راوی کہتے ہیں: آپ صلی اللہ علیہ وسلم سے کسی نے کہا: آپ جب اندر تشریف لے گئے تھے تو آپ کی حالت یکساں تھی کوئی تبدیلی ہمیں محسوس نہیں ہوئی لیکن جب باہر تشریف لائے تو آپ کا چہرہ ہشاش بشاش تھا، آپ صلی اللہ علیہ وسلم نے فرمایا: میں کیوں نہ خوش ہوتا جبکہ میں نے اپنے پسندیدہ دو افراد میں صلح کرا دی ہے۔ واقدی نے اپنی سند سے بحوالہ ابو جعفر نقل کیا ہے، فرماتے ہیں، سیدنا عباس رضی اللہ عنہ سیدنا علی اور فاطمہ رضی اللہ عنہما کے پاس گئے تو وہ کہہ رہی تھیں: میں عمر میں آپ سے بڑی ہوں، تو سیدنا عباس رضی اللہ عنہ نے فرمایا: سیدہ فاطمہ رضی اللہ عنہا اس وقت پیدا ہوئیں جب قریش کعبہ کی تعمیر کر رہے تھے اور سیدنا علی رضی اللہ عنہ ان سے دو برس قبل پیدا ہوئے۔ واقدی فرماتے ہیں: سیدہ فاطمہ رضی اللہ عنہا نے رمضان کے تین دن گزرنے پر منگل کی رات ۱۱ھ میں وفات پائی۔ عمرہ کے طریق سے ہے: سیدنا عباس رضی اللہ عنہ نے سیدہ فاطمہ رضی اللہ عنہا کی نماز جنازہ پڑھی، وہ سیدنا علی اور سیدنا فضل ان کی قبر میں اترے، علی بن حسین کے طریق سے ہے: کہ سیدنا علی رضی اللہ عنہ نے ان کی نماز جنازہ پڑھی اور رات(17) کو لوگوں کی چلت پھرت رک جانے کے بعد انہیں دفن کیا، انہوں نے بحوالہ ابن عباس رضی اللہ عنہما نقل کیا ہے کہ انہوں نے ان سے پوچھا تو انہوں نے بتایا۔ واقدی فرماتے ہیں: میں نے عبد الرحمن بن ابو موالی سے کہا: لوگ کہتے ہیں: کہ سیدہ فاطمہ رضی اللہ عنہا کی قبر بقیع میں ہے، انہوں نے فرمایا: وہ دار عقیل کے ایک گوشے میں دفن کی گئیں اور ان کی قبر اور راستے کے درمیان سات ہاتھ کا فاصلہ ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۷۵)، تجرید (۲۹۴/۲)\n(2) الاستيعاب (۱۸۹۳/۴)\n(3) الاستيعاب (۱۸۹۳/۴)\n(4) مسند ابویعلیٰ (۵۰۳/۱) مجمع الزوائد (۲۸۳/۴)\n(5) طبقات الکبریٰ (۱۱/۸)\n(6) ترمذی (۳۸۶۷)\n(7) المعجم الکبیر (۱۱۵۳/۲)، مجمع الزوائد (۲۰۹/۹)\n(8) سورۃ الاحزاب الآیۃ (۳۳)\n(9) مسلم (۶۱۶۰)، ترمذی (۳۷۲۴)\n(10) مسند ابویعلیٰ (۶۷۴۳/۱۲)\n(11) الاحاد والمثانی (۳۶۳/۵)\n(12) کتاب المناقب باب ماجاء فضل بنت محمد صلی اللہ علیہ وسلم (۳۸۷۰)\n(13) الاستيعاب (۱۸۹۹/۴)\n(14) المعجم الکبیر (۹۸۹/۲۲) مجمع الزوائد (۱۱/۹) الاحاد والمثانی (۳۵۵/۵) جامع المسانید (۳۶/۱۶)\n(15) المعجم الکبیر (۹۶۲/۲۲)، مجمع الزوائد (۲۱۱/۱)\n(16) الطبقات الکبریٰ (۱۶۱/۸)\n(17) طبرانی المعجم الکبیر (۹۹۶/۲۲)، مجمع الزوائد (۲۱۱/۹) الاحاد والمثانی (۳۵۶/۵)"}],[10189,"§۱۱۵۸۰ ۔ فاطمہ بنت اسد\n(1) بن ہاشم بن عبد مناف ہاشمیہ، سیدنا علی اور ان کے بہن بھائیوں کی والدہ ہیں، بعض کا قول ہے: ہجرت سے قبل وفات پا گئیں، صحیح یہ ہے کہ انہوں نے ہجرت کی اور مدینہ میں وفات پائی۔ شعبی نے اس پر اعتماد کیا ہے، فرماتے ہیں: اسلام لائیں اور ہجرت کی اور مدینہ میں وفات پائی۔ ابن ابی عاصم نے عبداللہ بن محمد بن عمر بن علی بن ابو طالب سے بحوالہ ان کے والد نقل کیا ہے، کہ نبی کریم صلی اللہ علیہ وسلم نے سیدہ فاطمہ بنت اسد کے کفن کے لیے اپنی قمیص عطا فرمائی(2) اور فرمایا: “ابو طالب کے بعد مجھ سے اچھا سلوک کرنے والا ان کے علاوہ کوئی ثابت نہیں ہوا۔” امام اعمش(3) بحوالہ عمرو بن مرہ، وہ ابو البختری سے وہ سیدنا علی رضی اللہ عنہ سے روایت کرتے ہیں، میں نے اپنی والدہ سے عرض کیا: پانی لانے اور دیگر ضروریات میں جانے کے سلسلے میں فاطمہ کی جگہ آپ لے لیں اور وہ چکی پیسنے اور آٹا گوندھنے میں آپ کا ہاتھ بٹا دے گی۔(4) زبیر بن بکار فرماتے ہیں: وہ پہلی ہاشمیہ ہیں جنہوں نے خلیفہ کو جنم دیا، ان کے بعد سیدہ فاطمۃ الزھراء ہیں، فاطمہ بنت حمزہ کے سوانح میں ان کا ذکر آئے گا۔ جو دلالت کرتا ہے کہ انہوں نے مدینہ میں وفات پائی۔(5) ابن سعد فرماتے ہیں: وہ نیک خاتون تھیں نبی کریم صلی اللہ علیہ وسلم ان سے ملاقات کے لیے تشریف لاتے تھے اور دوپہر کو ان کے گھر آرام فرماتے تھے۔","",{"fn":"(1) اسد الغابۃ (۷۱۶۸)، الاستيعاب (۳۵۹۹)، تجرید (۲۹۳/۵)\n(2) معجم الکبیر (۸۷۲/۲۴) مجمع الزوائد (۲۵۶/۹)\n(3) مجمع الزوائد (۲۵۷/۹)\n(4) المعجم الکبیر (۸۷۳/۲۴)، مجمع الزوائد (۲۵۶/۹)\n(5) نسب قریش (۱۶)"}],[10190,"§۱۱۵۸۱ ۔ فاطمہ بنت ابی الاسد\n(1) بعض کا قول ہے: بنت اسود بن عبد الاسد: ابو عمر فرماتے ہیں،(2) یہ وہی ہیں، کہ نبی کریم صلی اللہ علیہ وسلم نے چوری کی وجہ سے ان کا ہاتھ کاٹنے کا حکم فرمایا، اور جب اسامہ بن زید نے ان کے لیے سفارش کی تو فرمایا: “کیا تم اللہ کی حدوں میں سے ایک حد کے بارے میں سفارش کرتے ہو؟” حبیب بن ابو ثابت نے ان کی حدیث روایت کی اور ان کا نام لیا ہے۔ میں کہتا ہوں: عبد الغنی بن سعید نے مہمات میں یحییٰ بن سلمہ بن کہیل کے طریق سے، عمار دہنی سے بحوالہ ابو وائل نقل کیا ہے۔ فرماتے ہیں: فاطمہ بنت ابوالاسد نے جو ابو سلمہ کے بھائی کی بیٹی ہیں چوری کی، قریش کو خوف ہوا کہ ان کا ہاتھ کاٹ دیا جائے گا، انہوں نے اسامہ سے گفتگو کی۔۔۔۔ الحدیث ابن سعد کا قول ہے: فاطمہ بنت اسود بن عبد الاسد اسلام لائیں اور بیعت کی، یہ وہی ہیں جنہوں نے چوری کی، تو نبی کریم صلی اللہ علیہ وسلم نے ان کا ہاتھ کاٹنے کا حکم دیا۔ ہم سے ابن نمیر نے اصبغ سے بحوالہ حبیب بن ابو ثابت مرفوع حدیث بیان کی کہ فاطمہ بنت اسود بن عبدالاسد نے رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں زیور چوری کیا، بہت سے لوگوں نے نبی کریم صلی اللہ علیہ وسلم سے سفارش کی، انہوں نے اسامہ بن زید سے گفتگو کی تا کہ وہ نبی کریم صلی اللہ علیہ وسلم سے ان کی سفارش کریں، جب اسامہ آئے اور ان کو نبی کریم صلی اللہ علیہ وسلم نے دیکھا تو فرمایا: “اے اسامہ مجھ سے سفارش نہ کرنا، کیونکہ حدود جب میرے سپرد کی جاتی ہیں تو ان کے ترک کرنے کی گنجائش نہیں رہتی، اگر محمد کی بیٹی فاطمہ بھی ایسا کرتی تو میں اس کے ہاتھ کاٹنے کا حکم دیتا۔”(3) ابن سعد(4) کا قول ہے: اہل مدینہ وغیرہ کی اہل مکہ کی روایت ہے کہ جس خاتون نے چوری کی، اور رسول اللہ صلی اللہ علیہ وسلم نے ان کا ہاتھ کاٹنے کا حکم دیا، وہ ام عمرو بنت سفیان بن عبدالاسد۔","",{"fn":"(1) اسد الغابۃ (۷۱۶۹)، تجرید (۲۹۳/۲)\n(2) الاستيعاب (۱۸۹۲/۴)\n(3) بخاری (الحدیث ۳۴۷۵، ۳۷۳۲، ۶۷۸۷) مسلم (الحدیث ۴۳۸۶) ابوداؤد (۴۳۷۳)، ترمذی (۱۴۳۰) نسائی (۴۹۱۴)، ابن ماجہ (۲۵۴۷)\n(4) الطبقات الکبریٰ (۱۹۲/۸)"}],[10191,"§۱۱۵۸۲ ۔ فاطمہ بنت جنید\nبن عمرو بن عبد شمس بن عمرو، عباس بن عبدالمطلب کی زوجہ اور حارث کی والدہ ہیں جو ان کا بیٹا ہے۔ زبیر بن بکار نے ان کا ذکر کیا ہے۔"],[10192,"§۱۱۵۸۳ ۔ فاطمہ بنت الحارث\n(1) بن خالد بن صحر بن عامر بن کعب بن سعد بن تیم بن مرہ قرشیہ تیمیہ، ان کی والدہ رائطہ کے سوانح میں ان کا ذکر ہو چکا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۷۰)، الاستيعاب (۵۳۰۲)، تجرید (۲۹۳/۲)"}],[10193,"§۱۱۵۸۴ ۔ فاطمہ بنت ابی حبیش\n(1) بن مطلب بن اسد بن عبد العزیٰ بن قصی قرشیہ اسدیہ صحیحین(2) میں ہشام بن عروہ کے طریق سے بحوالہ ان کے والد، سیدہ عائشہ رضی اللہ عنہا سے روایت ہے، فرماتی ہیں: فاطمہ بنت ابی حبیش نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں اور کہنے لگیں: یا رسول اللہ صلی اللہ علیہ وسلم مجھے حیض آتا ہے اور میں کبھی پاک نہیں ہوتی، کیا میں نماز چھوڑ دوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: نہیں، یہ ایک رگ ہے، حیض نہیں” الحدیث۔ اسے منذر بن مغیرہ نے بحوالہ عروہ روایت کیا ہے، کہ فاطمہ بنت ابی حبیش ہیں، ایک روایت میں الفاظ ہیں بحوالہ فاطمہ، ایک اور روایت میں ہے، مجھ سے فاطمہ نے بیان کیا، ان کی حدیث کو ابوداؤد اور نسائی نے نقل کیا ہے، اور پہلی مشہور ہے۔(3)","",{"fn":"(1) اسد الغابۃ (۷۱۷۱) الاستيعاب (۳۵۰۳) تجرید (۲۹۴/۲)\n(2) بخاری (الحدیث ۲۲۳) مسلم (الحدیث ۷۵۲)\n(3) ابوداؤد (الحدیث ۲۸۰)، نسائی (الحدیث ۳۵۶)"}],[10194,"§۱۱۵۸۵ ۔ فاطمہ بنت حمزہ\n(1) بن عبدالمطلب بن ہاشم، ہاشمیہ، ان کی والدہ سلمیٰ بنت عمیس ہیں: ابن سکن کا قول ہے: ان کی کنیت ام الفضل ہے، دارقطنی نے کتاب الاخوۃ میں فرمایا: ان کا نام امیمہ ہے ان سے سعد بن زید کا بیٹا عبد الرحمن پیدا ہوا نبی کریم صلی اللہ علیہ وسلم نے سلمہ بن ابو سلمہ ابن عبد الاسد سے ان کا نکاح کر دیا، ابن ابی عاصم نے ابو فاختہ کے طریق سے بحوالہ جعدہ بن کبیرہ، انہوں نے علی سے روایت کیا ہے، فرماتے ہیں نبی کریم صلی اللہ علیہ وسلم کو موٹے ریشم کا جوڑا ہدیہ دیا گیا، آپ صلی اللہ علیہ وسلم نے فرمایا: “فاطماؤں کے لیے اسے اوڑھنیاں بنا دو” تو میں نے اسے پھاڑ کر چار اوڑھنیاں بنائیں: ایک سیدہ فاطمہ بنت رسول اللہ صلی اللہ علیہ وسلم کے لیے، ایک سیدہ فاطمہ بنت اسد اور ایک فاطمہ بنت حمزہ کے لیے اوڑھنی بنائی اور چوتھی فاطمہ کا ذکر نہیں کیا۔(2) میں کہتا ہوں: شاید وہ عقیل کی زوجہ ہیں جن کا ذکر آگے آ رہا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۷۲)، تجرید (۲۹۴/۲)\n(2) الاحاد والمثانی (۱۴۲/۱، ۱۴۳۰)"}],[10195,"§۱۱۵۸۶ ۔ فاطمہ بنت الخطاب\n(1) بن نفیل قرشیہ عدویہ، سیدنا عمر رضی اللہ عنہ کی بہن ہیں، ان کے بھائی کے سوانح میں ان کا نسب گزر چکا ہے۔ اسلام کے ابتدائی دور میں اپنے شوہر سعید بن زید بن عمرو بن نفیل کے ساتھ اسلام لائیں، دارقطنی نے کتاب الاخوۃ میں روایت کیا ہے کہ ان کا نام امیمہ ہے، فرماتے ہیں: سعید بن زید سے ان کے ہاں عبدالرحمن پیدا ہوئے۔ ابو عمر(2) فرماتے ہیں: سیدنا عمر کے اسلام لانے کے بارے میں ان کی عجیب حدیث ہے۔ میں کہتا ہوں: اسے محمد بن عثمان بن ابی شیبہ نے اپنی تاریخ میں اور ابونعیم نے اپنے طریق سے اور اسحاق بن عبد اللہ کے طریق سے بحوالہ ابان بن صالح اسے نقل کیا ہے۔ انہوں نے مجاہد سے، انہوں نے ابن عباس سے روایت کیا ہے، فرماتے ہیں: میں نے سیدنا عمر رضی اللہ عنہ سے ان کے اسلام لانے کے بارے میں پوچھا، انہوں نے فرمایا: میں سیدنا حمزہ رضی اللہ عنہ کے اسلام لانے کے تین دن بعد باہر نکلا، تو فلاں بن فلاں مخزومی کو پایا، میں نے اسے کہا: کیا تو نے اپنے آباء و اجداد کے دین کو چھوڑ کر محمد کے دین کو اختیار کر لیا ہے؟ اس نے کہا یہ دین تو اس شخص نے بھی اختیار کر لیا ہے جس کا مجھ سے بڑھ کر تم پر حق ہے۔ فرماتے ہیں: میں نے کہا: کون؟ انہوں نے کہا: تمہاری بہن اور بہنوئی، فرماتے ہیں: میں چلا، اور دروازے کو بند پایا، مجھے ہلکی ہلکی آواز سنائی دی۔ فرماتے ہیں: انہوں نے میرے لیے دروازہ کھولا، میں اندر گیا، اور کہا: یہ مجھے کس چیز کی آواز آ رہی تھی؟ کہنے لگیں: کچھ نہیں، بحث کرتے رہے، یہاں تک کہ میں نے اس کے سر پر مارا، کہنے لگیں: تمہارے نہ چاہتے ہوئے بھی ہم مسلمان ہو چکے ہیں، فرماتے ہیں: جب میں نے خون دیکھا تو مجھے شرم آئی، میں نے کہا: مجھے وہ کتاب دکھاؤ۔۔۔۔۔ پھر طویل قصہ ذکر کیا۔ واقدی نے بحوالہ فاطمہ بنت مسلم اشجعیہ بحوالہ فاطمہ خزاعیہ انہوں نے فاطمہ بنت خطاب سے نقل کیا ہے، کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: “میری امت اس وقت تک بھلائی پر رہے گی جب تک اس کے فاسق (کھلے عام گناہ کرنے والے) علماء میں دنیا کی محبت، جاہل قاریوں اور ظالموں کا ظہور نہیں ہو جاتا۔ جب یہ علامت ظاہر ہو جائے گی تو خدشہ ہے اللہ تعالیٰ انہیں عمومی عذاب میں مبتلا نہ کر دے۔ کنیتوں میں عنقریب آئے گا کہ زبیر فرماتے ہیں: کہ عبدالرحمن اکبر بن سعید بن زید کی والدہ یہ ہیں: ام جمیل بنت خطاب، گویا ان کا نام فاطمہ، لقب امیمہ، اور کنیت ام جمیل ہے، ابن سعد(3) کا قول ہے کہ کتاب النسب میں ہے جن سے سعید بن زید بن عمرو بن نفیل نے نکاح کیا تھا وہ رملہ ہیں، اور وہ ام جمیل بنت خطاب ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۱۷۴)، الاستيعاب (۱۸۹۲/۴) تجرید (۲۹۴/۲)\n(2) الاستيعاب (۱۸۹۲/۴)\n(3) الطبقات الکبریٰ (۱۹۵/۸)"}],[10196,"§۱۱۵۸۷ ۔ فاطمہ بنت سودہ\n(1) بن ابی نہشل، جہنیہ، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۷۶)، تجرید (۲۹۴/۲)"}],[10197,"§۱۱۵۸۸ ۔ فاطمہ بنت شریح الکلابیہ\n(1) ابن بشکوال نے بحوالہ ابی عبیدہ نقل کیا ہے کہ انہوں نے ازواج مطہرات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۲۹۴/۲)"}],[10198,"§۱۱۵۸۹ ۔ فاطمہ بنت شریک\nبن محماء، ان کے والد کے سوانح میں ان کا ذکر ہے۔"],[10199,"§۱۱۵۹۰ ۔ فاطمہ بنت شیبہ\n(1) بن ربیعہ بن عبد شمس عبشمیہ، عقیل بن ابی طالب نے ان سے نکاح کیا، ابن ہشام نے ذکر کیا ہے کہ عقیل حنین کے دن لڑائی کے بعد ان کے پاس آئے، تو انہوں نے کہا: تمہیں کیا غنیمت ملی؟ انہوں نے انہیں سوئی دی۔ اتنے میں نبی کریم صلی اللہ علیہ وسلم کے منادی نے کہا: “(مجاہدین! سن لو!) سوئی اور دھاگہ تک اجتماعی مال غنیمت میں جمع کرا دو!”(2) انہوں نے ان سے سوئی لی اور غنیمت میں رکھ دی۔ واقدی نے سیدہ فاطمہ بنت ولید بن عقبہ کے بارے میں یہ نقل کیا ہے، بعض کا قول ہے: عقیل کی زوجہ کا نام یہ ہے: فاطمہ بنت عقبہ جو ہند کی بہن ہیں، یہ ابن ابی ملیکہ سے منقول ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۷۷)، تجرید (۲۹۴/۲)\n(2) السیرۃ النبویۃ (۱۰۶/۴)، الطبقات الکبریٰ (۱۷۳/۸)"}],[10200,"§۱۱۵۹۱ ۔ فاطمہ بنت صفوان\n(1) بن امیہ بن محرث بن حمل بن شق بن رقبہ بن مخدج کنانیہ، عمرو بن ابی احیحہ سعید بن العاص کی زوجہ ہیں،(2) ابن اسحاق نے بنو امیہ سے حبشہ کی طرف ہجرت کرنے والوں میں ان کا نام لیا ہے۔ فرماتے ہیں: عمرو بن سعید ان کے ساتھ ان کی زوجہ فاطمہ بنت صفوان کنانیہ نے ہجرت کی اور وہیں وفات پا گئیں، ابن سعد(3) نے ان کا نسب بیان کیا ہے اور فرمایا: مکہ میں ابتدائی دور میں اسلام لائیں۔","",{"fn":"(1) اسد الغابۃ (۷۱۷۸)، الاستيعاب (۳۵۰۶)، تجرید (۲۹۴/۲)\n(2) السیرۃ النبویۃ (۲۵۶/۱)\n(3) الطبقات الکبریٰ (۱۳۹/۸)"}],[10201,"§۱۱۵۹۲ ۔ فاطمہ بنت الضحاک\n(1) بن سفیان کلابیہ: ابو عمر(2) نے ان کا ذکر کیا ہے اور فرمایا: ابن اسحاق فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے ان سے ان کی بیٹی زینب کی وفات کے بعد نکاح کیا اور جب آیت تخیر نازل ہوئی تو انہیں اختیار دیا، انہوں نے دنیا کو اختیار کیا تو نبی کریم صلی اللہ علیہ وسلم نے انہیں جدا کر دیا، اس کے بعد وہ مینگنیاں چنا کرتی تھیں۔ اور فرماتیں: میں بدبخت ہوں، میں نے دنیا کو اختیار کیا ابو عمر کا قول ہے: یہ ہمارے نزدیک صحیح نہیں، کیونکہ شہاب ابو سلمہ کے حوالے سے اور حضرت عروہ سیدہ عائشہ کے حوالے سے روایت کرتے ہیں: کہ جب نبی کریم صلی اللہ علیہ وسلم نے اپنی ازواج کو اختیار دیا تو ان سے آغاز کیا، میں نے اللہ اور اس کے رسول کو اختیار کیا، فرماتے ہیں اور رسول اللہ صلی اللہ علیہ وسلم کی تمام ازواج نے اسی کی پیروی کی۔(3) حضرت قتادہ اور عکرمہ کا قول ہے: آپ صلی اللہ علیہ وسلم نے جب انہیں اختیار دیا اس وقت آپ صلی اللہ علیہ وسلم کے نکاح میں نو ازواج مطہرات تھیں، جو آپ صلی اللہ علیہ وسلم کی وفات کے وقت زندہ تھیں ایک جماعت کا قول ہے: جو کہتی تھیں میں بد بخت ہوں، انہوں نے پناہ چاہی تھی، اور پناہ مانگنے والی خاتون کے بارے میں بہت زیادہ اختلاف ہے۔ بعض کا قول ہے: ضحاک بن سفیان نے اپنی بیٹی فاطمہ کو آپ صلی اللہ علیہ وسلم کے ہاں نکاح کے لیے پیش کیا اور عرض کیا: کبھی اس کے سر درد نہیں ہوا، آپ نے فرمایا: مجھے اس کی ضرورت نہیں۔ بعض کا قول ہے: آپ صلی اللہ علیہ وسلم نے ان سے ۸ھ میں نکاح کیا تھا ابن عبدالبر کا کلام ختم ہوا۔ ان کے کلام کی تشریح کی ضرورت ہے اور بعض مقامات قابل مواخذہ ہیں کہ حدیث ابن شہاب جو انہوں نے ذکر کی، وہ صحیح میں ہے۔ (لیکن اس کے آخر میں ہے: میرے والد جانے لگے۔۔۔۔۔” اور رہا قتادہ کا قول تو اسے نقل کیا ہے۔۔۔۔۔ اور رہا عکرمہ کا قول تو اسے نقل کیا ہے۔۔۔۔ ان کا یہ قول کہ یہ وہی ہیں جو آپ صلی اللہ علیہ وسلم کی وفات کے وقت زندہ تھیں، اس میں تردد ہے، کیونکہ آیت تخیر۔۔۔۔۔۔۔۔۔ اور آپ صلی اللہ علیہ وسلم نے اس کے بعد نکاح کیا۔۔۔۔۔۔۔)(4) اور ان کا قول: کہ جو یہ کہتی تھیں کہ میں بدبخت ہوں وہ پناہ چاہنے والی تھیں، اس قول کو واقدی نے بحوالہ ابن مناح روایت کیا ہے فرماتے ہیں: انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے پناہ چاہی، اور اس سے ابن اسحاق کا قول باطل نہیں ہوتا کہ کلابیہ نے اختیار کیا وہ کہتی تھیں: میں بدبخت ہوں، کیونکہ دونوں واقعات کو جمع کرنا ممکن ہے۔ رہا ان کا قول: کہ پناہ چاہنے والی میں بہت سا اختلاف ہے۔ وہ صحیح ہے، ابن سعد کا قول ہے: کلابیہ کے بارے میں اختلاف ہے، اور ان کے نام کے بارے میں اختلاف ہے: بعض کا قول ہے: فاطمہ بنت ضحاک بن سفیان، بعض نے کہا: عمرہ بنت یزید بن عبید، بعض کا قول ہے: سنا بنت سفیان بن عوف، یہ بھی قول ہے کہ یہ ایک ہیں اور ان کے نام میں اختلاف ہے، بعض نے کہا: تین ہیں، پھر واقدی نے مسنداً بواسطہ ابن ابی ذئب زہری سے نقل کیا، انہوں نے زہری سے نقل کیا ہے: فرماتے ہیں: وہ فاطمہ بنت ضحاک ہیں، آپ صلی اللہ علیہ وسلم ان کے پاس آئے تو انہوں نے آپ صلی اللہ علیہ وسلم سے پناہ مانگی آپ صلی اللہ علیہ وسلم نے انہیں طلاق دے دی وہ مینگنیاں چنا کرتی تھیں اور کہتیں: میں بدبخت ہوں۔ اسی مذکورہ سند سے بحوالہ زہری مسنداً ذکر کیا ہے، انہوں نے عروہ سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ہے، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم نے کلابیہ سے نکاح کیا، جب وہ آپ صلی اللہ علیہ وسلم کے پاس لائی گئیں، آپ ان کے قریب آئے تو کہنے لگیں: میں آپ سے اللہ کی پناہ مانگتی ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: “تم نے بڑی ہستی کی پناہ مانگی ہے، اپنے گھر والوں کے پاس چلی جاؤ۔”(5) عبدالواحد بن ابی عون کے طریق سے بحوالہ امام مناح مروی ہے، فرماتی ہیں: جس عورت نے پناہ مانگی تھی وہ شدت غم کی وجہ سے اپنی عقل کھو بیٹھی تھی۔ وہ امہات المومنین سے ملنے آتی تو اجازت لیتے وقت کہتی! میں بدبخت آئی ہوں۔ اور بتاتی تھی کہ مجھے دھوکا دیا گیا ہے۔ عمرو بن شعیب کے طریق سے بحوالہ ان کے والد اور وہ اپنے دادا سے روایت کرتے ہیں کہ ان کی رخصتی ہوئی تھی اور جب آپ صلی اللہ علیہ وسلم نے اپنی ازواج کو اختیار دیا تو انہوں نے اپنی قوم کو پسند کیا آپ صلی اللہ علیہ وسلم نے انہیں جدا کر دیا، وہ مینگنیاں چنا کرتی تھیں اور کہتیں: میں بدبخت ہوں۔ بعض کا قول ہے: پناہ مانگنے والی سنا بنت نعمان بن ابی الجون تھیں، ابن سعد نے بحوالہ واقدی اسے مسنداً نقل کیا ہے، انہوں نے محمد بن یعقوب سے، انہوں نے متعب سے، انہوں نے عبدالواحد بن ابی عون سے روایت کیا ہے، بعض کا قول ہے: اسماء بنت نعمان بن ابی الجون، واقدی نے اسے مسنداً نقل کیا ہے بحوالہ عمرو بن صالح، انہوں نے سعید بن عبدالرحمن بن ابزیٰ سے، انہوں نے ہشام بن کلیبی سے، انہوں نے اپنے والد سے، انہوں نے ابو صالح سے، انہوں نے ابن عباس سے روایت کیا ہے۔ ابو اسید ساعدی کے طریق سے صحیح میں مذکور قصہ کی طرح ہے، اس کے آخر میں ہے، وہ کہتی تھیں، مجھے بدبخت کہو دوسرے طریق سے بحوالہ ابو اسید مروی ہے کہ وہ خاتون جنہوں نے پناہ چاہی تھی وہ سیدنا عثمان رضی اللہ عنہ کی خلافت میں وفات پا گئیں۔ اور رہا ان کا قول کہ اس میں سے کچھ صحیح نہیں، عجیب ہے، کیونکہ صحیح میں ابو اسید ساعدی کی حدیث سے ان کا قصہ ثابت ہے۔ البتہ صحیح ہونے کی نفی سے مراد کلابیہ کے بارے میں یقینی قول کی نفی ہے۔ رہا ان کا قول کہ ضحاک بن سفیان نے آپ صلی اللہ علیہ وسلم کے ہاں اپنی بیٹی کو پیش کیا تھا، اور عرض کیا: اس کے سر میں درد نہیں ہوا۔ صحیح میں اسے نقل کیا گیا ہے۔ رہا یہ قول، بعض نے کہا ہے: آپ صلی اللہ علیہ وسلم نے ۸ھ میں ان سے نکاح کیا، ظاہر ہے کہ ضمیر کا مرجع سوانح والی شخصیت ہے۔ جس کا تقاضا ہے کہ اس کا متناقض قول پہلے گزر چکا ہے۔ وہ قول یہی ہے کہ آپ صلی اللہ علیہ وسلم نے اپنی صاحبزادی سیدہ زینب رضی اللہ عنہا کی وفات کے بعد ان سے نکاح کیا تھا۔ ابن سعد نے بحوالہ واقدی اسے مسنداً نقل کیا ہے، انہوں نے ابراہیم بن وثیمہ سے، انہوں نے ابی وجزہ سے اسے روایت کیا ہے، فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے کلابیہ سے ذی قعدہ ۸ھ میں حمراء الاسد سے واپسی پر نکاح کیا، اسماعیل بن مصعب ہے بحوالہ ان کے قبیلے کے کسی شیخ سے روایت ہے، وہ ۷۰ھ میں وفات پا گئیں۔","",{"fn":"(1) اسد الغابۃ (۷۱۷۹)، الاستيعاب (۵۳۰۷)، تجرید (۲۹۴/۲)\n(2) الاستيعاب (۱۸۹۹/۴)\n(3) بخاری (الحدیث ۴۷۸۵، ۴۷۸۶)\n(4) بیاض فی الاصل (اصل مسودہ میں یہ سطر خالی ہیں۔ از مترجم)\n(5) بخاری (الحدیث ۵۲۵۴)، نسائی (الحدیث ۳۴۱۷)"}],[10202,"§۱۱۵۹۳ ۔ فاطمہ بنت ابی طالب\nبعض کا قول ہے: وہ ام ہانی ہیں، کنیتوں میں ان کا ذکر آئے گا۔ ابو نعیم نے ان کا ذکر کیا ہے۔"],[10203,"§۱۱۵۹۴ ۔ فاطمہ بنت عامر\nبن حذیمہ قرشیہ۔ سعید بن عامر جو مشہور صحابی ہیں ان کی بہن ہیں، مغیرہ بن ابو العاص کی زوجہ ہیں جو سیدنا عثمان بن عفان رضی اللہ عنہ کے چچا ہیں، ان سے عائشہ پیدا ہوئیں جن سے مروان نے نکاح کیا۔ جس سے عبدالملک پیدا ہوئے، زبیر بن بکار نے یہ ذکر کیا ہے۔"],[10204,"§۱۱۵۹۵ ۔ فاطمہ بنت عبداللہ\n(1) عثمان بن ابی العاص ثقفی کی والدہ ہیں۔ ابو عمر(2) نے ان کا ذکر کیا ہے، اور فرمایا: جب حضرت آمنہ کے ہاں نبی کریم صلی اللہ علیہ وسلم پیدا ہوئے تو وہ موجود تھیں، اس وقت رات تھی، فرماتی ہیں: گھر کی ہر شے روشن تھی، اور ستارے بہت قریب نظر آ رہے تھے، یہاں تک کہ میں کہہ رہی تھی: “وہ مجھ پر آ گریں گے۔” میں کہتا ہوں: ابو عمر نے اسے مسنداً نقل کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۸۱) تجرید (۲۹۴/۲)\n(2) الاستيعاب (۱۹۰۰/۴)"}],[10205,"§۱۱۵۹۶ ۔ فاطمہ بنت عقبہ\n(1) بن ربیعہ بن عبد شمس عبشمیہ۔ سیدہ ہند کی جو سیدہ ام معاویہ کی والدہ ہیں، بہن ہیں: ان سے ام محمد بن عجلان نے روایت کی اور وہ ان کی مولاۃ ہیں، یہ ابو عمر کا قول ہے۔ میں کہتا ہوں: ابن مندہ نے اسے ابو بکر بن عیاش کے طریق سے محمد بن عجلان سے بحوالہ ان کی والدہ مسنداً نقل کیا ہے، انہوں نے سیدہ فاطمہ رضی اللہ عنہا سے روایت کیا ہے۔ فرماتی ہیں، میں نے کہا: “یا رسول اللہ صلی اللہ علیہ وسلم! میں چاہتی تھیں دنیا کے تمام گھرانوں میں سے اللہ تعالیٰ آپ کے گھرانے کو ذلیل کرے”۔ (حدیث)(2) فرماتے ہیں: اسے ابن ابی اویس نے بحوالہ اپنے والد، انہوں نے ابن عجلان سے روایت کیا ہے، اور اس میں کچھ اضافہ نقل کیا ہے۔ طبرانی رحمہ اللہ نے یعقوب بن محمد کے طریق سے بحوالہ ابو بکر بن اویس، انہوں نے ابو ایوب سے جو قاسم کے مولیٰ ہیں، انہوں نے ابن عجلان سے، انہوں نے اپنے والد سے، انہوں نے فاطمہ بنت عقبہ سے روایت کی ہے کہ ابو حذیفہ بن عقبہ انہیں اور اپنی بہن کو ساتھ لے گئے ہم نے رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی، جب آپ نے شرائط لگائیں تو ہند آپ سے کہنے لگیں: کیا ان ممنوع باتوں میں سے آپ کو اپنی قوم کی عورتوں میں کسی بات کا علم ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:(3) “ان سے بیعت کرو! یہی شرط ہے۔” ابن سعد(4) کا قول ہے: ان سے قرظہ بن عبد عمرو بن نوفل بن عبد مناف نے نکاح کیا، جس سے ولید، ہشام، مسلم، عقبہ، ابی برق، ظفر، آمنہ بنت قرظہ، اور فاختہ پیدا ہوئیں۔ فاختہ سے امیر معاویہ رضی اللہ عنہ نے نکاح کیا، پھر وہ اسلام لائیں اور بیعت کی، پھر ان سے ابو حذیفہ بن عقبہ بن ربیعہ نے نکاح کیا۔ ابن سعد نے صحیح سند سے بحوالہ ابن ابی ملیکہ نقل کیا ہے، فرماتے ہیں: عقیل بن ابو طالب نے فاطمہ بنت عقبہ بن ربیعہ سے نکاح کیا، جب وہ ان کے پاس آئے تو کہتیں: عقبہ بن ربیعہ کہاں (جنت میں یا جہنم) ہے؟ انہوں نے ان سے ایک دن کہا: جب انہیں غصہ دلایا، جب تم جہنم میں جاؤ گی تو تمہاری بائیں طرف ہوگا، دیکھ لینا۔ وہ کہنے لگیں: ہم دونوں ایک گھر میں نہیں رہ سکتے۔ سیدنا عثمان رضی اللہ عنہ کے پاس آئیں، آپ نے ابن عباس اور معاویہ رضی اللہ عنہم کو ان کے ساتھ روانہ کیا، جب یہ دونوں وہاں پہنچے، دیکھا دونوں نے صلح کر لی ہے۔ انہوں نے اسے اختصار کے ساتھ بحوالہ ابن عباس رضی اللہ عنہما موصولاً نقل کیا ہے، اور ان کی سند میں واقدی رحمہ اللہ ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۱۸۲) الاستيعاب (۳۵۰۹) تجرید (۲۹۵/۲)\n(2) مسلم (الحدیث: ۴۴۰۴) ابوداؤد (الحدیث: ۳۵۳۳)\n(3) المعجم الکبیر (۹۰۴/۲۲) مجمع الزوائد (۳۹/۶)\n(4) الطبقات الکبریٰ (۱۷۲/۸)"}],[10206,"§۱۱۵۹۷ ۔ فاطمہ بنت علقمہ\n(1) بن عبداللہ بن ابی قیس، ام معظم العامریہ، اپنے شوہر سلیط بن عمرو کے ساتھ حبشہ کی طرف ہجرت کی، ان کے ہاں سلیط بن سلیط نام پیدا ہوئے، ان کا یہی نام کنیت ابن سعد نے لکھی ہے۔ فرماتے ہیں: ان کی والدہ عاتکہ بنت اسعد بن عامر بن بیاضہ خزاعیہ ہیں، اور فرمایا: مکہ کے ابتدائی دور میں اسلام لائیں اور بیعت کی، ان کے والد کے سوانح میں گزر چکا ہے کہ وہ ام معظم ہیں، یہ ان کی کنیت ہے۔","",{"fn":"(1) تجرید (۲۹۵/۲)"}],[10207,"§۱۱۵۹۸ ۔ فاطمہ بنت عمرو بن حرام\n(1) انصاریہ۔ سیدنا جابر رضی اللہ عنہ کی پھوپھی ہیں، ان کے بھائی عمرو بن حرام کے سوانح میں ان کا نسب گزر چکا ہے، صحیح حدیث میں شعبہ کی روایت میں بحوالہ ابن المنکدر ان کا ذکر ثابت ہے، انہوں نے جابر سے روایت کی ہے، فرماتے ہیں: جب میرے والد قتل کیے گئے، تو میں ان کے چہرے سے مٹی صاف کرنے لگا اور لوگ مجھے منع کرنے لگے، میری پھوپھی فاطمہ بنت عمرو ان پر رونے لگیں۔ (الحدیث) کا یہ طیالسی کی روایت کے الفاظ بحوالہ شعبہ ہیں۔(2)","",{"fn":"(1) اسد الغابۃ (۷۱۸۳) الاستيعاب (۳۵۱۰) تجرید (۲۹۵/۲)\n(2) بخاری (الحدیث: ۱۲۴۴) مسلم (الحدیث: ۶۳۰۵)"}],[10208,"§۱۱۵۹۹ ۔ فاطمہ بنت عمرو بن حرم\n(1) ابو موسیٰ نے ذیل میں ان کا ذکر کیا ہے، اور بحوالہ مستغفری نقل کیا ہے کہ وہ فرماتے ہیں: انہیں شرف صحابیت حاصل ہے، ابو موسیٰ نے کہا ہے کہ یہ پہلے والی ہی ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۱۸۴)"}],[10209,"§۱۱۶۰۰ ۔ فاطمہ بنت قیس بن خالد\n(1) قرشیہ، فہریہ، ضحاک بن قیس کی بہن ہیں جن کے سوانح میں ان کا نسب گزر چکا ہے، عمر میں ان سے بڑی تھیں۔ ابو عمر(2) کا قول ہے: اولین مہاجرین میں سے تھیں، خوبصورت اور عقلمند تھیں، ابوبکر بن حفص مخزومی کے نکاح میں تھیں، انہوں نے طلاق دے دی، اس کے بعد اسامہ بن زید سے نکاح ہوا۔ میں کہتا ہوں: اس بارے میں صحیح(3) میں ان کی حدیث ہے، جب انہوں نے اپنے شوہر کے وکیل سے نفقہ طلب کیا، تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا: “ام شریک کے ہاں عدت گزارو۔” پھر فرمایا: “ابن ام مکتوم کے ہاں”۔ جب انہیں نکاح کے پیام آئے تو آپ نے اسامہ بن زید(4) کا مشورہ دیا، یہ مشہور قصہ ہے۔ یہ وہی ہیں جنہوں نے جساسہ کا طویل قصہ روایت کیا ہے، وہ اس طویل قصے کی روایت میں منفرد ہیں، جب وہ اپنے بھائی کو ملنے کوفہ آئیں جو امیر کوفہ تھے تو ان سے شعبی رحمہ اللہ نے روایت کی ہے جن میں حدیث جابر وغیرہ میں سے بعض سے میں مطلع ہوا۔ بعض کا قول ہے: وہ ضحاک سے دس برس بڑی ہیں، یہ ابو عمر کا قول ہے، فرماتے ہیں: ان کے گھر اہل شوریٰ جمع ہوئے جب سیدنا عمر رضی اللہ عنہ پر قاتلانہ حملہ ہوا تھا۔ ابن سعد(5) کا قول ہے: ان کی والدہ امیمہ بنت ربیعہ ہیں، جو بنو کنانہ سے ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۱۸۵) الاستيعاب (۳۵۱۱) تجرید (۲۹۵/۲)\n(2) الاستيعاب (۹۰۱/۴)\n(3) مصنف عبد الرزاق (الحدیث: ۱۲۰۲۱) مستدرک (۵۵/۴) المعجم الکبیر (۹۲۸/۲۴)\n(4) ترمذی (۱۱۸۰)\n(5) الطبقات الکبریٰ (۲۰/۸)"}],[10210,"§۱۱۶۰۱ ۔ فاطمہ بنت قیس\nبعض کا قول ہے: وہ بنت ابی حیش ہیں، اور ابو جیش کا نام قیس ہے۔"],[10211,"§۱۱۶۰۲ ۔ فاطمہ بنت المجلل\n(1) بن عبداللہ بن ابی قیس بن عبدود بن نصر بن مالک بن حسل بن عامر بن لوی قرشیہ عامریہ، ان کی کنیت ام جمیل تھی، اور وہ اسی سے مشہور ہیں۔ ابن اسحاق(2) کا قول ہے: یونس بن بکیر وغیرہ کی روایت میں ہے، حبشہ کی طرف ہجرت کرنے والوں میں ان کا ذکر ہے کہ حاطب بن حارث نے ہجرت کی اور ان کے ساتھ ان کی زوجہ فاطمہ بنت محمل تھیں، ان کے شوہر وہاں وفات پاگئے، وہ اپنے دونوں بیٹوں کو لے کر دونوں کشتی والوں کے ساتھ مدینہ آئیں۔ عبداللہ بن حارث بن محمد بن حاطب نے اپنے والد سے، انہوں نے اپنے دادا سے روایت کی ہے، فرماتے ہیں: جب ہم حبشہ کی سرزمین سے آئے تو میری والدہ مجھے لے کر نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں۔ حدیث ذکر کی۔(3) جن کا ذکر محمد بن حاطب کے سوانح میں گزر چکا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۸۶) الاستيعاب (۳۵۱۲) تجرید (۲۹۵/۲)\n(2) السیرۃ النبویۃ (۲۵۹/۱) (۶۴)\n(3) المعجم الکبیر (۵۳۵/۱۹) مجمع الزوائد (۴۱۵/۹) معرفۃ الصحابۃ (۶۶/۲)"}],[10212,"§۱۱۶۰۳ ۔ فاطمہ بنت منقذ\n(1) بن عمرو بن خنساء بن مبذول انصاریہ، بنو مازن بن نجار سے تھیں، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ ابن سعد(2) نے بھی ان کا ذکر کیا اور فرمایا: وہ ام ولد تھیں، ان سے داؤد بن ابو داؤد بن عامر بن مالک بن خنساء نے نکاح کیا، جس سے اولاد ہوئی۔","",{"fn":"(1) اسد الغابۃ (۷۱۸۷) الاستيعاب (۳۵۱۳) تجرید (۲۹۵/۲)\n(2) الطبقات الکبریٰ (۲۹۵/۲)"}],[10213,"§۱۱۶۰۴ ۔ فاطمہ بنت الولید\nبن عبد شمس بن ولید بن مغیرہ مخزومیہ، ان کے والد یمامہ میں قتل ہوئے، اور ام حکیم بنت ابو جہل ان کی والدہ ہیں، فاطمہ مذکورہ نے عثمان بن عفان سے نکاح کیا، جس سے سعید اور ولید پیدا ہوئے، بعض کا قول ہے: ان کا نام اسماء ہے۔"],[10214,"§۱۱۶۰۵ ۔ فاطمہ بنت الولید\n(1) بن عقبہ بن ربیعہ بن عبد شمس عبشمیہ، ان کے والد حالت کفر میں بدر میں قتل ہوئے۔ ان کی پھوپھی فاطمہ بنت عقبہ کا ذکر گزر چکا ہے، یہ ہجرت کرنے والی علم و فضل والی تھیں، ان کے چچا ابو حذیفہ بن عقبہ نے سالم سے ان کا نکاح کر دیا جنہیں مولیٰ ابو حذیفہ کہا جاتا تھا، وہ یمامہ میں شہید ہوئے۔ ابو عمر کا قول ہے: اس کے بعد حارث بن ہشام سے نکاح ہوا، یہی ان کا قول ہے جبکہ اس میں تامل ہے۔ جسے ابن الاثیر(2) نے بیان کیا ہے اور اس بات کو درست قرار دیا ہے کہ حارث بن ہشام کی اہلیہ ان کے بعد والی ہیں، واقعی یہی بات ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۸۸) الاستيعاب (۳۵۱۳) تجرید (۲۹۵/۲)\n(2) اسد الغابۃ (۳۷۲/۵)"}],[10215,"§۱۱۶۰۶ ۔ فاطمہ بنت الولید\n(1) بن مغیرہ بن عبداللہ بن عمرو بن مخزوم قرشیہ مخزومیہ، سیدنا خالد بن ولید کی بہن ہیں۔ ابن سعد(2) کا قول ہے۔ ان کی والدہ حکتمہ (ن ساکن اور ث کے ساتھ) بنت عبداللہ بن عمرو بن کعب کنانیہ ہیں، فتح کے دن اسلام لائیں اور بیعت کی، حارث بن ہشام کی زوجہ اور عبد الرحمن اور ام حکیم کی والدہ ہیں جو حارث کے بیٹے ہیں۔ ابو عمر(3) کا قول ہے، بعض نے کہا کہ سیدنا عمر رضی اللہ عنہ نے حارث کے بعد ان سے نکاح کیا اور اس میں تردد ہے۔ میں کہتا ہوں: ابن مندہ نے ان کے لیے عنوان قائم کیا ہے۔ فاطمہ بنت ولید قرشیہ، اور ان سے حدیث ازار نقل کی ہے، عقیلی نے اسے عبدالسلام بن حرب کے طریق سے، اسحاق بن عبداللہ بن ابو فروہ سے بحوالہ ابراہیم بن عباس بن حارث، انہوں نے ابو بکر بن حارث سے، انہوں نے فاطمہ بنت ولید سے جو ابوبکر کی والدہ ہیں، روایت کیا ہے کہ وہ ریشمی لباس کے جسے پہنتیں اور پھر ازار باندھتی تھیں، لوگوں نے کہا: اس کا کیا فائدہ؟ فرمانے لگیں: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا کہ انہوں نے بازار کا حکم دیا۔ ابن اثیر(4) کا قول ہے: یہ قول کہ ابوبکر کی والدہ ہیں یعنی ابن عبدالرحمن بن حارث بن ہشام، یہ ان کے والد کی والدہ ہیں، اور ابو بکر کی دادی ہیں، بات یہی ہے۔ ابن عساکر نے کہا ہے کہ فاطمہ بنت ولید بن مغیرہ، خالد کی بہن ہیں، انہیں شرف صحابیت حاصل ہے، اپنے شوہر حارث کے ساتھ شام گئیں ان کے بھائی خالد نے اپنے بعض معاملات میں ان سے مشورہ لیا۔ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے ایک حدیث روایت کی ہے، ان سے ان کے بیٹے ابوبکر بن عبد الرحمن نے روایت کی ہے پھر وہ حدیث ذکر کی، جس میں ازار باندھنے کا حکم ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۸۸) الاستيعاب (۳۵۱۴) تجرید (۲۹۶/۲)\n(2) الطبقات الکبریٰ (۱۹۰/۸)\n(3) الاستيعاب (۱۹۰۱/۴، ۱۹۰۲)\n(4) اسد الغابۃ (۳۷۳/۵)"}],[10216,"§۱۱۶۰۷ ۔ فاطمہ بنت یعار\nبعض کا قول ہے: وہ سالم مولی ابو حذیفہ کی مولاۃ ہیں۔"],[10217,"§۱۱۶۰۸ ۔ فاطمہ بنت الیمان العبسیہ\n(1) حذیفہ کی بہن ہیں، حذیفہ کے سوانح میں ان کا نسب گزر چکا ہے۔ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی کہ وہ خواتین کے ساتھ آپ صلی اللہ علیہ وسلم کی عیادت کرنے آئیں، ایک لٹکے ہوئے مشکیزے سے پانی قطرہ قطرہ آپ صلی اللہ علیہ وسلم پر گر رہا تھا جو بخار کی شدت کو کم کرنے کے لیے تھا، اس روایت میں ہے: “سب سے زیادہ مصائب انبیاء پر آتے ہیں پھر جو لوگ ان کے قریب ہیں”۔(2) ان سے ان کے بھتیجے ابو عبیدہ بن حذیفہ نے روایت کی، اور نسائی(3) اور ابن سعد نے قوی سند سے ان کی حدیث روایت کی، ہم نے عالی سند سے ابن مندہ کی کتاب معرفہ اور ابن مسعود بن فرات کے جزء میں اسے روایت کیا۔ ابن سعد(4) کا قول ہے: اسلام لائیں اور بیعت کی، منصور نے بحوالہ ربعی بن خراش فرمایا: میں نے مجاہد سے کہا: مجھ سے ربعی نے بحوالہ ایک خاتون، انہوں نے حذیفہ کی بہن سے روایت کیا، ان کی کئی بہنیں تھیں، جنہوں نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا۔ مجاہد رحمہ اللہ کا قول ہے: ان خاتون نے ان کا زمانہ پایا۔ حدیث سونے(5) کے زیورات کی مذمت کے بارے میں ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۹۰) الاستيعاب (۳۵۱۵) تجرید (۲۹۶/۲)\n(2) اسد الغابۃ (۳۷۴/۵)\n(3) نسائی (الحدیث: ۵۱۵۲، ۵۱۵۳)\n(4) الطبقات الکبریٰ (۲۳۸/۸)\n(5) ابوداؤد (۴۲۳۷) مسند احمد (۳۹۶/۶)"}],[10218,"§۱۱۶۰۹ ۔ فرتنی\n(1) ان دو باندیوں میں سے ایک تھیں جنہیں ابن خطل نے گانا بجانا سکھایا تا کہ وہ نبی کریم صلی اللہ علیہ وسلم اور آپ کے اصحاب کی ہجو کریں، تو یہ ان لوگوں میں سے تھیں جن کا خون فتح مکہ کے روز آپ نے بے کار قرار دیا تھا (کوئی بھی انہیں قتل کر سکتا ہے) یہ اسلام لے آئیں اور گانا بجانا ترک کیا اور دوسری قتل ہوئی، یہ سہیلی کا قول ہے۔","",{"fn":"(1) تجرید (۲۹۶/۲)"}],[10219,"§۱۱۶۱۰ ۔ الفرعۃ بنت مالک الحُدریۃ\nفریعہ میں ان کے حالات آئیں گے۔"],[10220,"§۱۱۶۱۱ ۔ فروہ بنت الحارث العتواریہ\nعقیلہ کی والدہ ہیں، عقیلہ میں ان کا ذکر گزر چکا ہے۔ خطیب کی تحریر سے میں نے اسے ف اور راء ساکن کے ساتھ پڑھا ہے۔"],[10221,"§۱۱۶۱۲ ۔ فُریعہ بنت ابی امامہ\nاسعد بن زرارہ انصاریہ۔ رفاعہ میں ان کے حالات گزر چکے ہیں۔"],[10222,"§۱۱۶۱۳ ۔ فُریعہ بنت الحباب\n(1) ابن رافع بن معاویہ بن عبید بن جراح انصاریہ، بنو ابجر سے ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔(2)","",{"fn":"(1) اسد الغابۃ (۷۱۹۳) تجرید (۲۹۶/۲)\n(2) المحبر (۴۲۲)"}],[10223,"§۱۱۶۱۴ ۔ فُریعہ بنت خالد\n(1) ابن حسین بن لوزان انصاریہ، سیدنا حسان بن ثابت رضی اللہ عنہ کی والدہ ہیں، اور انہیں کی طرف منسوب تھے، کہا جاتا: ابن فریعہ نے کہا، انہوں نے اپنے آپ کو اس شعر میں ان کی طرف منسوب کیا: “چادریں ہی چادریں ہو گئیں، جب وہ غالب آ گئے اور بڑے ہو گئے فریعہ کا بیٹا شہر کا امیر بن گیا۔” ابن سعد(2) نے بیعت کرنے والی صحابیات میں فریعہ میں ان کا ذکر کیا ہے۔ بعض کا قول ہے، ان کے والد کا نام عمرو ہے۔","",{"fn":"(1) تجرید (۲۹۶/۲)\n(2) الطبقات الکبریٰ (۲۷۱/۸)"}],[10224,"§۱۱۶۱۵ ۔ فُریعہ بنت زرارہ\nرفاعہ میں گزر چکی ہیں۔"],[10225,"§۱۱۶۱۶ ۔ فُریعہ بنت عمرو\n(1) ابن خنیس بن لوزان جو منذر بن عمرو کی بہن ہیں۔ ان کے بھائی کے سوانح میں ان کا نسب گزر چکا ہے۔ اور ان کے بھائی کا مشہور صحابہ رضی اللہ عنہم میں شمار ہے۔(2)","",{"fn":"(1) اسد الغابۃ (۷۱۹۵) تجرید (۲۹۶/۲)\n(2) الطبقات الکبریٰ (۲۷۱/۸)"}],[10226,"§۱۱۶۱۷ ۔ فُریعہ بنت عمرو\nابن لوزان سیدنا حسان کی والدہ ہیں، بعض کا قول ہے: بنت خالد، ان کا ذکر گزر چکا ہے۔"],[10227,"§۱۱۶۱۸ ۔ فُریعہ بنت قیس الأنصاریہ\n(1) بنو حجیجی سے ہیں، ابن اسحاق نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کرنے والوں میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۹۶)"}],[10228,"§۱۱۶۱۹ ۔ فُریعہ بنت مالک بن الدُّخشم\n(1) بنو عوف بن خزرج سے ہیں، ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے۔ ابن حبیب(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۹۷) تجرید (۲۹۶/۲)\n(2) المحبر (۴۲۴)"}],[10229,"§۱۱۶۲۰ ۔ فُریعہ بنت مالک\n(1) ابن سنان خُدریہ، ابو سعید کی بہن ہیں۔ ان کے بھائی کے سوانح میں ان کا نسب گزر چکا ہے۔ اکثر کے نزدیک ایک ایسی ہی ہے۔ سنن نسائی(2) میں ان کی حدیث کے سیاق میں فارعہ ہے۔ اور طحاوی رحمہ اللہ میں فرعہ ہے، ان کی والدہ حبیبہ بنت عبداللہ بن ابی ہے۔ ان کی حدیث کا مدار سعد بن اسحاق بن کعب بن عجرہ پر ہے، انہوں نے اپنی پھوپھی زینب بنت کعب بن عجرہ سے روایت کی ہے کہ فریعہ بنت مالک بن سنان جو ابو سعید خدری کی بہن ہیں، انہوں نے انہیں بتایا کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں اور آپ صلی اللہ علیہ وسلم سے پوچھا کہ کیا وہ بنو خدرہ میں اپنے گھر والوں کے پاس لوٹ سکتی ہیں، کیونکہ ان کے شوہر اپنے بھاگے ہوئے غلاموں کو تلاش کرنے نکلے ہیں، جہاں وہ قتل ہو گئے۔۔۔۔ پھر حدیث ذکر کی، اس روایت میں ہے: “اپنے گھر میں ٹھہرو یہاں تک کہ عدت پوری ہو جائے”۔ اس میں یہ بھی ہے کہ سیدنا عثمان رضی اللہ عنہ نے کسی کو بھیج کر مجھ سے اس بارے میں پوچھا، میں نے انہیں بتایا، انہوں نے اسی سے فیصلہ کیا۔(3) امام مالک رحمہ اللہ نے موطا میں اسے سعد بن اسحاق سے روایت کیا ہے اور الیاس بن مالک نے اپنے شیخ زہری سے اسے روایت کیا ہے، ابن مندہ کا قول ہے: ہمیں محمد بن یعقوب نیشاپوری نے بتایا کہ ہم سے محمد بن سلیمان بن حارث نے حدیث بیان کی، وہ فرماتے ہیں کہ ہم سے احمد بن عبد اللہ نساج نے، وہ فرماتے ہیں کہ ہم سے احمد بن سیف بن سعید نے وہ فرماتے ہیں کہ مجھے سے میرے والد نے بحوالہ یونس بن یزید، انہوں نے ابن شہاب سے وہ فرماتے ہیں کہ مجھ سے مالک بن انس نے حدیث بیان کی۔۔۔ پھر اسے ذکر کیا۔","",{"fn":"(1) اسد الغابۃ (۷۱۹۸) الاستيعاب (۳۵۱۷)\n(2) ابوداؤد (الحدیث: ۲۳۰۰)\n(3) ابوداؤد، کتاب الطلاق، باب فی المتوفی عنہا زوجہا تنتقل (۲۳۰۰)"}],[10230,"§۱۱۶۲۱ ۔ فُریعہ بنت مُعوّذ\n(1) ابن عفراء انصاریہ، ربیع کی بہن ہیں، ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے۔ ابو عمر(2) کا قول ہے، انہیں شرف صحابیت حاصل ہے۔ ان کی حدیث شادی کے موقع پر ترنم سے اشعار پڑھنے اور دف بجانے کے بارے میں ہے جو اہل بصرہ سے مروی ہے، ابن مندہ کا قول ہے: خالد بن دینار نے ان کی حدیث بحوالہ ان کی والدہ جنہوں نے ان سے روایت کیا نقل کی ہے کہ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں۔","",{"fn":"(1) اسد الغابۃ (۷۱۹۹) الاستيعاب (۳۵۱۸) تجرید (۲۹۷/۲)\n(2) الاستيعاب (۱۹۰۳/۴)"}],[10231,"§۱۱۶۲۲ ۔ قُریعہ بنت وَهَبْ الزُّہریہ\n(1) نبی کریم صلی اللہ علیہ وسلم نے اپنے ہاتھ سے ان کی طرف اشارہ کیا اور فرمایا: “جو چاہتا ہو کہ رسول اللہ صلی اللہ علیہ وسلم کی خالہ کو دیکھے تو وہ انہیں دیکھ لے۔” ابو موسیٰ(2) نے ذیل میں بحوالہ مستغفری ان کا ذکر کیا ہے اور فرمایا: اس پر اضافہ نہیں کیا۔ میں کہتا ہوں: فاختہ بنت عمرو کے سوانح میں ان کے کچھ حالات گزر چکے ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۲۰۰) تجرید (۲۹۷/۲)\n(2) اسد الغابۃ (۳۷۵/۵)"}],[10232,"§۱۱۶۲۳ ۔ فُسْحُم\n(1) بنت اوس بن خولی بن عبداللہ بن حارث انصاریہ، ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے۔ ابن حبیب(2) کا قول ہے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کی اور بنو نجی سے ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۲۰۱) تجرید (۲۹۷/۲)\n(2) المحبر (۴۲۴)"}],[10233,"§۱۱۶۲۴ ۔ فِضَّہ النوبیہ\n(1) سیدہ فاطمہ الزھراء کی باندی ہیں، ابو موسیٰ(2) نے ذیل میں اور ثعلبی رحمہ اللہ نے سورہ ﴿ھل اتی﴾ کی تفسیر میں عبداللہ ابن عبد الوہاب خوارزمی کے طریق سے جو احنف کے چچا زاد ہیں، انہوں نے احمد بن حماد مروزی سے، انہوں نے محبوب بن حمید سے اور ان سے روح بن عبادہ نے سوال کیا، انہوں نے قاسم بن بہرام سے، انہوں نے لیث بن ابو سلیم سے، انہوں نے مجاہد سے، انہوں نے ابن عباس رضی اللہ عنہما سے اللہ تعالیٰ کے اس ارشاد: ﴿وہ نذروں کو پورا کرتے ہیں﴾ (الآیۃ)(3) روایت کیا، فرماتے ہیں: سیدنا حسن اور حسین رضی اللہ عنہما بیمار ہوئے تو ان کے دادا، آپ صلی اللہ علیہ وسلم نے اور اہل عرب نے ان کی عیادت کی، انہوں نے ان کے والد سے کہا: اگر آپ نذر مان لیں؟ انہوں نے فرمایا: اللہ تعالیٰ جب انہیں شفاء دیں گے میں شکرانے کے تین روزے رکھوں گا۔ سیدہ فاطمہ رضی اللہ عنہا نے بھی یہی فرمایا اور ان کی لونڈی جنہیں فضہ تو بید کہا جاتا ہے، یہی فرمایا۔۔۔۔ پھر طویل حدیث ذکر کی۔ ذہبی رحمہ اللہ فرماتے ہیں: “یہ موضوع ہے” اور جو انہوں نے کہا یہ بات بعید نہیں۔ ابن صحر نے اپنے فوائد میں اور ابن بشکوال نے کتاب المستخیشین میں اپنے طریق سے، اس سند سے، حسین بن علاء کے طریق سے، جعفر بن محمد بن علی بن حسین بن علی سے، انہوں نے اپنے والد سے، انہوں نے سیدنا علی رضی اللہ عنہ سے روایت کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنی صاحبزادی سیدہ فاطمہ رضی اللہ عنہا کو خدمت کے لیے لونڈی دی جس کا نام فضہ نوبیہ تھا، سیدہ فاطمہ رضی اللہ عنہا کسی ایک کام کی اس سے شرط رکھتیں، رسول اللہ صلی اللہ علیہ وسلم نے اسے ایک دعا سکھائی جو دعا وہ کرتی، سیدہ فاطمہ رضی اللہ عنہا نے اس سے فرمایا: کیا تم آٹا گوندھوگی یا روٹی پکاؤ گی؟ اس نے کہا: اے میری مالکن! میں آٹا گوندھوں گی اور ایندھن کے لیے لکڑیاں لاؤں گی، وہ گئی اور لکڑیاں جمع کیں، اس کے ہاتھ میں لکڑیوں کا گٹھا تھا، اس نے اسے اٹھانا چاہا لیکن اٹھا نہ سکی، پھر اس نے ان کلمات کے ذریعہ دعا کی جو رسول اللہ صلی اللہ علیہ وسلم نے اسے سکھائے تھے، وہ یہ ہے: “اے اکیلے اللہ! اس جیسا کوئی نہیں، تو ہر ایک کو موت دے گا اور ہر ایک کو فنا کرے گا، وہ اپنے عرش پر تنہا ہے، اسے اونگھ آتی ہے اور نہ نیند۔” ایک اعرابی آیا گویا وہ ازدشنوءۃ کا تھا، اس نے لکڑیوں کا گٹھا اٹھایا اور سیدہ فاطمہ رضی اللہ عنہا کے دروازہ تک پہنچا دیا۔","",{"fn":"(1) الطبقات الکبریٰ (۲۸۰/۸)\n(2) اسد الغابۃ (۷۲۰۲) تجرید (۲۹۷/۲)\n(3) سورۃ الانسان الآیۃ (۷)"}],[10234,"§۱۱۶۲۵ ۔ فُکیہہ بنت السکن الأنصاریہ\n(1) بنو سواد سے ہیں، ابن حبیب(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ ابن سعد(3) کا قول ہے: محمد بن عمر نے ذکر کیا کہ وہ اسلام لائیں اور بیعت کی، ابن سکن فرماتے ہیں: اسماء بنت یزید بن سکن، ان کی کنیت ام عامر ہے، بعض کا قول ہے: ام عامر کا نام فُکیہہ ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۰۳) تجرید (۲۹۷/۲)\n(2) المحبر (۴۲۸)\n(3) الطبقات الکبریٰ (۲۹۰/۸)"}],[10235,"§۱۱۶۲۶ ۔ فُکیہہ بنت عبید\n(1) ابن ولیم انصاریہ بنو ٹیم سے ہیں۔ قیس بن سعد بن عبادہ کی والدہ ہیں، جو ان کے والد کے چچا کی پرورش میں تھے، ابن حبیب(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) الطبقات الکبریٰ (۷۲۰۴) تجرید (۲۹۷/۲)\n(2) الطبقات الکبریٰ (۲۷۲/۸)"}],[10236,"§۱۱۶۲۷ ۔ فُکیہہ بنت المطلب\n(1) ابن خلدہ بن خلد انصاریہ، بنو زُریق سے ہیں، ابن حبیب(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۰۵) تجرید (۲۹۷/۲)\n(2) الطبقات الکبریٰ (۲۸۴/۸)"}],[10237,"§۱۱۶۲۸ ۔ فُکیہہ بنت یزید\nابن سکن، ام عامر، کنیتوں میں ان کا ذکر آئے گا۔"],[10238,"§۱۱۶۲۹ ۔ فُکیہہ بنت یسار\n(1) خطاب بن حارث بن محی کی زوجہ ہیں، ابن اسحاق(2) نے مہاجرات میں سے ابتدائی دور میں اسلام لانے والی صحابیات میں ان کا ذکر ہے، محمد بن عثمان بن ابی شیبہ نے اپنی تاریخ میں اور ابو نعیم نے اپنے طریق سے، زیاد بکائی کی روایت سے بحوالہ ابن اسحاق سے نقل کیا ہے۔ ابن سعد(3) کا قول ہے: اسلام کے ابتدائی دور میں مکہ میں اسلام لائیں اور بیعت کی اور دو ہجرتیں کیں۔","",{"fn":"(1) اسد الغابۃ (۷۲۰۶) تجرید (۲۹۷/۲)\n(2) السیرۃ النبویۃ (۲۵۹/۱) (۲۶/۴)\n(3) الطبقات الکبریٰ (۱۷۹/۸)"}],[10239,"§۱۱۶۳۰ ۔ فاطمہ بنت الولید\nابن عبد شمس بن ولید بن مغیرہ بن عبداللہ بن عمر بن مخزوم ان کے والد یمامہ میں شہید ہوئے، ان کی والدہ ام حکیم بنت ابی جہل ہیں، ان سے سیدنا عثمان بن عفان رضی اللہ عنہ نے نکاح کیا، جس سے سعید اور ولید پیدا ہوئے۔ زبیر بن بکار نے ان کا ذکر کیا ہے۔"],[10240,"§۱۱۶۳۱ ۔ فَرْوَہ، ظفر النبی صلی اللہ علیہ وسلم\n(1) فرماتی ہیں، مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “جب تم اپنے بستر پر آؤ تو یہ سورت پڑھو(2) کہہ دو، اے کافرو!(3) کیونکہ یہ شرک سے برأت ہے۔” ابو احمد عسکری  نے ان کا ذکر کیا ہے۔ اسی طرح ابن اثیر  نے اپنے استدراک میں ان کا ذکر کیا ہے اور ذہبی رحمہ اللہ  نے بھی اسے برقرار رکھا ہے، جو خطا ہے جو تحریف سے پیدا ہوئی۔ انہوں نے جو کہا وہ بغیر تاویل و تانیث کے ہے، یہ حدیث فروہ بن نوفل کے لیے معروف ہے جو تابعین میں سے ایک شخص ہے، کسی راوی نے ابن اسحاق سے نقل کرنے میں غلطی کی ہے۔ فروہ بن نوفل، میں نبی کریم صلی اللہ علیہ وسلم کے پاس آئی اور کہا: صحیح وہی ہے جو اس کے علاوہ نے روایت کی، فرماتے ہیں: بحوالہ ابی اسحاق، انہوں نے فروہ بن نوفل دیلمی سے، انہوں نے اپنے والد سے روایت کیا، پھر اسے ذکر کیا، میں نے اسے حرف فاء کی قسم رابع میں بیان کر دیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۹۱) تجرید (۲۹۶/۲)\n(2) ابوداؤد (الحدیث: ۵۰۵۰) ترمذی (۲۴۰۲) مستدرک (۵۳۸/۲)\n(3) اسد الغابۃ (۳۷۴/۵)"}],[10241,"§۱۱۶۳۲ ۔ قُریعہ ام ابراہیم\n(1) بنت عبیط(2)، انہیں شرف صحابیت حاصل ہے۔ ابن اثیر نے استیعاب کے حاشیے میں اسے ذکر کیا ہے۔ اسی طرح تجرید میں ہے۔ اور اس کا استدراک وہم ہے۔ ابو عمر نے فارعہ میں ذکر کیا ہے۔ بنت ابی امامہ اسعد بن زرارہ، نبی کریم صلی اللہ علیہ وسلم نے نبیط بن جابر سے ان کا نکاح کر دیا، میں نے فارعہ کے سوانح میں ایک روایت ذکر کی ہے جس میں ان کا نام کسی نے فریعہ بتایا ہے۔ یہاں ذہبی کے بجائے ابن الاثیر پر زیادہ اعتراض ہوتا ہے۔ واللہ التوفیق!","",{"fn":"(1) تجرید (۲۹۶/۲)\n(2) تجرید (۱۹۵)"}],[10242,"§۱۱۶۳۳ ۔ قبیسہ بنت صَیفی\nابن صحر بن خنساء، بشر بن البراء بن معرور کی زوجہ ہیں، تجرید میں بھی ان کا ذکر ہے، حرف زاء میں زینب بنت صیفی کے سوانح میں گزر چکے ہیں، شاید وہ ان کی بہن ہیں۔"],[10243,"§۱۱۶۳۴ ۔ قُتیلہ\n(1) بعض کا قول ہے: تصغیر کے ساتھ، بنت عبد العزیٰ بن سعد بن نصر بن مالک بن حسل بن عامر بن لوی قرشیہ، عامریہ، اسماء بنت ابو بکر اور ان کے سگے بھائی عبداللہ کی والدہ ہیں۔ زبیر وغیرہ نے بھی ان کا نسب بیان کیا ہے۔ ابو موسیٰ نے ذیل میں فرمایا: قتیلہ بنت سعد بن عامر بن لوی، اسی طرح نسب کو مختصر کیا ہے اور اس میں سے ایک جماعت کو حذف کر دیا ہے، پھر فرمایا: مستغفری نے صحابیات میں ان کا ذکر کیا اور فرمایا: بعد میں اسلام لائیں، حاکم، ابو احمد نے کنیتوں میں ان کا نام لیا ہے۔ ان کی حدیث بحوالہ ہشام بن عروہ مروی ہے، انہوں نے اپنے والد سے، انہوں نے اسماء بنت ابو بکر صدیق سے روایت کی، فرماتی ہیں: میری والدہ میرے پاس آئیں اور قریش کے ساتھ معاہدہ کی مدت میں مشرکہ تھیں، میں نے رسول اللہ صلی اللہ علیہ وسلم سے ان سے صلہ رحمی کی اجازت طلب کی۔۔۔۔ (الحدیث)(2) علم یہ صحیح میں ہے، اور اس کے بعض طرق میں ہے، وہ صلہ رحمی کی رغبت رکھتی تھیں، ابو موسیٰ کا قول ہے، روایات میں ان کے اسلام کا ذکر نہیں، اور ان کے قول کہ وہ رغبت رکھتی تھیں، اس سے اسلام نہیں صلہ رحمی مراد ہے، اگر وہ مسلمان ہوتیں تو سیدہ اسماء رضی اللہ عنہا کو ان کے بارے میں صلہ رحمی کی اجازت طلب کرنے کی ضرورت نہ تھی، یہ ہو سکتا ہے کہ وہ اس کے بعد اسلام لائی ہوں۔ میں کہتا ہوں: اگر وہ فتح کے موقع تک زندہ تھیں تو ظاہر ہے کہ وہ اسلام لائیں۔","",{"fn":"(1) اسد الغابۃ (۷۲۰۷) تجرید (۲۹۷/۲)\n(2) بخاری (الحدیث: ۲۶۲۰) مسند احمد (۳۴۷/۶) (۳۵۵) المعجم الکبیر (۲۰۳/۲۴)"}],[10244,"§۱۱۶۳۵ ۔ قُتیلہ بنت صیفی الجہنیہ\n(1) بعض کا قول ہے: انصاریہ۔ ابو عمر(2) کا قول ہے، اولین مہاجرات میں سے تھیں، ان سے عبداللہ بن یسار نے روایت کی، میں نے ان کے نسب میں انصاریہ نہیں پایا، اور ان کے اس قول کہ وہ مہاجرات میں سے ہیں، اس کی تردید کرتا ہے۔ ابن سعد(3) نے ان کی حدیث نقل کی ہے اور اس طرف اشارہ کیا ہے کہ ان کی اس کے علاوہ کوئی حدیث نہیں۔ اور طبرانی(4) نے مشعر کے طریق سے بحوالہ سعید بن خالد جدلی، انہوں نے عبداللہ بن سیار سے، انہوں نے قتیلہ سے روایت کی جو جہینہ کی ایک خاتون ہیں، فرماتی ہیں، ایک یہودی آیا اور ابن سعد کی روایت میں ہے، یہودی علماء میں سے ایک عالم نبی کریم صلی اللہ علیہ وسلم کے پاس آیا اور کہنے لگا: تم لوگ شرک کرتے ہو، کہتے ہو جو کچھ اللہ چاہے اور تو چاہے، اور تم کہتے ہو: کعبہ کے رب کی قسم۔ تو نبی کریم صلی اللہ علیہ وسلم نے انہیں حکم دیا کہ وہ کہیں: “جو کچھ اللہ چاہے پھر آپ چاہیں”۔(5) نسائی نے اسے نقل کیا ہے اور اس کی سند صحیح ہے، ابن مندہ نے اسے مسعودی کے طریق سے بحوالہ سعید، انہوں نے ابن سیار سے، انہوں نے قتیلہ بنت صیفی جہنیہ سے اسے روایت کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۰۸) تجرید (۲۹۷/۲)\n(2) الاستيعاب (۱۹۰۳/۴)\n(3) المعجم الکبیر (۵۱۲۵) الحدیث (۷۰۶/۲۵)\n(4) مسند احمد (۳۷۱/۶) (۳۷۲/۶)\n(5) اسد الغابۃ (۷۲۰۹) تجرید (۲۹۸/۲)"}],[10245,"§۱۱۶۳۶ ۔ قُتیلہ بنت العرباض\n(1) بنو مالک بن حسل سے ہیں، ان کا ذکر ہے، ابن مندہ نے ان کے مختصر سوانح ذکر کیے ہیں اور ابو نعیم نے ان کی پیروی کی ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۱۰) تجرید (۲۹۸/۲)"}],[10246,"§۱۱۶۳۷ ۔ قُتیلہ بنت عمرو\n(1) ابن ہلال کنانیہ، حجۃ الوداع میں نبی کریم صلی اللہ علیہ وسلم سے بیعت کی، یہ ابن حبیب اور ابن سعد(2) کا قول ہے۔","",{"fn":"(1) الطبقات الکبریٰ (۲۱۸/۸)\n(2) اسد الغابۃ (۷۲۱۲) الاستيعاب (۳۵۲۱) تجرید (۲۹۸/۲)"}],[10247,"§۱۱۶۳۸ ۔ قُتیلہ بنت النضر\nابن حارث بن علقمہ بن کلدہ بن عبد مناف بن عبد الدار بن قصی قرشیہ، عبداللہ بن حارث بن امیہ اصغر کی زوجہ تھیں۔ علی ابن عبداللہ اور ان کے بہن بھائیوں، ولید، محمد، اور ام حکم کی والدہ ہیں، ابو عمر کا قول ہے، واقدی فرماتے ہیں: یہ وہی ہیں جب ان کے والد نضر بن حارث کو بدر کے دن آپ صلی اللہ علیہ وسلم کے حکم پر قتل کر دیا گیا تو آپ صلی اللہ علیہ وسلم کے بارے میں اشعار کہے: “اے سوار! جھاؤ کا درخت پانچویں روز کی صبح تیرا مقام ہوگا اور تجھے توفیق دی جائے گی، اس صبح ایک میت کو یہ سلام پہنچا دینا کیونکہ ہمیشہ سلام شرفاء کے گلے کا ہار رہے ہیں، وہ سلام میری طرف سے اور ساتھ جھڑتے ہوئے آنسو جو اس کے پونچھنے والے کے لیے بہہ پڑے، اور دوسروں کا دم گھٹ رہا ہے، اگر میں نفر کو پکاروں، کیا وہ واقعی میری بات سن لے گا، کبھی نہیں۔ بھلا مردہ شخص جو بولتا نہیں وہ کیسے سن سکتا ہے، اس کے بھائیوں کی تلوار میں اسے نوچنے لگیں، اللہ کے لیے ان رشتہ داریوں کا خیال کرو جو آپس میں بٹی ہوئی ہیں، ایک شیر کو زبردستی موت کی جانب لے جایا جا رہا ہے وہ بیڑیوں میں جکڑا ہوا ہے وہ مشقت میں ہے۔ اے محمد صلی اللہ علیہ وسلم! آپ کی والدہ اپنی قوم کی انتہائی شریف خاتون تھیں اور ان کے خاوند خاندانی شریف آدمی تھے۔ آپ اگر احسان کر دیتے تو آپ کا کیا جاتا تھا، کئی دفعہ سخت دشمن اور کینہ ور نوجوان بھی احسان کر دیتا ہے۔ اگر آپ قرابت و رشتہ داری کی وجہ سے چھوڑ دیتے تو مدد قریب تھی، بلکہ وہ حقدار تھے اگر گردن چھوڑ دی جاتی۔(1) جب رسول اللہ صلی اللہ علیہ وسلم کو یہ اشعار پہنچے تو آپ صلی اللہ علیہ وسلم روئے یہاں تک کہ آپ صلی اللہ علیہ وسلم کی ریش مبارک تر ہو گئی اور فرمایا: “اگر ان کے قتل ہونے سے پہلے مجھے یہ اشعار پہنچتے تو میں اسے قتل کرنے کا حکم نہ دیتا۔” ابو عمر کا قول ہے: یہ عبداللہ بن ادریس کے الفاظ ہیں اور زبیر بن بکار کی روایت میں ہے، نبی کریم صلی اللہ علیہ وسلم پر رقت طاری ہو گئی یہاں تک کہ آپ صلی اللہ علیہ وسلم کی آنکھوں سے آنسو بہنے لگے، آپ صلی اللہ علیہ وسلم نے ابو بکر رضی اللہ عنہ سے فرمایا: “اے ابو بکر! اگر میں اس کے اشعار پہلے سن لیتا تو اس کے والد کے قتل کا حکم نہ دیتا۔” زبیر فرماتے ہیں: میں نے بعض اہل علم سے سنا ہے کہ وہ اشارہ بتاتے ہیں کہ یہ اشعار مصنوعی ہیں۔ میں کہتا ہوں: مجھے ان کے اسلام لانے کے بارے میں کوئی واضح روایت نہیں ملی۔ لیکن اگر وہ فتح کے موقع پر زندہ تھیں تو وہ صحابیات میں سے ہیں، میں نے جاحظ کی کتاب البیان کے آخر میں لکھا پایا ہے کہ ان کا نام “لیلیٰ” ہے، اور فرمایا کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کی چادر مبارک کھینچی، اس وقت آپ صلی اللہ علیہ وسلم طواف فرما رہے تھے۔ پھر یہ مذکورہ اشعار پڑھے۔","",{"fn":"(1) اسد الغابۃ (۳۸۰/۵) البیان والتبیین (۴۳/۴، ۴۴) نسب قریش عصب الزبیری (۲۵۵)"}],[10248,"§۱۱۶۳۹ ۔ قُرصافہ بنت الحارث\nابن عوف، بعض کا قول ہے: یہ بڑصاء کا نام ہے اور ان کی حدیث ان کے والد کے سوانح میں ہے۔"],[10249,"§۱۱۶۴۰ ۔ قُرَّۃ العین بنت عبادہ\n(1) بن فضلہ بن مالک بن عجلان انصاریہ، بنو عوف بن خزرج سے ہیں، سیدنا عبادہ بن صامت کی والدہ ہیں۔ ابن اثیر(2) نے ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۱۳) تجرید (۲۹۸/۲)\n(2) اسد الغابۃ (۳۸۰/۵)"}],[10250,"§۱۱۶۴۱ ۔ قُریبہ\n(1) بعض کا قول ہے: تصغیر کے ساتھ۔ بنت ابی امیہ المغیرہ مخزومیہ، سیدہ ام سلمہ رضی اللہ عنہا کی بہن ہیں، ان کے بھائی عبداللہ کے سوانح میں ان کا نسب گزر چکا ہے، سیدہ ام سلمہ رضی اللہ عنہا یوں فرماتی ہیں: جب میرے ہاں زینب کی ولادت ہوئی تو رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے اور مجھے نکاح کا پیغام دیا، پھر انہوں نے اپنے نکاح کا قصہ ذکر کیا، اور آپ صلی اللہ علیہ وسلم کے ان کے پاس آنے اور ان کے زینب بنت ام سلمہ کو دودھ پلانے کا قصہ بیان کیا، یہاں تک کہ آپ صلی اللہ علیہ وسلم ایک دن تشریف لائے اور انہیں نہیں پایا تو پوچھا: “زینب کہاں ہے؟” قریبہ ابھی بولی ہی تھیں کہ خادمہ نے بھی ان کا ساتھ دیتے ہوئے کہا کہ عمار بن یاسر (جو سیدہ ام سلمہ رضی اللہ عنہا کے رضاعی بھائی بنتے تھے) لے گئے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “آج شب تمہارے ہاں آؤں گا۔”(2) پھر سیدہ ام سلمہ رضی اللہ عنہا کے ہاں تشریف لائے۔ بلاذری کا قول ہے ان سے معاویہ بن ابی سفیان نے اسلام لانے کے بعد نکاح کیا۔ ابن سعد(3) کا قول ہے: یہ قریبہ صغریٰ ہیں، ان کی والدہ عاتکہ بنت عقبہ بن ربیعہ ہیں، فرماتے ہیں: ان سے عبدالرحمن ابن ابو بکر نے نکاح کیا، جس سے عبداللہ، ام حکیم اور حفصہ پیدا ہوئیں۔ پھر اس روایت کی صحیح سند کو ابن ابی ملیکہ تک لے گئے ہیں، فرماتے ہیں: عبدالرحمن نے قریبہ سے جو ام سلمہ کی بہن ہیں، نکاح کیا، ان کے مزاج میں تیزی تھی، وہ ان سے ایک دن کہنے لگیں: اللہ کی قسم! مجھے آپ سے ڈر لگتا ہے۔ انہوں نے کہا: تمہارا معاملہ تمہارے اختیار میں ہے، کہنے لگیں: میں صدیق کے بیٹے کو چھوڑ کر کسی اور کو اختیار نہیں کروں گا، اور ان کے پاس رہیں۔ میں کہتا ہوں: صاحب جمال تھیں، عمر بن فتہ نے کتاب مکہ میں بحوالہ یعقوب بن قاسم طلحی، انہوں نے یحیی بن عبداللہ ابن ابی حارث زمعی سے نقل کیا ہے، فرماتے ہیں: جب مکہ فتح ہوا، نبی کریم صلی اللہ علیہ وسلم نے سعد بن عبادہ رضی اللہ عنہ سے فرمایا: جب انہوں نے کہا کہ ہم نے قریش کی عورتیں اتنی خوبصورتی پائی نہیں جتنا ان کے حسن و جمال کا چرچا تھا۔ تو آپ صلی اللہ علیہ وسلم نے یہ ارشاد فرمایا تھا: “کیا تم نے ابو امیہ بن مغیرہ کی بیٹیوں کو دیکھا ہے؟ کیا تم نے قریبہ کو دیکھا ہے؟” (الحدیث)","",{"fn":"(1) اسد الغابۃ (۷۲۱۴) تجرید (۲۹۸/۲)\n(2) مصنف عبد الرزاق (۱۰۶۴۴)\n(3) الطبقات الکبریٰ (۶۶/۸)"}],[10251,"§۱۱۶۴۲ ۔ قُریبہ بنت زید\n(1) ابن عبدربہ انصاریہ، بنو شم سے ہیں۔ ابن حبیب(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ ابن سعد(3) کا قول ہے، عبداللہ بن زید کی بہن ہیں جنہیں اذان کا خواب دکھائی دیا تھا۔","",{"fn":"(1) اسد الغابۃ (۷۲۱۶) تجرید (۲۹۸/۲)\n(2) المحبر (۴۲۱)\n(3) الطبقات الکبریٰ (۲۶۵/۸)"}],[10252,"§۱۱۶۴۳ ۔ قُریبہ بنت ابی سفیان\nابن حرب امویہ، سیدنا معاویہ رضی اللہ عنہ کی بہن ہیں۔ صاحب تاریخ مظفری نے ان کا ذکر کیا ہے۔ فرمایا: انہیں اہل بدر میں سے چودہ مردوں نے نکاح کا پیغام دیا، انہوں نے انکار کر دیا اور عقیل بن ابی طالب سے نکاح کیا، فرماتی ہیں: وہ بدر کے دن ان کے محبوب لوگوں کے ساتھ تھے، یعنی ان کے والد ان کے بھائی حنظلہ، دادا عتبہ، ان کے بھائی شیبہ، اور جو بدر کے معرکہ میں مشرکین کا ساتھ دے رہے تھے۔"],[10253,"§۱۱۶۴۴ ۔ قُریبہ بنت ابی قحافہ\n(1) سیدنا صدیق اکبر رضی اللہ عنہ کی بہن ہیں۔ ابن سعد نے ان کا ذکر کیا ہے، قیس بن سعد بن عبادہ نے ان سے نکاح کیا، اولاد نہ ہوئی، سیدہ ام فروہ کی سگی بہن ہیں۔","",{"fn":"(1) تجرید (۲۹۸/۲)"}],[10254,"§۱۱۶۴۵ ۔ قُریرہ بنت الحارث العُتواریہ\n(1) حرف عین میں ان کی بیٹی عقیلہ عتواریہ کے سوانح میں ان کا ذکر گزر چکا ہے۔(2)","",{"fn":"(1) الطبقات الکبریٰ (۱۸۱/۸)\n(2) الطبقات الکبریٰ (۷۲/۷) تجرید (۲۹۸/۲)"}],[10255,"§۱۱۶۴۶ ۔ قُسرہ بنت رؤاس الکندیہ\n(1) ابو نعیم نے ان کا ذکر کیا ہے، اور عبدالرحمن بن عمرو بن جبلہ کے طریق سے جو ایک متروک راوی ہیں نقل کیا ہے، فرماتے ہیں: ہم سے میسرہ بنت طفیل طائیہ نے بحوالہ ثعلبہ بنت عبداللہ، انہوں نے قسرہ کندیہ سے روایت کیا ہے۔ فرماتی ہیں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “اے قسرہ! گناہوں کے وقت اللہ کا ذکر کرو، وہ تمہیں مغفرت کے وقت یاد رکھے گا، اپنے خاوند کی اطاعت کرو، وہ دنیا اور آخرت کے شر سے تمہیں کافی ہوگی، اپنے والدین سے اچھا سلوک رکھو تمہارے گھر کی خیر و برکت بڑھے گی”۔(2) ابو عمر(3) کا قول ہے: قرہ، بعض نے زبر اور سین سے لکھا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۱۸) الاستيعاب (۳۵۲۲) تجرید (۲۹۸/۲)\n(2) جامع المسانید والسنن (۶۷/۱۶)\n(3) الاستيعاب (۱۹۰۶/۴)"}],[10256,"§۱۱۶۴۷ ۔ القُصواء\n(1) قاسم بن غنام کی دادی ہیں۔ مسند ابن سنجر میں ان کی حدیث ہے، اسی طرح تجرید میں ہے۔","",{"fn":"(1) تجرید (۲۹۸/۲)"}],[10257,"§۱۱۶۴۸ ۔ قُفیرہ\n(1) ہلالیہ، بعض کا قول ہے: ملیکہ، ابو علی غسانی نے الاستيعاب کے ذیل میں فرمایا: مسلم نے وحدان میں ان کا ذکر کیا ہے۔ اور فرمایا: عبد اللہ بن ابی حدرد کی زوجہ ہیں، ان سے اعرج کے علاوہ کسی نے روایت نہیں کیا۔","",{"fn":"(1) اسد الغابۃ (۷۲۱۹) الاستيعاب (۳۵۲۳) تجرید (۲۹۸/۲)"}],[10258,"§۱۱۶۴۹ ۔ قُہطم بنت علقمہ\n(1) ابن عبد اللہ بن ابی قیس، سلیط بن عمرو کی زوجہ ہیں۔ ابن اسحاق(2) نے ذکر کیا ہے کہ انہوں نے اور ان کے شوہر نے حبشہ کی طرف ہجرت کی، پھر کشتی والوں کے ساتھ مدینہ کی طرف لوٹ آئے۔","",{"fn":"(1) اسد الغابۃ (۷۲۲۰) تجرید (۲۹۸/۲)\n(2) السیرۃ النبویۃ (۲۶۰/۱)"}],[10259,"§۱۱۶۵۰ ۔ قَیلہ بنت مخرمہ التمیمیہ\n(1) پھر بنو عنبر سے ہیں، جنہوں نے انہیں غنویہ کہا، ان سے لفظی غلطی ہوتی ہے۔ حریث بن حسان کے ساتھ نبی کریم صلی اللہ علیہ وسلم کی طرف ہجرت کی، جو بنو بکر بن وائل کے سفیر ہیں، ان کی حدیث عبداللہ بن حسان عنبری نے اپنی دونوں دادیوں صفیہ اور ذھیبہ سے جو علیہ کی بیٹیاں ہیں، روایت کی، وہ دونوں قبیلہ کی پرورش میں تھیں، اور قبیلہ ان کے والد کی دادی تھیں، وہ فرماتی ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آئی، پھر طویل حدیث ذکر کی، طبرانی(2) نے یہ طویل حدیث بیان کی۔ امام بخاری رحمہ اللہ نے “الادب المفرد” میں اس میں سے کچھ حصہ اور ابوداؤد(3) نے بھی ایک حصہ نقل کیا، اور ترمذی(4) نے مرفوع روایت کے شروع سے “یتعاونان” تک ذکر کی ہے، فرماتے ہیں: پھر طویل حدیث ذکر کی، اور فرمایا: ہم اسے عبداللہ بن حسان کی حدیث سے جانتے ہیں۔ ابو عمر(5) کا قول ہے، وہ طویل، فصیح اور حسن حدیث ہے، اور علم غریب الحدیث والوں نے اس کی اور شرح کی ہے۔ ابوعلی بن سکن فرماتے ہیں: ان سے طویل حدیث مروی ہے، اس میں فصیح کلام ہے، اور اس طریق سے اسے روایت کیا ہے، بحوالہ عبداللہ بن حسان، اسے مختصر بیان کیا اور فرمایا کہ اسے عبداللہ بن حسان کے علاوہ کسی نے روایت نہیں کیا، فرماتے ہیں: اس میں ہے: “قیلہ کی والدہ صفیہ بنت صیفی ہیں، جو اکثم بن صیفی کی بہن ہیں”۔ میں کہتا ہوں: طبرانی نے اور ابن مندہ نے اسے طویل نقل کیا ہے۔ یہ ابن مندہ کے تین طرق سے الفاظ ہیں، بحوالہ عبداللہ بن حسان، اس سند کے ساتھ کہ انہوں نے ان دونوں کو بتایا کہ وہ حبیب بن ازھر کی زوجہ تھیں جو بنو جناب کے ایک مرد ہیں، ان سے لڑکیاں پیدا ہوئیں، بعد میں حبیب کا انتقال ہو گیا تو بچیوں کے چاچا اثوب بن ازھر نے بھابھی سے بھتیجیاں چھین لیں۔ ان کی قوم نئی نئی مسلمان ہوئی تھی، وہ رسول اللہ صلی اللہ علیہ وسلم سے شرف صحابیت حاصل کرنا چاہتی تھیں تو اپنے گھر سے نکل پڑیں ان کی سب سے چھوٹی بیٹی رونے لگیں جس کا نام حدیباء تھا اس نے اونی لباس پہن رکھا تھا، موقعہ کو غنیمت جانا اور اسے ساتھ سوار کر لیا، اسی اثناء میں کہ وہ دونوں اونٹ کو ہلکی چال سے لے جارہی تھیں کہ اچانک ایک خرگوش سامنے آ گیا، حدیباء کہنے لگیں: “خیر سے محرومی شر سے رہائی”۔ اللہ کی قسم! اس بارے میں ہمیشہ تیری شان اثوب سے بلند رہے گی۔ پھر جب لومڑی سامنے آئی تو اس کا کوئی اور نام لیا اور اس کے متعلق بھی وہی بات کہی جو خرگوش کی بابت کی تھی۔ وہ دونوں دھیرے دھیرے اونٹ چلاتی جا رہی تھیں کہ یکا یک اونٹ بیٹھ گیا اور کانپنے لگا۔ حدیباء بولی: لگتا ہے آپ کو اور امانت تک اثوب کی پہنچ ہو جائے گی۔ فرماتی ہیں: میں نے اس سے عاجزانہ کہا: بتاؤ میں کیا کروں؟ وہ کہنے لگی: اپنے کپڑے الٹے پہنو اور اپنی پیٹھ کو پیٹ کی جانب لڑھکا لو۔ اپنے اونٹ کے ٹاٹ پلٹ دو، پھر اونٹ کا کالا کمیل پلٹ دیا اس کے بعد قلابازی کھائی جب میں یہ کام کر چکی تو اونٹ چنگا بھلا ہو کر کھڑا ہو گیا پھر بیٹھا اور پیشاب کرنے لگا۔ وہ کہنے لگی: اس پر اپنے کان لگاؤ، میں نے ایسا ہی کیا تو وہ پھر کانپنے لگا۔ کیا دیکھتی ہوں کہ اثوب ہمارے نقش قدم پر تلوار سونتے دوڑا آ رہا ہے۔ ہم نے بڑے بڑے گھروں کے پیچھے پناہ لی۔ اونٹ ایک درمیانی گھر کے برآمدے کا چکر لگا کر بیٹھ گیا وہ اونٹ بڑا رام و فرمانبردار تھا۔ پھر وہاں سے اٹھ کر اندر جا گھسا۔ اتنے میں اثوب تلوار لیے مجھ تک آپہنچا کہ تلوار کی نوک اس کے بالوں کو چھورہی تھی لگتا تھا ابھی وار کرنے کو ہے۔ مجھ سے کہتا ہے: اری کنیز! میری بھیجی مجھے دے دے۔ میں نے بچی اس کی طرف تھمادی جسے اس نے اپنے کندھے پر بٹھا لیا اور چلتا بنا۔ گھرانے کے لوگوں میں سے میں اس کی طبیعت سے زیادہ واقف تھی۔ پھر میں اپنی اس بہن کی جانب چل پڑی جس کی بنی شیبان میں شادی ہوئی تھی تا کہ رسول اللہ صلی اللہ علیہ وسلم کا ساتھ نصیب ہو جائے۔ ایک رات میں اس کے گھر میں تھی وہ سمجھ رہی تھی کہ میں سوئی پڑی ہوں، اتنے میں اس کا خاوند دیہاتی بیٹھک سے آ کر کہنے لگا: تیرے باپ کی قسم! میں نے قبیلہ کے لیے ایک سچا آدمی تلاش کر لیا ہے۔ میری بہن جھٹ سے بولی: کون؟ کہنے لگا: حریث بن حسان شیبانی، بکر بن وائل کا قاصد، اس پر میری بہن کہنے لگی: میرا کچھ نہ رہے۔ میری بہن سے مت کہنا۔ بھلا وہ بکر بن وائل کے آدمی کے ساتھ ایسی جگہ کیسے جائے گی جہاں اس کا سننے دیکھنے والا کوئی نہیں۔ کم از کم اس کی قوم کا کوئی اور مرد تو ساتھ ہوتا۔ وہ کہنے لگا: میں اس سے اس بات کا تذکرہ نہیں کروں گا۔ وہ بولی: میں بھی یہ بات بتانے کی نہیں۔ صبح ہوتے ہی میں نے اپنے اونٹ پر سامان باندھا، کسی کی آواز سنائی دی، میں نے اسے تلاش کیا تو وہ معمولی فاصلے پر تھا میں نے اس کے ساتھ جانے کا پوچھا، وہ کہنے لگا: ٹھیک ہے، اس کی سواریاں اس کے پاس بیٹھی تھیں۔ ہم اس بچے شخص کے ساتھ روانہ ہو گئے اور مدینہ پہنچے نبی کریم صلی اللہ علیہ وسلم نماز فجر پڑھا رہے تھے، جونہی صبح پھوٹی اس وقت نماز قائم کی گئی ستارے آسمان پر چمک رہے تھے، اندھیرا اتنا تھا کہ لوگوں کی پہچان نہیں ہو رہی تھی۔ میں نے مردوں کی صف میں نیت باندھ لی، میں چونکہ جاہلیت کے دور سے نئی نئی اسلام میں داخل ہوئی تھی، اسی صف میں سے ایک مرد مجھے کہنے لگا: کیا تو مرد ہے یا عورت؟ میں نے کہا: نہیں! میں عورت ہوں۔ وہ کہنے لگا: مجھے تو تو نے فتنہ میں ڈال دینا تھا، پیچھے عورتوں کی صف میں نماز پڑھ۔ میں نے دیکھا کہ حجروں کے پاس عورتوں کی صف بنی تھی، لیکن جب میں مسجد میں داخل ہوئی تھی اس وقت مجھے نظر نہ آئی۔ پھر میں ان میں شامل ہوگئی اور ان کے ساتھ ہی رہی۔ پھر جب سورج طلوع ہوا تو میں منبر کے قریب ہوگئی، جونہی مجھے کوئی چادر اور لباس والا مرد دکھائی دیتا تو میری نگاہیں ادھر لگ جائیں تا کہ میں رسول اللہ صلی اللہ علیہ وسلم کو دیکھ سکوں۔ جونہی سورج بلند ہوا، ایک شخص آ کر کہنے لگا: “السلام عليك يا رسول الله” آپ صلی اللہ علیہ وسلم نے فرمایا: “وعليك السلام و رحمة الله”۔ آپ ایک یا دو پرانے کپڑے جن پر زعفران لگی تھی زیب تن فرما تھے وہ تڑ تڑا رہے تھے۔ آپ صلی اللہ علیہ وسلم کے دست مبارک میں کھجور کی ایک شاخ تھی، جس کے سر پر دو پتوں کے علاوہ باقی خالی تھی، آپ صلی اللہ علیہ وسلم اکڑوں بیٹھے تھے۔ میں نے جب رسول اللہ صلی اللہ علیہ وسلم کو اس طرح عاجزی کی حالت میں بیٹھے دیکھا تو مجھ پر بے تحاشا رعب طاری ہو گیا۔ اور میں کانپنے لگی۔ آپ صلی اللہ علیہ وسلم کے پاس بیٹھے شخص نے کہا: اللہ کے رسول صلی اللہ علیہ وسلم! یہ بے چاری ڈرگئی ہے، آپ صلی اللہ علیہ وسلم نے مجھے دیکھے بغیر اشارہ کیا میں آپ کی پیٹھ پیچھے تھی: “اے مسکین عورت! وقار و اطمینان سے رہ”۔ آپ صلی اللہ علیہ وسلم نے جب یہ جملہ ارشاد فرمایا تو سارا خوف و ہراس اللہ تعالیٰ نے دور فرما دیا۔ میرے ساتھ آنے والا شخص آگے بڑھا، اسلام اور اپنی قوم کی امان کی خاطر بیعت کی۔ پھر کہنے لگا اللہ کے رسول صلی اللہ علیہ وسلم! ہمارے اور بنی تمیم کے درمیان ایک تحریر مقام دھناء کے متعلق لکھ دیں، جہاں سے ہمارے پاس صرف مسافر اور راہ گزر ہی آیا کرے۔ آپ علیہ السلام نے فرمایا: نوجوان! دھناء کے متعلق تحریر لکھ دو۔ میں نے جب دیکھا کہ آپ صلی اللہ علیہ وسلم کے اس کے بارے میں فرمان جاری کر چکے ہیں، مجھے خیال آیا ارے وہ تو میرا وطن اور میری جائے پیدائش میں ہے۔ میں جھٹ سے بولی: اللہ کے رسول صلی اللہ علیہ وسلم! ان صاحب نے آپ سے جب زمین کا سوال کیا تو برابری کا سوال نہیں کیا، حالانکہ وہ زمین تو اونٹوں کو باندھنے، بکریوں کو چرانے کی زمین ہے اور بنی تمیم کی عورتیں اور بچے تو اس کے ورے ہیں۔ اس پر آپ صلی اللہ علیہ وسلم نے فرمایا: “نوجوان! ذرا رکنا! اس مسکین خاتون نے سچ کہا۔ مسلمان، مسلمان کا بھائی ہوتا ہے، درخت اور پانی ان کے لیے گنجائش رکھتے ہیں۔ اور وہ دونوں آگ جلانے میں ایک دوسرے سے تعاون کرتے ہیں۔” حریث نے جب دیکھا کہ اس کی منشا میں رکاوٹ پیدا ہوگئی تو وہ تالی بجا کر کہنے لگا: اری! میری اور تیری مثال تو یہ کہاوت ہے: اس کی موت اسے جدا کرنے والی ہے جسے وہ اپنے گھروں سے اٹھائے ہوئے ہے (ایک شخص کہیں سے بکری لایا لیکن ذبح کرنے کے لیے چھری نہ ملی، اچانک بکری نے کھروں سے زمین کریدی نیچے سے چھری برآمد ہوگئی)۔ میں نے کہا: اللہ کی قسم! اگر چہ تو تاریکیوں میں رہنما بن کر اور رفیق سفر کے لیے پاکدامن مرد ثابت ہوا ہے یہاں تک کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس آ گئے لیکن یاد رکھو! جب تم نے اپنا حق مانگا ہے تو مجھے اپنا حق مانگنے پر ملامت کیوں کرتے ہو؟ اس نے کہا: دھناء میں تیرا کیا حق ہے؟ میں نے کہا: وہ میرے اونٹوں کے باندھنے کی جگہ ہے، جسے تم اپنی بیوی کے لیے مانگ رہے ہو۔ وہ بولا: یقیناً میں رسول اللہ صلی اللہ علیہ وسلم کو اس بات کا گواہ بنا کر کہتا ہوں کہ جب تک تم زندہ رہی میں تمہارا بھائی ہوں۔ اگر تم رسول اللہ صلی اللہ علیہ وسلم کے سامنے میری یہ تعریف کر دو۔ میں نے کہا: جب تم نے ہی اس کا آغاز کر دیا ہے تو میں بھی اس کی لاج رکھوں گی۔ رسول اللہ صلی اللہ علیہ وسلم فرمانے لگے: کیا اہل محبت کو ملامت کیا جاتا ہے کہ وہ خطہ ارض علیحدہ کر کے اور حجرہ کے پیچھے انتظار کرنے، فرماتی ہیں: میں تو رونے لگی اور رو کر عرض کرنے لگی: اللہ کے رسول! میں “حرام” کی اولاد میں سے تھی جس نے ربذہ میں آپ کی معیت میں جنگ کی پھر خیبر سے غلہ لینے گئے وہاں انہیں بخار ہوا جس سے وہ فوت ہو گئے۔ آپ علیہ السلام نے فرمایا: اگر تو بے چاری نہ ہوتی تو ہم تجھے چہرہ کے بل گھسیٹتے، کیا تم میں سے کسی عورت سے اتنا بھی نہیں ہو سکتا کہ وہ اپنی کسی سہیلی کے ساتھ دنیا میں اچھا برتاؤ کرے۔ جب اس میں اور جو اس کا زیادہ حقدار ہے کوئی حائل ہو جاتا ہے تو وہ افسوس کرتا ہے۔ پھر فرمایا: “اے میرے رب! جو کچھ میں نے جاری کیا اسے مجھے فراموش کرا دے اور جو میں نے باقی رکھا اس کے بارے میں میری مدد فرما۔ اس ذات کی قسم! جس کے دست قدرت میں میری جان ہے! تم عورتوں میں سے کوئی روتی ہے پھر اس کی سہیلی اس کے پاس پناہ طلب کرنے آتی ہے۔ اے اللہ کے بندو! اپنے بھائیوں کو اذیت و عذاب نہ پہنچاؤ۔” پھر چمڑے کے ایک ٹکڑا پر ان کے لیے تحریر لکھوائی: “قیلہ اور قبلہ کی بیٹیوں کو نہ ظلم کا نشانہ بنایا جائے اور نہ کسی غلط کام پر مجبور کیا جائے، ہر مومن و مسلمان ان کا اچھا مددگار ہے اور انہیں پریشان نہ کیا جائے۔”","",{"fn":"(1) اسد الغابۃ (۷۲۲۳) تجرید (۲۹۹/۲)\n(2) المعجم الکبیر (۲۵/۱)\n(3) ابوداؤد، کتاب الخراج والإمارۃ والفی، باب فی إقطاع الأرضین (۳۰۷۰)\n(4) ترمذی، کتاب الأدب، باب ما جاء فی الثوب الأخضر الحدیث (۲۸۱۴)\n(5) الاستيعاب (۱۹۰۶/۴)"}],[10260,"§۱۱۶۵۱ ۔ قَیلہ الأنماریہ\n(1) انہیں بنی انمار کی ماں اور بنی انمار کی بہن کہا جاتا تھا۔ طبری فرماتے ہیں: عقیلیہ، ابن ابی خیثمہ انصاری کا قول ہے، بنو انمار کی بہن، انہیں شرف صحابیت حاصل ہے، انہوں نے اور ابن ماجہ نے عبداللہ بن عثمان بن خیثم کے طریق سے جو انہوں نے ان سے روایت کی، حدیث نقل کی ہے، فرماتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو مروہ کے پاس دیکھا، آپ اپنے عمرہ سے حدود حرم سے حدود حل میں داخل ہو رہے تھے۔ میں نے کہا: میں خرید و فروخت کرتی ہوں، اور خرید سے زیادہ بھاؤ کر لیتی ہوں، پھر مجھے مال کم کرنا پڑتا ہے۔۔۔۔ (الحدیث)(2) اس میں ہے: ایسا نہ کیا کرو۔ ابن سعد(3) نے اس طویل روایت کو ابن خیثم سے نقل کیا ہے، اور اسے ابن سکن نے نقل کیا ہے، ان کی روایت میں ہے کہ حضرت عبداللہ بن عثمان بن خیثم نے فرمایا کہ انہوں نے قبیلہ سے سنا، اور فاکہی فرماتے ہیں: ام انمار کا مکہ میں گھر ہے اور وہ پچھلے دور کی خواتین میں سے فضیلت و بہادری میں اپنا مقام رکھتی تھیں۔","",{"fn":"(1) اسد الغابۃ (۷۲۲۱) الاستيعاب (۳۵۲۵) تجرید (۲۹۹/۲)\n(2) ابن ماجہ (۱۲۲۰۴) المعجم الکبیر (۴/۲۵) جامع المسانید والسنن (۶۸، ۶۹/۱۶)\n(3) الطبقات الکبریٰ (۳۱۱/۸)"}],[10261,"§۱۱۶۵۲ ۔ قَیلہ الخزاعیہ\n(1) ام سباع بن عبد العزیٰ بن عمرو بن نصلہ، بنو زھرہ کے حلیف تھے۔ ابن عبدالبر(2) نے ان کا ذکر کیا ہے اور فرمایا: ان کے بارے میں تردد ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۲۲) تجرید (۲۹۹/۲)\n(2) الاستيعاب (۱۹۰۶/۴)"}],[10262,"§۱۱۶۵۳ ۔ قَیلہ بنت قیس\n(1) ابن معدیکرب کندیہ، اشعث بن قیس کی بہن ہیں۔ یہ ابو عمر کا قول ہے۔ بعض کا قول ہے: قبیلہ، ان سے نبی کریم صلی اللہ علیہ وسلم نے واہ میں نکاح کیا، وہ وفات پا گئیں۔ آپ صلی اللہ علیہ وسلم کے پاس نہیں لائی گئیں، آپ صلی اللہ علیہ وسلم نے انہیں دیکھا، نہ رخصتی ہوئی، بعض کا قول ہے: آپ صلی اللہ علیہ وسلم کا ان سے نکاح وفات سے دو ماہ قبل ہوا تھا، بعض کا قول ہے: آپ صلی اللہ علیہ وسلم نے اپنی مرض وفات میں ان سے نکاح کیا، بعض کا قول ہے: آپ صلی اللہ علیہ وسلم نے وصیت فرمائی کہ انہیں اختیار دیا جائے، اگر چاہیں تو ان پر حجاب لازم قرار دیا جائے اور امہات المؤمنین میں شامل ہوں، اور اگر چاہیں اور نکاح کر لیں، تو انہوں نے نکاح کو اختیار کیا تو ان سے عکرمہ نے حضرت موت میں نکاح کر لیا، جب سیدنا ابو بکر رضی اللہ عنہ کو یہ بات پہنچی تو فرمایا: میں چاہتا ہوں کہ ان دونوں کو ان کے گھر سمیت جلا دوں، تو سیدنا عمر رضی اللہ عنہ نے فرمایا: نہ وہ امہات المؤمنین میں سے ہے، نہ ہی اس کی رخصتی ہوئی ہے، اور اس کے لیے حجاب لازم قرار نہیں دیا گیا۔ بعض کا قول ہے: وہ یمن سے نکلنے سے قبل وفات پا گئیں۔ اس کے بعد ان سے عکرمہ نے نکاح کیا، بعض کا قول ہے، مرتد ہو گئیں اور سیدنا عمر رضی اللہ عنہ نے سیدنا ابو بکر رضی اللہ عنہ کے سامنے دلیل پیش کی کہ وہ ازواج مطہرات میں ان میں سے نہیں ہیں، اور فرمایا: عکرمہ کی ان سے اولاد نہ ہوئی۔ ان کے بارے میں بہت زیادہ اختلاف ہے۔ ابن عبدالبر کا کلام ختم ہوا۔ ابو نعیم نے اسحاق بن حبیب شہیدی کے طریق سے عبدالاعلیٰ سے، انہوں نے داؤد بن ابو ہند سے، انہوں نے عکرمہ سے، انہوں نے ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے اشعث کی بہن قبیلہ سے نکاح کیا، تو اختیار دینے سے قبل وفات پا گئیں، اس موصول حدیث کی اسناد بھی قوی ہے۔(2) اسی طرح اسے عبدالوہاب ثقفی کے طریق سے بحوالہ داؤد شعمی مرسلاً نقل کیا ہے، اور اس کے الفاظ یہ ہیں۔۔۔۔ قیلہ بنت اشعث، آپ صلی اللہ علیہ وسلم کی وفات کے بعد عکرمہ نے ان سے نکاح کر لیا تو سیدنا ابو بکر رضی اللہ عنہ کو یہ بات ناگوار ہوئی، پھر سیدنا عمر رضی اللہ عنہ کی وہ بات نقل کی، جو گزر چکی ہے، اس کے آخر میں ہے، سیدنا ابو بکر رضی اللہ عنہ کو اطمینان ہوا اور خاموش ہو گئے۔(3)","",{"fn":"(1) اسد الغابۃ (۷۲۱۱) تجرید (۲۹۸/۲)\n(2) الاستيعاب (۱۹۰۴/۴)\n(3) اسد الغابۃ (۳۷۹/۵) الطبقات الکبریٰ (۱۰۵/۸، ۱۰۶)"}],[10263,"§۱۱۶۵۴ ۔ قُریبہ بنت الحارث العُتواریہ\n(1) ابن مندہ نے ان کی حدیث حفص بن عمر کے طریق سے بحوالہ بکار بن عبد العزیز، انہوں نے موسیٰ بن عبیدہ سے، وہ فرماتے ہیں کہ ہم سے یزید بن عبد الرحمن نے بحوالہ اپنی والدہ جحشہ بنت قرط، انہوں نے اپنی والدہ عقیلہ بنت عبید بن حارث، وہ فرماتے ہیں: میں اور میری والدہ قریبہ بنت حارث عتواریہ آئے، ان سے اسی طرح منقول ہے، اور صحیح قریرہ ہے، جیسا کہ حرف عین عقیلہ میں گزر چکا ہے، ابونعیم فرماتے ہیں: ابن مندہ نے قریبہ کا عنوان قائم کیا ہے، اور حدیث نقل کی جس میں فرمایا: قریرہ، اسی طرح طبرانی(2) وغیرہ نے نقل کیا ہے۔ میں کہتا ہوں: وہی صحیح ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۱۵) تجرید (۲۹۸/۲)\n(2) المعجم الکبیر (۸۵۴/۲۴)"}],[10264,"§۱۱۶۵۵ ۔ کبشہ بنت ابی امامہ\n(1) اسعد بن زرارہ، ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے، ان کے والد نے ان کے بارے نبی کریم صلی اللہ علیہ وسلم کو وصیت کی تھی تو ان سے عبد اللہ بن ابی حبیبہ نے نکاح کیا جو بنو اغر بن زید بن عطاف سے ہیں، وہ سیدنا اسعد کی صاحبزادیوں میں سب سے چھوٹی تھیں، بیعت کرنے والی صحابیات میں ان کا شمار ہے، ان کی بہن حبیبہ کے سوانح میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۲۴) تجرید (۲۹۹/۲)"}],[10265,"§۱۱۶۵۶ ۔ کبشہ بنت اوس\n(1) ابن شریق انصاریہ، بنو علمہ سے ہیں، خزیمہ بن ثابت کی والدہ ہیں، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۲۶) تجرید (۲۹۹/۲)"}],[10266,"§۱۱۶۵۷ ۔ کبشہ بنت ثابت\n(1) ابن حارثہ بن جلاس انصاریہ، بنو جدارہ سے ہیں، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ ابن سعد(2) کا قول ہے، ان کی والدہ کا نام سلامہ ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۲۷) تجرید (۳۰۰/۲)\n(2) الطبقات الکبریٰ (۲۶۶/۸)"}],[10267,"§۱۱۶۵۸ ۔ کبشہ بنت ثابت\n(1) ابن علیک بن نعمان بن عمرو بن عتیک بن عمرو بن مبذول، ان کی کنیت ام سعید ہے۔ ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، فرماتے ہیں: ان کی والدہ معاذہ بنت انس بن قیس بن عبید ہیں، ان سے یزید بن ابی الیسر، کعب بن عمرو نے نکاح کیا، جس سے سعید، عبدالرحمن اور ام کثیر پیدا ہوئے۔","",{"fn":"(1) تجرید (۲۹۹/۲)\n(2) الطبقات الکبریٰ (۲۶۶/۸)"}],[10268,"§۱۱۶۵۹ ۔ کبشہ بنت ثابت\n(1) ابن منذر بن حرام، سیدنا حسان کی باپ شریک بہن ہیں، بنو مالک بن نجار سے ہیں۔ ترمذی(2) اور ابو یعلیٰ نے یزید بن جابر کے طریق سے بحوالہ عبدالرحمن بن ابی عمرہ، انہوں نے اپنی دادی کبشہ سے ان کی حدیث روایت کی ہے، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے اور لٹکے ہوئے مشکیزے کے منہ سے پانی پیا، میں گئی اور جہاں سے نبی کریم صلی اللہ علیہ وسلم نے پانی پیا تھا اس کا منہ کاٹ لیا۔ اسی طرح ان کی حدیث میں ہے، اس میں ان کے والد اور نسب مذکور نہیں، ابوعروبہ نے ان کا نسب بیان کیا ہے، جیسا کہ میں نے ذکر کیا۔ اسے عبدالعزیز بن حسین نے بحوالہ یزید بن عبدالرحمن روایت کیا ہے، فرماتے ہیں: بحوالہ ان کی دادی بڑھیا صاحبہ کہ نبی کریم صلی اللہ علیہ وسلم نے کھڑے ہو کر پانی پیا۔ اسے ابن مندہ نے نقل کیا ہے، احتمال ہے کہ وہ ان سے ملے ہیں، اسے ابن وہب نے بحوالہ ابن لہیعہ، انہوں نے یزید سے روایت کیا ہے، فرماتے ہیں: بحوالہ ان کی دادی کبشہ، عنقریب ان کا تذکرہ آئے گا، ابن سعد(3) کا قول ہے: ان کی والدہ خطی بنت حارثہ بن لوزان ہیں، ان سے عمرو بن شخصن بن عمرو بن عتیک نے نکاح کیا، جس سے تعلیہ، ابو عمر اور حبیبہ پیدا ہوئے، اس کے بعد ان سے حارث بن ثعلبہ نے نکاح کیا، جس سے ام ثابت رملہ پیدا ہوئیں، اس کے بعد ان سے حارثہ بن نعمان نے نکاح کیا۔","",{"fn":"(1) اسد الغابۃ (۷۲۲۵) تجرید (۲۹۹/۲)\n(2) ترمذی (الحدیث: ۱۸۹۲)\n(3) الطبقات الکبریٰ (۲۳۹/۸)"}],[10269,"§۱۱۶۶۰ ۔ کبشہ بنت حاطب\n(1) ابن قیس بن ہیٹہ، بنو معاویہ سے ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۲۸) الاستيعاب (۳۵۲۶) تجرید (۲۹۹/۲)"}],[10270,"§۱۱۶۶۱ ۔ کبشہ بنت رافع\n(1) ابن عبید بن ثعلبہ بن ابجر، وہ خدرہ ہیں، انصاریہ خدریہ، سیدنا سعد بن معاذ کی والدہ ہیں، ان کی وفات تک زندہ رہیں۔ ام سعد کے لیے سعد کے کھو جانے کا افسوس، اس نے مستقل الرائے اور ہمت آج گنوادی۔ ابن اسحاق(2) نے سیدنا سعد کی وفات کے موقعہ پر یہ اشعار نقل کیے ہیں، پھر ان سب نے ذکر کیا کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: “ہر بین کرنے والی عورت جھوٹ بولتی ہے سوائے سعد کا بین کرنے والی کے”۔(3)","",{"fn":"(1) اسد الغابۃ (۷۲۳۰) الاستيعاب (۳۵۲۸) تجرید (۲۹۹/۲)\n(2) السیرۃ النبویۃ (۱۹۸/۳)\n(3) اسد الغابۃ (۲۸۵/۵)"}],[10271,"§۱۱۶۶۲ ۔ کبشہ بنت عمرو\n(1) ابن عبد بن قمیہ بن عامر بن خزرج انصاریہ، بنو ساعدہ سے ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۳۱) تجرید (۳۰۰/۲)"}],[10272,"§۱۱۶۶۳ ۔ کبشہ بنت الفاکہ\n(1) ابن قیس انصاریہ زرقیم۔ ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۳۰۰/۲)\n(2) الطبقات الکبریٰ (۲۸۵/۳)"}],[10273,"§۱۱۶۶۴ ۔ کبشہ بنت فروہ\n(1) ابن عمرو بن فروہ انصاریہ، بنو بیاضہ سے ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۳۲) تجرید (۳۰۰/۲)"}],[10274,"§۱۱۶۶۵ ۔ کبشہ بنت کعب\n(1) ابن مالک انصاریہ، عبداللہ بن ابی قتادہ کی زوجہ ہیں۔ ابن حبان کا قول ہے، انہیں شرف صحابیت حاصل ہے۔ مستغفری نے ان کی پیروی کی ہے، موطا اور سنن اربعہ میں بلی کے لعاب کے بارے میں بحوالہ ابی قتادہ ان کی حدیث مروی ہے۔ ابن سعد(2) کا قول ہے: ان سے ثابت بن ابی قتادہ نے نکاح کیا، جس سے اولاد ہوئی، ان کی والدہ صفیہ اہل یمن سے ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۲۳۳) تجرید (۳۰۰/۲)\n(2) ابوداؤد (۷۵) ترمذی (۹۲) نسائی (۶۸) (۳۳۹) ابن ماجہ (۳۶۷) مالک (۴۶) مسند احمد (۲۹۶/۵، ۳۰۳، ۳۰۹)"}],[10275,"§۱۱۶۶۶ ۔ کبشہ بنت مالک\nابن سنان، ابوسعد کی بہن ہیں، فریعہ ہیں، ان کا ذکر گزر چکا ہے۔"],[10276,"§۱۱۶۶۷ ۔ کبشہ بنت مالک\nابن قیس، کبشیہ میں ان کا ذکر آئے گا۔"],[10277,"§۱۱۶۶۸ ۔ کبشہ بنت معدیکرب\n(1) اشعث بن قیس کی پھوپھی ہیں، معاویہ بن خدیج جو معروف صحابی ہیں ان کی والدہ ہیں۔ دارقطنی(2) نے ان کا قصہ، ان کے بیٹے معاویہ کے طریق سے بیان کیا کہ انہوں نے فرمایا: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، میرے ساتھ میری والدہ کبشہ بنت معدیکرب تھیں جو اشعث کی پھوپھی ہیں، انہوں نے کہا: یا رسول اللہ! میں نے قسم کھائی ہے کہ بیت اللہ کا طواف گھٹنوں کے بل کروں گی، آپ صلی اللہ علیہ وسلم نے فرمایا: اپنے پاؤں پر ستر بار طواف کرو، سات اپنے ہاتھوں کی طرف سے اور سات اپنے پیروں کی طرف سے۔۔۔۔ اس کی سند ضعیف ہے۔ ابن دباغ وغیرہ نے استیعاب پر اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) الطبقات الکبریٰ (۳۵۱/۸)\n(2) سنن دارقطنی (۲۷۳/۲)"}],[10278,"§۱۱۶۶۹ ۔ کبشہ بنت معن\n(1) ابن عاصم انصاریہ، ابو قیس بن اسلت کی زوجہ تھیں، انہیں کبشہ کہا جاتا تھا۔ ابن جریج کا قول ہے جو انہوں نے عکرمہ سے نقل کیا ہے کہ ان کے بارے میں یہ آیت نازل ہوئی: تمہارے(2) لیے یہ حلال نہیں کہ تم زبردستی عورتوں کے وارث بن بیٹھو۔۔۔۔(3) ابوموسیٰ نے اسے مستغفری کے حوالے سے نقل کیا ہے، پھر ابو ثور کے طریق سے، انہوں نے ابن جریج سے نقل کیا ہے، میں نے اسے انساب میں کئی طرق سے ذکر کیا ہے۔(4)","",{"fn":"(1) الطبقات الکبریٰ (۳۵۱/۸)\n(2) اسد الغابۃ (۷۲۳۰۰) تجرید (۳۰۰/۲)\n(3) سورۃ النساء الآیۃ (۱۹)\n(4) تفسیر ابن کثیر (۲۱۴/۲)"}],[10279,"§۱۱۶۷۰ ۔ کبشہ بنت واقد\n(1) ابن عمرو بن عامر بن زید مناۃ اور عمرو بن اطنابہ ہیں، جو بنو حارث بن خزرج سے ہیں، ابن حبیب نے بیعت کرنے والی خواتین میں ان کا ذکر کیا ہے، وہ ام عبد اللہ بن رواحہ ہیں۔ ابن سعد(2) نے ان کا ذکر کیا ہے، ان کے بارے میں منقول ہے: کبیشہ تصغیر کے ساتھ ہے، اس میں یہ اضافہ ہے، جب رواحہ کی وفات ہوئی تو ان سے قیس بن شماس نے نکاح کیا، جس سے ثابت پیدا ہوئے۔","",{"fn":"(1) اسد الغابۃ (۷۲۳۵) تجرید (۳۰۰/۲)\n(2) الطبقات الکبریٰ (۲۶۴/۸)"}],[10280,"§۱۱۶۷۱ ۔ کُبیرہ\n(1) بعض کا قول ہے: کثیرہ، ابن مندہ نے “ث” کے ساتھ نقل کیا ہے۔ ابو نعیم نے ان کی پیروی کی ہے، ابو موسیٰ نے ذیل میں ابن ماکولا کی پیروی کرتے ہوئے باء کے ساتھ ذکر کیا ہے۔ میں کہتا ہوں: ابن ماکولا خطیب پر سبقت لے گئے، اور فرمایا: کبیرہ، جو کبیرہ بنت ابوسفیان ہیں۔ انہیں شرف صحابیات اور روایت حاصل ہے، پھر محمد بن سلیمان بن سموال کے طریق سے بحوالہ بیٹی بن ابی ورقہ بن سعید، انہوں نے اپنے والد سے روایت کی، فرماتے ہیں: مجھ سے میری مولاۃ کبیرہ بنت ابی سفیان نے روایت کی۔ انہوں نے جاہلیت کا زمانہ پایا، اور بیعت کرنے والی صحابیات میں سے ہیں، فرماتی ہیں: یا رسول اللہ! میں نے جاہلیت میں اپنے چار بیٹوں کو زندہ دفن کیا تھا، آپ صلی اللہ علیہ وسلم نے فرمایا: چار غلام آزاد کر دو۔ انہوں نے ابوسعید اور ان کے بیٹے میسرہ، ام میسرہ کو آزاد کیا، خطیب فرماتے ہیں: انہوں نے چوتھے کا ذکر نہیں کیا، شاید وہ اس حدیث کے راوی ہیں: یعنی ابو ورقہ۔ ابن اثیر(2) کا قول ہے، جس میں انہوں نے سلف کی پیروی کی ہے کہ وہ خزاعیہ ہیں، بعض کا قول ہے: ثقفیہ، بعض نے کہا: کبیرہ بنت ابی سفیان، اور مذکورہ استاد کے ساتھ ایک اور حدیث روایت کی: “خاکستری رنگ کے جانور کا خون اللہ تعالیٰ کے نزدیک سیاہ رنگ والے جانور سے زیادہ پاکیزہ ہے”۔(3)","",{"fn":"(1) اسد الغابۃ (۷۲۳۶) تجرید (۳۰۰/۲)\n(2) اسد الغابۃ (۳۸۶/۵)\n(3) المعجم الکبیر (۲۵/۹) مجمع الزوائد (۱۸/۴)"}],[10281,"§۱۱۶۷۲ ۔ کُبیشہ بنت مالک\n(1) ابن قیس انصاریہ، بنو مازن سے ہیں، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ وہ شموس ہیں۔ ابن سعد(2) نے تصغیر کے بغیر ان کا ذکر کیا ہے اور فرمایا: ان کی والدہ سہیمہ بنت عویمر بن اسعد ہیں، ان سے ثعلبہ بن شخصن بن عمرو بن عتیک بن عمرو بن مبذول نے نکاح کیا، جس سے زینب پیدا ہوئیں۔","",{"fn":"(1) اسد الغابۃ (۷۲۳۷) تجرید (۳۰۰/۲)\n(2) الطبقات الکبریٰ (۳۰۶/۸)"}],[10282,"§۱۱۶۷۳ ۔ کبشہ بنت معن\nابن عاصم، کبشہ (بغیر تصغیر) میں ان کے حالات گزر چکے ہیں۔"],[10283,"§۱۱۶۷۴ ۔ کثیرہ\nٹ کے ساتھ، بنت ابی سفیان، کبیرہ میں گزر چکی ہیں۔"],[10284,"§۱۱۶۷۵ ۔ کحیلہ\nطبرانی کی معجم کبیر میں حدیث ابوامامہ میں ان کا ذکر ہے۔"],[10285,"§۱۱۶۷۶ ۔ کریمہ بنت ابی حدرد الاسلمیہ\n(1) بعض کا قول ہے: انہیں شرف صحابیت حاصل ہے، ابن حبان اور مستغفری نے ان کا ذکر کیا ہے، بعض کا قول ہے: وہ ام درداء کبرئی ہیں، حالانکہ یہ وہ نہیں ہیں۔ ام درداء کیبرٹی کے بارے میں معروف ہے کہ ان کا نام خیرہ ہے جیسا کہ حرف خاء میں گزر چکا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۳۹) الاستيعاب (۳۵۳۰) تجرید (۳۰۰/۲)"}],[10286,"§۱۱۶۷۷ ۔ کریمہ بنت کلثوم الحمیریہ\nعکاف بن وداعہ کے سوانح میں ان کا ذکر گزر چکا ہے، بعض کا قول ہے: وہ زینب بنت کلثوم ہیں۔"],[10287,"§۱۱۶۷۸ ۔ کُعیبہ\n(1) بنت سعید اسلمیہ، ابوعمر(2) نے بحوالہ واقدی ان کا ذکر کیا ہے کہ وہ خیبر میں آپ صلی اللہ علیہ وسلم کے ساتھ حاضر تھیں، رسول اللہ صلی اللہ علیہ وسلم نے ان کے لیے ایک آدمی کے حصے کے برابر حصہ عطا فرمایا، ابن سعد(3) کا قول ہے: یہ وہی ہیں جو مسجد میں ان کا خیمہ تھا، بیماروں اور زخمیوں کو دوا دیتیں، سیدنا سعد بن معاذ رضی اللہ عنہ کو جب تیر لگا تو ان کے زخموں کا علاج کرتی تھیں، یہاں تک کہ وہ وفات پاگئے۔","",{"fn":"(1) اسد الغابۃ (۷۲۴۱) الاستيعاب (۳۵۳۱) تجرید (۳۰۰/۲)\n(2) الاستيعاب (۱۹۰۷/۴)\n(3) المغازی (۶۸۵/۲)"}],[10288,"§۱۱۶۷۹ ۔ کلبہ بنت یثربی\n(1) انہیں شرف صحابیت حاصل ہے۔ تجرید میں اسی طرح ہے، بغیر اضافے کے میرا خیال ہے کہ یہ بعد والی ہیں، پھر میں نے ابراہیم حربی کے کلام میں اس کے بارے میں تصریح پائی ہے، انہوں نے ان کے والد کا نام وہی بتایا ہے جو اوروں نے بتایا ہے۔(2)","",{"fn":"(1) الطبقات الکبریٰ (۲۱۳/۸)\n(2) تجرید (۳۰۱/۲)"}],[10289,"§۱۱۶۸۰ ۔ کُلثُم\n(1) بعض کا قول ہے: کلیہ، بنت بُرھن۔ بنو عنبر بن تمیم سے ہیں۔ زینب بن ثعلبہ کی والدہ ہیں، طبرانی(2) نے کبیر میں زینب ابن ثعلبہ کے طریق سے نقل کیا ہے، فرماتے ہیں، مجھے میری والدہ کلیبہ بنت بُرشن عنبریہ نے بلایا اور کہا: اے میرے بیٹے! اس شخص نے میری اوڑھنے والی چادر لے لی ہے۔ میں اس شخص سے جا ملا اور اسے رسول اللہ صلی اللہ علیہ وسلم کے پاس لے آیا، میں نے عرض کی: اللہ کے رسول! اس نے میری والدہ کی چادر لے لی ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: اسے وہ چادر واپس کرو۔ ابونعیم نے ان کا ذکر کیا ہے، یہ طویل حدیث سے مختصر لیا گیا ہے۔ ابونعیم کا قول ہے، بعض نے کہا: ان کا نام کلیم ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۴۲) تجرید (۳۰۱/۲)\n(2) المعجم الکبیر (۲۵/۱۱)"}],[10290,"§۱۱۶۸۱ ۔ مکثم بنت محرز النجاریہ\n(1) سیدہ اسماء کی بہن ہیں، جن کا ذکر گزر چکا ہے۔ ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۳۰۱/۲)\n(2) الطبقات الکبریٰ (۳۰۹/۸)"}],[10291,"§۱۱۶۸۲ ۔ کُلثم\nعبدالرحمن بن ابی عمرہ کی دادی ہیں، کبعہ میں ان کا ذکر گزر چکا ہے۔"],[10292,"§۱۱۶۸۳ ۔ کُنود بنت قرطہ\nفاختہ بنت قرطہ میں ان کا ذکر ہے۔"],[10293,"§۱۱۶۸۴ ۔ کُنود ام سارہ\nسارہ میں ان کا ذکر گزر چکا ہے۔"],[10294,"§۱۱۶۸۵ ۔ کُویسہ\n(1) یہ یتیمہ تھی جو نبی کریم صلی اللہ علیہ وسلم کی پرورش میں تھی۔ یہ کلیب بن عیسیٰ کا قول ہے، جو انہوں نے زُجلہ سے، انہوں نے ان سے روایت کیا ہے، تجرید میں اسی طرح مذکور ہے۔ انہوں نے اختصار میں انتہائی کمی کی ہے۔ زُجلہ، اہل شام کی ایک خاتون تھیں، انہوں نے ام درداء وغیرہ سے روایت کیا، خطیب نے مؤتلف میں ہیثم بن خارجہ کے طریق سے، انہوں نے کلیب بن عیسیٰ بن ابی حجر ثقفی سے روایت کیا، فرماتے ہیں: میں نے زُجلہ سے، جو معاویہ کی مولاۃ ہیں، فرماتے ہوئے سنا: میں نے ان یتیموں کا زمانہ پایا، جو نبی کریم صلی اللہ علیہ وسلم کی پرورش میں تھیں، ان میں سے ایک کا نام کویسہ تھا، انہوں نے یہ قصہ بیان کیا کہ عورتیں جنازہ کے پیچھے نہیں جاتی تھیں ہاں اگر کوئی عورت ماہواری یا حمل سے ہوتی تو وہ عید گاہ نہ جاتی جبکہ بقیہ خواتین عید گاہ جاتی تھیں۔ جب جنازہ رکھ دیا جاتا وہ عورت اپنا ہاتھ میت کے پیٹ پر رکھتی کہ آیا اس سے کوئی چیز تو نہیں نکلی، مرد اسے دیکھ رہے ہوتے، یہاں تک کہ جب وہ چھپ جاتی تو لوگ امام سے کہتے تکبیر کہے۔","",{"fn":"(1) الاستيعاب (۳۵۲۷) تجرید (۳۰۱/۲)"}],[10295,"§۱۱۶۸۶ ۔ کیسہ\nبنت حارث بن کریز بن عبد شمس، مسیلمہ کذاب کی زوجہ تھیں، اس کے بعد عبد اللہ بن عامر اکبر کے نکاح میں آئیں۔ زبیر بن بکار نے ان کا ذکر کیا ہے، اور ان کا نام قلمبند کیا ہے۔"],[10296,"§۱۱۶۸۷ ۔ کُبشہ بنت حکیم الثقفیہ\n(1) ام حکم بنت یحییٰ بن عقبہ کی دادی ہیں، ام حکیم نے ان سے روایت کیا کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کو دیکھا، ابن مندہ نے اسی طرح ذکر کیا ہے۔ اور ابونعیم نے اسے ذکر کیا ہے، فرمایا: اس پر اضافہ نہیں کیا، یعنی ان کی حدیث نقل نہیں کی۔","",{"fn":"(1) اسد الغابۃ (۷۲۲۹) تجرید (۲۹۹/۲)"}],[10297,"§۱۱۶۸۸ ۔ کبشہ بنت مکشوح المرادیہ\nقیس کی بہن ہیں جو مشہور شہسوار ہیں، ابن شاہین نے ابان بن سعید بن العاص کے سوانح میں ان کا ذکر کیا ہے، وہ صاحب جمال خاتون تھیں، ان کے بھائی قیس بن ابان نے ان کا نکاح کر دیا، سیدنا ابو بکر صدیق رضی اللہ عنہ کی خلافت میں جب وہ یمن کے والی مقرر ہوئے تھے۔ ایک طویل حدیث میں یہ سلیمان انباری کے طریق سے بحوالہ نعمان بن بزرج منقول ہے۔"],[10298,"§۱۱۶۸۹ ۔ کبشہ بنت بُرتن\n(1) بعض کا قول ہے: بیر بی عنبریہ۔ ابوعمر نے حدیث زینب بنت ثعلبہ میں ان کا تذکرہ کیا ہے۔ اسی طرح تجرید میں ہے اور وہ غلطی ہے۔ یہ کلیہ تصغیر کے ساتھ ہے، جیسا کہ قریب ہی کلثم میں گزر چکا ہے۔","",{"fn":"(1) تجرید (۲۹۹/۳)"}],[10299,"§۱۱۶۹۰ ۔ لُبابہ بنت اسلم\n(1) ابن حریش بن عدی بن مجدعہ بن حارثہ۔ ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، اور فرمایا: سیدنا سلمہ بن اشیاء کی سگی بہن ہیں۔ ان سے زید بن سعد بن زید اشہلی نے نکاح کیا۔","",{"fn":"(1) تجرید (۳۰۱/۲)\n(2) الطبقات الکبریٰ (۲۴۴/۸)"}],[10300,"§۱۱۶۹۱ ۔ لُبابہ بنت الحارث\n(1) ابن حزن بن بخیر بن ہرم بن رویبہ بن عبد اللہ بن ہلال بن عامر بن صعصعہ بلالیہ، ام الفضل سیدنا عباس بن عبدالمطلب کی زوجہ اور ان کی اولاد، فضل، عبد اللہ وغیرہ کی والدہ ہیں۔ یہ لبابہ کبریٰ ہیں جو اپنی کنیت سے مشہور اور اپنے نام سے پہچانی جاتی ہیں۔ کنیتوں میں ان کا ذکر آئے گا۔ ان کی والدہ خولہ بنت عوف قرشیہ ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۲۴۴) الاستيعاب (۳۵۳۲) تجرید (۳۰۱/۲)"}],[10301,"§۱۱۶۹۲ ۔ لُبابہ بنت الحارث ابن حزن ہلالیہ\n(1) ابن حزن ہلالیہ، اس سے پہلی صحابیہ کی بہن ہیں، یہ لبابہ صغریٰ ہیں، ان کا لقب عصماء تھا، ان کی والدہ فاختہ بنت عامر ثقفیہ ہیں اور یہ خالد بن ولید کی، جو مشہور صحابی ہیں، والدہ ہیں۔ ابو عمر(2) کا قول ہے: ان کے اسلام لانے اور صحابیہ ہونے میں تردد ہے۔ ابن اثیر(3) نے اسی کو برقرار رکھا ہے۔ یہ عجیب بات ہے، گویا انہوں نے ان کے شوہر ولید کی پہلے وفات کی جہت سے اسے بعید سمجھا ہے، کہ وہ ان کے ساتھ یہ تھوڑا عرصہ بعد وفات پاگئیں ہوں، یہ ضروری نہیں، کیونکہ ثابت ہو چکا ہے کہ وہ اپنے بیٹے خالد کی وفات کے بعد بھی زندہ رہیں۔ ان کا اس بارے میں قصہ ہے۔ ابو حذیفہ نے مبتدا والفتوح میں بحوالہ محمد بن اسحاق ذکر کیا ہے، فرماتے ہیں: جب سیدنا خالد بن ولید رضی اللہ عنہ کی وفات ہوئی تو سیدنا عمر رضی اللہ عنہ ان کے جنازے کے لیے نکلے تو ان کی والدہ یہ اشعار پڑھ رہی تھیں: “تم قوم کے لاکھوں میں سے بہتر ہو، جب تم لوگوں کے چہروں کے سامنے تھے۔” فرماتے ہیں، سیدنا عمر رضی اللہ عنہ نے فرمایا: تم نے سچ کہا، ایسا ہی تھا۔ سیف بن عمر نے ارتداد اور فتوح کے زمانے کے بارے میں اپنی سند سے فرمایا اور سیدنا خالد رضی اللہ عنہ کے الگ ہو جانے اور مدینہ میں مقیم ہونے کے بارے میں ذکر کیا ہے، فرماتے ہیں: جب سیدنا عمر رضی اللہ عنہ نے دیکھا کہ لوگوں کے فتنے میں پڑنے کا خدشہ ختم ہو گیا ہے تو انہوں نے ارادہ کیا کہ حج سے واپسی پر وہ انہیں عہدہ پر بحال کر دیں، ان کے ساتھ سیدنا خالد بن ولید رضی اللہ عنہ نکلے، انہوں نے مدینہ سے باہر پانی مانگا، تو فرمایا: میرے ہجرت کے مقام تک مجھے نیچے اتار دو۔ تو ان کی والدہ انہیں مدینہ لے آئیں۔ وہاں ان کی تیمار داری کی۔ سیدنا عمر رضی اللہ عنہ نے حج سے آنے والے ایک آدمی سے پوچھا: کیا خبر ہے؟ اس نے کہا: خالد کی حالت تشویشناک ہے۔ سیدنا عمر رضی اللہ عنہ نے تین راتوں کا سفر ایک رات میں طے کیا۔ ان کی وفات کے بعد سیدنا عمر رضی اللہ عنہ پہنچے، ان پر رقت طاری ہوگئی، إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ پڑھا۔ جب ان کی تجہیز ہوئی تو عورتیں رونے لگیں، آپ سے کہا گیا: کیا آپ انہیں نہیں روکتے؟ انہوں نے فرمایا: ابوسلیمان پر آنسو بہانے میں کوئی حرج نہیں جب تک مار دھاڑ اور آواز بلند نہ ہو۔ جب آپ کا جنازہ اٹھایا گیا تو ایک عورت احرام باندھے رو رہی تھی اور کہہ رہی تھی: تو لاکھوں میں بہتر ہے۔۔۔۔ جو شعر پہلے گزر چکا ہے، اس کے بعد ہے: “کیا بہادری؟ تو لیث مرۃ بن جہم ابی اشبال سے زیادہ بہادر تھا۔ کیا سخاوت؟ تو پہاڑوں کے درمیان جانے والے سیلاب سے زیادہ سخی تھا۔” تو سیدنا عمر رضی اللہ عنہ نے پوچھا: یہ کون ہے؟ کہا گیا: ان کی والدہ۔ آپ نے کہا: ان کی والدہ، اللہ کی قسم! تین مرتبہ فرمایا، تو کیا عورتوں سیدنا خالد جیسے شخص کی میت سے اٹھی تھیں۔ یہ اگر ابو حذیفہ کی روایت ہے تو وہ ضعیف ہے، اسی طرح سیف بھی ضعیف ہے، لیکن ابن سعد(4) نے ذکر کیا ہے، وہ ثقہ ہے، بحوالہ کثیر بن ہشام، انہوں نے جعفر بن بُرقان سے، انہوں نے یزید بن اصم سے، فرماتے ہیں: جب خالد بن ولید رضی اللہ عنہ وفات پاگئے تو ان کی والدہ ان پر روئیں، تو سیدنا عمر رضی اللہ عنہ نے فرمایا: اے ام خالد! کیا خالد یا اس کے اجر کی مصیبت پر آنسو بہاتی ہو؟ تمہیں ثابت قدم رہنا ہوگا یہاں تک کہ تم مہندی سے اپنا ہاتھ رنگ لو۔ یہ سند صحیح ہے۔ بخاری وغیرہ نے سیدنا عمر رضی اللہ عنہ کے قول کو تعلیقاً ذکر کیا ہے جس میں سیدنا خالد پر بلند آواز سے آنسو بہانے کا ذکر ہے۔ لیکن ان کی والدہ کا نام نہیں لیا۔ ان روایات سے معلوم ہوا کہ وہ نبی کریم صلی اللہ علیہ وسلم کے بعد بھی زندہ رہیں، کیا اس سے یہ گمان کیا جا سکتا ہے کہ وہ فتح کے بعد نبی کریم صلی اللہ علیہ وسلم کی وفات تک حالت کفر میں رہیں، یہ بعید ہے اور یہ قول اسے باطل کر دے گا کہ حرمین اور طائف میں حجۃ الوداع کے موقع پر سب لوگ اسلام لا چکے تھے اور حاضر تھے۔","",{"fn":"(1) اسد الغابۃ (۷۲۴۵) الاستيعاب (۳۵۳۳) تجرید (۳۰۱/۲)\n(2) الاستيعاب (۱۹۰۹/۴)\n(3) اسد الغابۃ (۳۹۰/۵)\n(4) الطبقات الکبریٰ (۲۴۶/۸)"}],[10302,"§۱۱۶۹۳ ۔ لبابہ بنت ابی لبابہ الانصاریہ\n(1)انہوں نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا، ان کا ذکر موجود ہے۔ ابن مندہ نے مختصراً ان کا ذکر کیا ہے، ابو نعیم نے موسیٰ بن عبیدہ ربذی کے طریق سے جو ایک ضعیف راوی ہیں، بحوالہ سعید بن جبیر جو مولی ابولبابہ ہیں، اور یعقوب بن زید سے، انہوں نے لبابہ سے روایت کی، فرماتی ہیں: میں ان کے ساتھ تھی، وہ فرماتے تھے: اس اللہ کے دشمن کی مشکیں کس دو! جس نے اللہ اور اس کے رسول صلی اللہ علیہ وسلم سے خیانت کی ہے۔ ان کے پاس سے ان کے بھائی گزرے اور کہا: اے میرے بھائی! میرے پاس آؤ۔ انہوں نے کہا: نہیں، اللہ کی قسم! میں تم سے بات نہیں کروں گا یہاں تک کہ تم سے اللہ اور اس کا رسول صلی اللہ علیہ وسلم راضی ہو؟ ان کے بارے میں رسول اللہ صلی اللہ علیہ وسلم نے پوچھا، انہوں نے کہا: وہ مسجد میں ہیں۔ لوگوں نے ان کے بارے میں آپ صلی اللہ علیہ وسلم کو بتایا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر وہ میرے پاس آتا تو میرے لیے اس کے بارے میں کوئی واقعہ ہوتا۔\"(2) پھر یہ آیت نازل ہوئی: اے مومنو! تم اللہ اور رسول (صلی اللہ علیہ وسلم) سے خیانت نہ کرو، اور اپنی امانتوں میں خیانت نہ کرو۔۔۔۔(3) اور دوسری آیت اور دوسرے جنہیں اللہ کے حکم کی امید ہے۔۔۔۔(4)","",{"fn":"(1) اسد الغابہ (۷۲۴۶) تجرید (۳۰۱/۲)\n(2) السیرۃ النبویۃ (۱۸۷/۳) دلائل النبوۃ (۱۶/۴)\n(3) سورۃ الانفال الآیۃ (۲۷)\n(4) سورۃ التوبۃ الآیۃ (۱۰۶)"}],[10303,"§۱۱۶۹۴ ۔ لبنی بنت ثابت\n(1)ابن منذر بن حزام انصاریہ خزرجیہ، سیدنا حسان رضی اللہ عنہ جو مشہور شاعر ہیں ان کی بہن ہیں، ابن سعد نے ذکر کیا ہے کہ انہوں نے اور ان کی بہن کبشہ نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کی، لبنی اوس بن ثابت کی سگی بہن تھیں۔","",{"fn":"(1) تجرید (۳۰۱/۲)"}],[10304,"§۱۱۶۹۵ ۔ لبنی بنت الخطیم الانصاریہ\n(1)اوسیہ، قیس بن خطیم کی جو شاعر ہیں، بہن ہیں، عبد قیس بن زید بن عامر ظفری کے نکاح میں تھیں، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، اور ابن سعد(2) کا قول ہے، ان کی والدہ ام قیس، قریبہ بنت قیس بن قدیم بن امیہ بن سنان، سلمیہ ہیں۔ ان سے عبداللہ بن نہیک بن اساف نے نکاح کیا، جس سے اولاد ہوئی، لبنی اسلام لائیں اور بیعت کی، ان کی بہن لیلیٰ کا ذکر عنقریب آئے گا۔","",{"fn":"(1) اسد الغابہ (۷۲۴۷) تجرید (۳۰۱/۲)\n(2) الطبقات الکبریٰ (۱۰۰/۸)"}],[10305,"§۱۱۶۹۶ ۔ لبنی بنت قیطی\n(1)ابن قیس بن لوذان بن ثعلبہ بن عدی بن مجدعہ بن حارثہ انصاریہ۔ ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۳۰۲/۲)\n(2) الطبقات الکبریٰ (۲۴۵/۸)"}],[10306,"§۱۱۶۹۷ ۔ لبینہ\nبنو مؤمل بن حبیب بن تمیم بن عبد اللہ بن قرط بن رزاح بن عدی بن کعب کی باندی ہیں، یہ ان کمزور لوگوں میں سے تھیں جنہیں عذاب دیا جاتا تھا، اور ان سات لوگوں میں سے ہیں جنہیں سیدنا ابو بکر رضی اللہ عنہ نے خریدا، ام عمیس میں ان کا ذکر آئے گا۔ اکثر روایات میں ان کا نام مذکور نہیں۔ بلاذری رحمہ اللہ نے بحوالہ ابوالبختری ان کا نام لیا ہے۔"],[10307,"§۱۱۶۹۸ ۔ لبیس بنت عمرو\n(1)ابن حرام انصاریہ۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے اور فرمایا: ان کی والدہ قراد بنت موہبہ بن عدی بن مجدعہ بن حازم ہیں، ان سے ابو ثابت بن عبد بن عبد عمرو بن قبطی نے نکاح کیا پھر قیس بن قیس بن لوذان کے نکاح میں آئیں۔","",{"fn":"(1) اسد الغابہ (۲۵۸/۶) تجرید (۳۰۱/۲)"}],[10308,"§۱۱۶۹۹ ۔ لبیسہ بنت عمرو الانصاریہ\n(1)ام عمارہ ہیں۔ طبرانی(2) نے حرف لام میں ان کا ذکر کیا ہے، اور ابن نقطہ نے اسی پر اعتماد کیا ہے، مشہور ہے کہ نون کے ساتھ ہے، اپنی کنیت سے مشہور ہیں، عنقریب ان کا ذکر آئے گا، بعض کا قول ہے: وہ لبیسہ ہیں، جو نسیبہ کے علاوہ ہیں وہ تو بنت حرب ہیں۔ واللہ اعلم!","",{"fn":"(1) اسد الغابہ (۷۲۴۸) (۲۵۸/۶) تجرید (۳۰۲/۲)\n(2) المعجم الکبیر (۳۰/۲۵)"}],[10309,"§۱۱۷۰۰ ۔ لہیمہ\n(1)سیدنا عمر بن خطاب رضی اللہ عنہ کی باندی اور ام ولد ہیں، اور ان کی صاحبزادی سیدہ حفصہ رضی اللہ عنہا کی خدمت کیا کرتی تھیں۔ ابن ماکولا(2) کا قول ہے: ام عبد الرحمن بن عمر ہیں، ان کی کنیت ابو شحمہ ہے، بعض کا قول ہے: ان کا نام نہیمہ ہے، مستغفری نے ان کا ذکر کیا اور فرمایا: انہیں شرف صحابیت حاصل ہے، ابراہیم بن موسیٰ بن تیم کی روایت سے منقول ہے، فرمایا: مجھ سے میرے چچا زکریا بن یحییٰ نے روایت کی، فرمایا: مجھ سے میرے بھتیجے ابن شہاب نے بحوالہ اپنے چچا روایت کی، فرماتے ہیں: مجھ سے اہل علم میں سے کچھ لوگوں نے روایت کی کہ سیدہ حفصہ رضی اللہ عنہا جو نبی کریم صلی اللہ علیہ وسلم کی زوجہ ہیں، لہیمہ ام ولد سیدنا عمر رضی اللہ عنہ کو اس دن، جبکہ رسول اللہ صلی اللہ علیہ وسلم ان کے پاس تشریف لائے، بھیجا اور کہا: آپ صلی اللہ علیہ وسلم میرے پاس سے تشریف لے گئے ہیں، اور کافی دیر ہو گئی ہے نہیں آئے۔ دیکھو وہ اپنی کس زوجہ کے پاس ہیں؟ سیدہ لہیمہ گئیں، اور آپ صلی اللہ علیہ وسلم کو سیدہ صفیہ رضی اللہ عنہا کے ہاں پایا، انہوں نے آ کر سیدہ حفصہ رضی اللہ عنہا کو بتایا، سیدہ حفصہ رضی اللہ عنہا کہنے لگیں: یہودیہ کے پاس بیٹھے ہیں۔ پھر لہیمہ کو حکم دیا کہ وہ سیدہ صفیہ رضی اللہ عنہا کے پاس جائیں، یہاں تک کہ نبی کریم صلی اللہ علیہ وسلم ان کے پاس سے تشریف لے جائیں، اور انہیں (صفیہ رضی اللہ عنہا) کو بتاؤ جو کچھ حفصہ نے کہا ہے، تو سیدہ صفیہ رضی اللہ عنہا نے فرمایا: اللہ کی قسم! میں حضرت ہارون رضی اللہ عنہ کی بیٹی ہوں اور میرے چچا حضرت موسیٰ علیہ السلام ہیں، اور میرے شوہر رسول اللہ صلی اللہ علیہ وسلم ہیں اور کوئی مجھ سے افضل نہیں، آپ صلی اللہ علیہ وسلم ان کے پاس تشریف لائے تو وہ رو رہی تھیں۔ آپ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"تمہیں کیا ہوا؟\" انہوں نے آپ صلی اللہ علیہ وسلم کو بتایا جو انہیں لہیمہ نے حفصہ کے حوالے سے بتایا تھا، اور جو کچھ انہوں نے ان سے کہا، رسول اللہ صلی اللہ علیہ وسلم نے ان کی تصدیق کی۔ جب سیدہ حفصہ رضی اللہ عنہا نے یہ دیکھا تو فرمانے لگیں: اللہ کی قسم! میں سیدہ صفیہ رضی اللہ عنہا کو کبھی ایذاء نہیں دوں گی۔(3)","",{"fn":"(1) اسد الغابہ (۷۲۵۰) تجرید (۳۰۲/۲)\n(2) الاکمال (۸۳/۱)\n(3) جامع المسانید والسنن (۸۴/۱۶)"}],[10310,"§۱۱۷۰۱ ۔ لیلی بنت الاطنابہ\n(1)ابن منصور بن متی، انصاریہ، بنو شیلی سے ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا نام لیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۵۱) تجرید (۳۰۲/۲)"}],[10311,"§۱۱۷۰۲ ۔ لیلی بنت بلال\n(1)یا نبیل انصاریہ ابو لیلی کی بہن ہیں، اور عبدالرحمن بن ابو لیلی کی پھوپھی ہیں۔ ابو عمر(2) کا قول ہے: انہوں نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کی اور آپ صلی اللہ علیہ وسلم سے روایت کی۔","",{"fn":"(1) تجرید (۳۰۳/۲)\n(2) الاستيعاب (۱۸۱۰/۴)"}],[10312,"§۱۱۷۰۳ ۔ لیلی بنت ثابت\n(1)ابن منذر بن عمرو بن حرام، سیدنا حسان رضی اللہ عنہ کی بہن ہیں۔ ابن حبیب نے ان کا بھی ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۵۲) تجرید (۳۰۲/۲)"}],[10313,"§۱۱۷۰۴ ۔ لیلی بنت ابی حثمہ\n(1)ابن حذیفہ بن غانم بن عامر بن عبداللہ بن عبید بن عویج بن کعب بن لوی قرشیہ عدویہ، سیدنا سلیمان رضی اللہ عنہ کی بہن اور عامر بن ربیعہ عنبری کی زوجہ ہیں ان سے عبداللہ پیدا ہوئے، ابن سعد کا قول ہے: اسلام کے ابتدائی دور میں اسلام لائیں اور بیعت کی، اولین مہاجرات میں سے ہیں۔ حبشہ کی طرف دو ہجرتیں کیں، پھر مدینہ کی طرف ہجرت کی، بعض کا قول ہے: یہ پہلی مسافر خاتون ہیں جو ہجرت کر کے مدینہ آئیں، بعض نے کہا: ام سلمہ ہیں۔ ابن اسحاق نے یونس بن بکیر وغیرہ کی روایت سے جو ان سے مروی ہے، انہوں نے عبدالرحمن بن حارث سے، انہوں نے عبد العزیز بن عبد اللہ بن عامر بن ربیعہ سے، انہوں نے اپنی والدہ سے روایت کی، فرماتی ہیں: سیدنا عمر بن خطاب رضی اللہ عنہ ہمارے اسلام لانے کے بارے میں لوگوں میں سب سے زیادہ سخت تھے، جب ہم نے حبشہ کی سرزمین کی طرف نکلنے کا ارادہ کیا تو سیدنا عمر رضی اللہ عنہ ہمارے پاس آئے اور میں اپنے اونٹ پر تھی۔ انہوں نے پوچھا: اے ام عبداللہ! کہاں کا ارادہ ہے؟ میں نے کہا: تم لوگ ہمارے دین کی وجہ سے ہمیں ایذاء دیتے ہو، ہم اللہ کی زمین میں جائیں گے، انہوں نے کہا: اللہ تمہارا ساتھی ہو، پھر وہ چلے گئے، تو میرے پاس میرے شوہر عامر بن ربیعہ آئے، میں نے جب انہیں ان لوگوں کی بات بتائی تو وہ مجھے کہنے لگے: کیا تمہیں ان کے مسلمان ہونے کی امید ہے، پھر انہوں نے قصہ ذکر کیا۔(2) لیث بن سعد نے بحوالہ محمد بن عجلان روایت کیا ہے کہ عبداللہ بن عامر کے موالی میں سے ایک آدمی نے بحوالہ عبداللہ بن عامر روایت کیا، فرماتے ہیں: میری والدہ نے ایک دن مجھے بلایا اور رسول اللہ صلی اللہ علیہ وسلم ہمارے گھر میں تشریف فرما تھے، انہوں نے مجھ سے کہا: ادھر آؤ، میں تمہیں چیز دوں؟ ان سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم نے کیا چیز دینے کا ارادہ کیا تھا؟ انہوں نے کہا: میں نے اسے کھجور دی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر تم اسے کچھ نہ دیتی تو تمہارے نامہ اعمال میں ایک جھوٹ لکھا جاتا\"۔(3) اسے سراج نے بحوالہ بقیہ ان سے روایت کیا ہے اور لیث نے حیوۃ بن شریح اور یحییٰ بن ایوب، حاتم بن اسماعیل کی پیروی کی ہے اور بحوالہ یحییٰ بن ایوب جو مولی زیاد ہیں، اور وہ روایت ابن مندہ کے ہاں ان کے طریق سے مروی ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۵۳) الاستيعاب (۳۵۳۴) تجرید (۳۰۲/۲)\n(2) المعجم الکبیر (۴۷/۲۵) مجمع الزوائد (۲۴/۶) السیرۃ النبویۃ (۲۷۰/۱، ۲۷۱)\n(3) ابوداؤد (۴۴۹۱) مسند احمد (۴۴۷/۳) السنن الکبریٰ (۱۹۸/۱۰)"}],[10314,"§۱۱۷۰۵ ۔ لیلی بنت حکیم\n(1)انصاریہ اوسیہ۔ ابو عمر(2) کا قول ہے: ابو احمد بن صالح مصری نے ازواج النبی صلی اللہ علیہ وسلم میں ان کا ذکر کیا ہے۔ ان کے علاوہ اور کسی نے ان کا ذکر نہیں کیا۔ ابن اثیر(3) نے اسے جائز کہا ہے کہ یہ بعد والی ہوں، کیونکہ حکیم خطیم سے مشابہ ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۵۴) الاستيعاب (۳۵۳۵) تجرید (۳۰۲/۲)\n(2) الاستيعاب (۱۹۰۹/۴)\n(3) اسد الغابہ (۳۹۲/۵)"}],[10315,"§۱۱۷۰۶ ۔ لیلی بنت الخطیم\n(1)ابن عدی بن عمرو بن سواد بن ظفر انصاریہ اوسی، پھر ظفریہ ابو علی الجیانی نے استیعاب پر اپنے استدراک میں ان کا ذکر کیا ہے اور فرمایا: ابن ابی خیثمہ نے ان کا ذکر کیا ہے اور فرمایا: وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں اور کہا: میں لیلی بنت خطیم ہوں، میں آپ پر اپنا نفس پیش کرنے آئی ہوں، مجھ سے نکاح کر لیجئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے ایسا کیا\"۔(2) پھر میں اپنی قوم کے پاس واپس گئی، وہ کہنے لگے: تم نے برا کیا، تو غیرت مند خاتون ہے جبکہ وہ صاحب ازواج ہیں۔ جاؤ ان سے خلع لے لو۔ وہ واپس آ کر کہنے لگی: میں اپنا معاملہ ختم کرنا چاہتی ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے کر دیا\"۔ میں نے کہا: ابن سعد(3) نے بحوالہ ابن عباس رضی اللہ عنہما ایک سند سے جس میں کلبی بھی ہیں، یہ ذکر کیا ہے۔ انہوں نے ان سے زیادہ روایت کیا ہے، اس کے شروع میں ہے: لیلی بنت خطیم نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں اور آپ صلی اللہ علیہ وسلم سورج کی طرف اپنی کمر کئے ہوئے تھے۔ انہوں نے آپ صلی اللہ علیہ وسلم کے کندھے پر مارا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ کون ہے؟ شیر کا لقمہ\" آپ اکثر یہ جملہ فرمایا کرتے تھے۔ اس کے آخر میں ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: میں نے معاملہ ختم کیا۔ فرماتے ہیں: ان سے مسعود بن اوس بن سواد بن ظفر نے نکاح کیا، اس سے اولاد ہوئی، بیان کیا گیا ہے کہ وہ مدینہ کے ایک باغ میں غسل کر رہی تھیں، ان پر اچانک ایک بھیڑیے نے حملہ کر دیا کافی زخمی ہو گئیں، کوئی پہنچ گیا لیکن وفات پا گئیں۔ پھر واقدی سے بحوالہ محمد بن صالح بن دینار، انہوں نے عاصم بن عمر بن قتادہ سے مسنداً نقل کیا ہے، فرماتے ہیں: لیلی بنت خطیم نے اپنے نفس کو نبی کریم صلی اللہ علیہ وسلم کے لیے ہبہ کر دیا تھا، آپ صلی اللہ علیہ وسلم نے انہیں قبول کر لیا۔ اپنے خاوندوں پر بڑے برے طریقے سے سوار ہوتی تھی بھی بد اخلاق، پھر اسی قصے کا مفہوم ذکر کیا، البتہ اس کے آخر میں اس کا تذکرہ نہیں کیا۔ انہوں نے اپنی روایت میں فرمایا کہ یہ کہنے لگیں: آپ اللہ کے نبی ہیں، اللہ نے آپ کے لیے (زیادہ) عورتیں حلال کی ہیں، میں زبان دراز عورت ہوں، سوکنوں کے بارے میں صبر نہیں کر سکتی اور آپ سے ہبہ واپس لے لیا۔ ابن ابی عون کے طریق سے ہے کہ لیلی نے اپنے نفس کو نبی کریم صلی اللہ علیہ وسلم کے لیے ہبہ کر دیا اور کئی عورتوں نے اپنے نفس نبی کریم صلی اللہ علیہ وسلم کے لیے ہبہ کر دیئے، یہ نہیں سنا گیا کہ نبی کریم صلی اللہ علیہ وسلم نے ان میں سے کسی کو قبول کیا ہو، فرماتے ہیں: ان کی والدہ اونچی حویلی والی بنت پیشہ بن حارث ہیں۔ ابن سعد رحمہ اللہ نے بحوالہ واقدی رحمہ اللہ اور میرا خیال ہے بحوالہ عاصم بن عمر بن قتادہ روایت کیا ہے، فرماتے ہیں: سب سے پہلے نبی کریم صلی اللہ علیہ وسلم سے بیعت کرنے والی ام سعد بن معاذ ہیں۔ وہ کبشہ بنت ابی رافع بن عبید، بنو ظفر سے لیلی بنت خطیم، بنو عمرو بن عوف سے لیلی، مریم اور سہیمہ جو ابو سفیان رضی اللہ عنہ کی بیٹیاں ہیں، انہیں ابوالبنات کہا جاتا تھا۔۔۔۔ (الحدیث) ابن سعد نے بھی روایت کیا ہے کہ مسعود بن اوس نے جاہلیت میں ان سے نکاح کیا، جس سے عمرہ اور عمیرہ پیدا ہوئے۔ انہیں شیر کا لقمہ کہا جاتا تھا، وہ پہلی خاتون تھیں، جنہوں نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کی، ان کے ساتھ ان کی دونوں بیٹیاں، ان کی دو نواسیاں بھی تھیں، انہوں نے نبی کریم صلی اللہ علیہ وسلم کے لیے اپنے نفس کو ہبہ کر دیا، پھر بنو ظفر نے کہا: یہ ہبہ واپس کر دیں تو آپ نے یہ ہبہ واپس کر دیا۔","",{"fn":"(1) اسد الغابہ (۷۲۵۵) تجرید (۳۰۲/۲)\n(2) جامع المسانید والسنن (۸۷/۱۶)\n(3) الطبقات الکبریٰ (۱۰۸، ۱۰۷/۸)"}],[10316,"§۱۱۷۰۷ ۔ لیلی بنت رافع\n(1)ابن عمرو انصاریہ، ابو عبس بن حرب کی والدہ ہیں۔ ابن سعد نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، فرماتے ہیں: ان کی والدہ ام البراء بنت سلمہ بن غزفطہ ہیں۔","",{"fn":"(1) تجرید (۳۰۲/۲)"}],[10317,"§۱۱۷۰۸ ۔ لیلی بنت ربعی\n(1)ابن عامر بن خالدہ انصاریہ، بنو بیاضہ سے ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۵۶) تجرید (۳۰۲/۲)"}],[10318,"§۱۱۷۰۹ ۔ لیلی بنت رئاب\n(1)ابن حنیف انصاریہ، بنو عوف بن خزرج سے ہیں۔ ابن حبیب نے بھی ان کا ذکر کیا ہے۔ عتبان بن مالک کی زوجہ ہیں۔","",{"fn":"(1) اسد الغابہ (۷۲۵۷) تجرید (۳۰۲/۲)"}],[10319,"§۱۱۷۱۰ ۔ لیلی بنت ابی سفیان\n(1)ابن حارث بن قیس بن زید بن امیہ، انصاریہ، اشہلیہ، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، لیلی بنت خطیم کے سوانح میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۵۹) تجرید (۳۰۲/۲)"}],[10320,"§۱۱۷۱۱ ۔ لیلی بنت سماک\nابن ثابت بن سفیان بن عدی بن عمرو بن امرئی القیس بن مالک آغر۔ ابن سعد نے بحوالہ واقدی روایت کیا ہے کہ وہ فرماتے ہیں: اسلام لائیں اور بیعت کی، فرماتے ہیں: ان کے علاوہ کسی اور نے ان کا ذکر نہیں کیا۔ میں کہتا ہوں: ام ثابت بنت قیس بن شماس کے سوانح میں آئے گا جو قیس کی بہن ہیں کہ ثابت بن سفیان سے ان کا بیٹا سماک پیدا ہوا، اس وجہ سے لیلی، ان کے والد سماک اور والدہ ام ثابت تینوں ترتیب وار صحابی تھے۔"],[10321,"§۱۱۷۱۲ ۔ لیلی بنت سماک\n(1)ابن ثابت بن سنان بن جشم بن عمرو بن امرئی القیس انصاریہ بن حارث بن خزرج سے ہیں، ابن حبیب نے بھی ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۶۰) تجرید (۳۰۲/۲)"}],[10322,"§۱۱۷۱۳ ۔ لیلی بنت طباۃ\n(1)ابن معیص انصاریہ۔ ابن سعد نے ان کا ذکر کیا ہے، تجرید میں اسی طرح ہے، فرماتے ہیں: ہوسکتا ہے یہ لیلی بنت اطنابہ پہلے والی ہوں جن کا نام لیلی ہے۔","",{"fn":"(1) تجرید (۳۰۲/۲)"}],[10323,"§۱۱۷۱۴ ۔ لیلی بنت عبادہ الانصاریہ\n(1)ساعدیہ، عبادہ بن عبادہ کی بہن ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۶۲) تجرید (۳۰۳/۲)"}],[10324,"§۱۱۷۱۵ ۔ لیلی بنت عبداللہ العدویہ\n(1)وہ شفاء ہیں، جن کا ذکر گزر چکا ہے۔ مستغفری نے بحوالہ ابن حبان ان کا نام لیا ہے۔","",{"fn":"(1) نسب قریش (۳۶۳) جمہرۃ انساب العرب (۱۵۰) اسد الغابہ (۳۹۳/۵)"}],[10325,"§۱۱۷۱۶ ۔ لیلی بنت عطارد\nابن حاجب تمیمیہ۔ عبداللہ بن ابی ربیعہ کی، جو صحابی ہیں، والدہ ہیں اور عبد الرحمن کی والدہ ہیں۔ زبیر بن بکار نے ان کا ذکر کیا ہے۔"],[10326,"§۱۱۷۱۷ ۔ لیلی بنت قائف الثقفیہ\n(1)امام احمد رحمہ اللہ(2) اور ابوداؤد نے محمد بن اسحاق کے طریق سے بحوالہ نوح بن حکیم ثقفی ان کی حدیث نقل کی ہے، انہوں نے عروہ بن مسعود کی اولاد میں سے ایک آدمی سے جسے داؤد کہا جاتا ہے روایت کی، ام حبیبہ بنت ابی سفیان کے بیٹے تھے، انہوں نے لیلی بنت قائف سے روایت کی، انہوں نے ذکر کیا کہ وہ فرماتی ہیں: میں ام کلثوم بنت نبی کریم صلی اللہ علیہ وسلم کے غسل دینے والی عورتوں میں تھی۔ سب سے پہلے آپ صلی اللہ علیہ وسلم نے مجھے ان کے کفن میں سے ازار پھر قمیص، پھر اوڑھنی دی، پھر لفافہ، پھر ایک کپڑے میں کفن دے دیا گیا۔ (الحدیث) میں کہتا ہوں: داؤد جن کا تذکرہ ہے، ابن عاصم بن عروہ بن مسعود ہیں۔","",{"fn":"(1) اسد الغابہ (۷۲۶۶) الاستيعاب (۳۵۳۸) تجرید (۳۰۳/۲)\n(2) مسند احمد (۳۸۰/۶)"}],[10327,"§۱۱۷۱۸ ۔ لیلی بنت النضر العبدریہ\nحرف قاف میں قتیلہ کے سوانح میں ان کا ذکر گزر چکا ہے۔"],[10328,"§۱۱۷۱۹ ۔ لیلی بنت نہیک\n(1)بن اساف بن عدی بن زید بن جشم انصاریہ۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ براء کی بہن ہیں۔ ابن سعد(2) کا قول ہے: ان سے سہل بن ربیع بن عمرو بن عدی نے نکاح کیا، ان کی والدہ ام عبداللہ بن اسلم بن خریش بن مجدعہ ہیں۔","",{"fn":"(1) اسد الغابہ (۷۲۶۷) تجرید (۳۰۳/۲)\n(2) الطبقات الکبریٰ (۲۳۹/۸)"}],[10329,"§۱۱۷۲۰ ۔ لیلی بنت یسار\nمعقل بن یسار کی بہن کا ایک نام ہے۔ جن کے بارے میں آیت نازل ہوئی: تم انہیں روکو نہیں کہ اپنے شوہروں سے نکاح کریں۔(1) سہیلی نے مبہمات القرآن میں ان کا نام لیا ہے، اور منذری نے ان کی پیروی کی ہے۔ راجح یہی ہے کہ ان کا نام جمیل ہے جیسا کہ حرف جیم میں گزر چکا ہے۔","",{"fn":"(1) سورۃ البقرۃ الآیۃ (۲۳۲)"}],[10330,"§۱۱۷۲۱ ۔ لیلی السدوسیہ\n(1)بشیر بن خصاصیہ کی زوجہ ہیں، انہیں جہدمہ کہا جاتا تھا۔ بعض نے کہا کہ وہ ان کے علاوہ ہیں، جہدمہ میں اس کا بیان گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۵۸) الاستيعاب (۳۵۳۹) تجرید (۳۰۲/۲)"}],[10331,"§۱۱۷۲۲ ۔ لیلی بنت یعار\nیہ ایک ہیں جن کے بارے میں کہا گیا کہ انہوں نے سالم مولی ابو حذیفہ کو آزاد کیا۔"],[10332,"§۱۱۷۲۳ ۔ لیلی الغفاریہ\n(1)ابو عمر(2) کا قول ہے: نبی کریم صلی اللہ علیہ وسلم کے ساتھ غزوات میں شامل ہوئی تھیں، زخمیوں کا علاج کرتیں اور مریضوں کے پاس ٹھہرتی تھیں۔ ان کی حدیث ہے کہ نبی کریم صلی اللہ علیہ وسلم نے سیدہ عائشہ رضی اللہ عنہا سے فرمایا: \"یہ علی ہیں، لوگوں میں سب سے پہلے ایمان لانے والے\"۔(3) ان سے محمد بن قاسم طائی نے روایت کی۔ میں کہتا ہوں: پہلی روایت کے بارے میں حرف الف کی آخری قسم میں امامہ بنت ابی الحکم میں تنبیہ گزر چکی ہے۔ عقیلی نے موسیٰ بن قاسم کے سوانح میں جو ضعیف راوی ہیں، اور ابن مندہ نے علی بن ہاشم بن برید کی روایت سے نقل کیا ہے کہ مجھ سے میرے والد نے، فرماتے ہیں: ہم سے موسیٰ بن قاسم نے، فرماتے ہیں: مجھ سے لیلی غفاریہ نے روایت کی، فرماتی ہیں: میں نبی کریم صلی اللہ علیہ وسلم کے ساتھ غزوات میں شریک ہوتی، زخمیوں کا علاج اور مریضوں کی تیمارداری کرتی تھی۔(4) جب سیدنا علی رضی اللہ عنہ بصرہ کی طرف نکلے اور میں آپ صلی اللہ علیہ وسلم کے ساتھ نکلی، جب میں نے سیدہ عائشہ رضی اللہ عنہا کو دیکھا تو ان کے پاس آئی اور کہا: کیا آپ نے رسول اللہ صلی اللہ علیہ وسلم سے سیدنا علی رضی اللہ عنہ کی فضیلت میں کوئی حدیث سنی ہے؟ فرماتی ہیں: جی ہاں! وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور آپ صلی اللہ علیہ وسلم میرے پاس تھے، انہوں نے پرانی چادر اوڑھ رکھی تھی پھر وہ ہمارے درمیان بیٹھ گئے۔ میں نے کہا: تمہیں اس سے زیادہ کھلی جگہ نہیں ملی؟ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: \"اے عائشہ! میرے بھائی کو چھوڑ دو، وہ لوگوں میں سب سے پہلے اسلام لایا، اور آخری وقت میں میرا ساتھ دیا، اور قیامت کے دن سب سے پہلے مجھ سے ملے گا۔\" عقیلی کا قول ہے، یہ حدیث موسیٰ بن قاسم سے مروی ہے، اور بخاری رحمہ اللہ فرماتے ہیں: اس کی پیروی نہیں کی جائے گی۔ اس سند میں عبد السلام بن صالح، ابو الصلت ہیں۔ محدثین نے انہیں جھوٹا قرار دیا ہے، اور آخری روایت کے بارے میں تجرید میں ہے: وہ باطل ہے۔ میں کہتا ہوں: محمد بن قاسم، وہ طالیسکانی ہیں، طائی نہیں۔ اور وہ متروک راوی ہے، وہ موسیٰ بن قاسم کے علاوہ ہیں۔ اسی طرح کی روایت معاذہ سے مروی ہے۔ تفسیر ابن مردویہ میں ہے، اسے ابو موسیٰ نے اپنے طریق سے نقل کیا ہے، پھر یعلی بن عبید کی روایت سے بحوالہ حارث بن ابی رجال، انہوں نے عمرہ سے روایت کیا ہے، فرماتی ہیں: معاذہ غفاریہ فرماتی ہیں: میں نبی کریم صلی اللہ علیہ وسلم کی رفاقت میں تھی، آپ صلی اللہ علیہ وسلم کے ساتھ سفر میں نکلتی، مریضوں کی تیمارداری کرتی اور زخمیوں کا علاج کرتی تھی، میں سیدہ عائشہ رضی اللہ عنہا کے گھر میں رسول اللہ صلی اللہ علیہ وسلم کے پاس گئی، اور سیدنا علی رضی اللہ عنہ گھر سے باہر تھے، میں نے سنا آپ صلی اللہ علیہ وسلم سیدہ عائشہ رضی اللہ عنہا سے فرما رہے تھے: \"یہ مردوں میں مجھے سب سے زیادہ محبوب ہے، اور میرے نزدیک معزز ہے، اس کا حق پہچانو! اور اس کے مرتبے کا اکرام کرو۔۔۔۔\" (الحدیث) اس میں ہے: \"سیدنا علی رضی اللہ عنہ کو دیکھنا عبادت ہے۔\" میں کہتا ہوں: حارث ضعیف ہیں، یہ وہی حدیث ہے جس کی طرف ابو عمر نے اشارہ کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۶۵) الاستيعاب (۳۵۴۰) تجرید (۳۰۳/۲)\n(2) الاستيعاب (۱۹۱۰/۴)\n(3) الضعفاء الکبیر (۱۷۳۷/۴)\n(4) المعجم الکبیر (۴۵/۲۵) مجمع الزوائد (۳۲۴/۵) جامع المسانید والسنن (۸۹/۱۶)"}],[10333,"§۱۱۷۲۴ ۔ لیلی\n(1)عبد الرحمن بن ابی لیلی کی پھوپھی ہیں، لیلی بنت بلال میں تذکرہ ہوا ہے۔ ابی لیلی کے سوانح میں گزر چکا ہے کہ ان کے اور ان کے والد کے نام میں بہت زیادہ اختلاف ہے، صحیح یہ ہے کہ ان کے والد کا نام بلال یا بلیل ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۶۴) الاستيعاب (۳۵۳۷) تجرید (۳۰۲/۲)"}],[10334,"§۱۱۷۲۵ ۔ لیلی\n(1)سیدہ عائشہ رضی اللہ عنہا کی مولاۃ ہیں، ابو عمر(2) کا قول ہے: ان کی حدیث کی اسناد قائم نہیں، ان سے ابو عبداللہ مدنی نے روایت کی اور وہ مجہول راوی ہے۔ میں کہتا ہوں: مستغفری نے عبد الکریم النجار کے طریق سے ابی عبداللہ مدنی سے بحوالہ سیدہ عائشہ رضی اللہ عنہا ان کی دربان اور مولاۃ نقل کیا ہے، فرماتی ہیں، میں نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! آپ قضائے حاجت کے لیے تشریف لے جاتے ہیں، میں آپ کے بعد جاتی ہوں، میں وہاں کچھ نہیں دیکھتی البتہ مشک کی خوشبو پاتی ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ہم انبیاء کی جماعت کے اجسام اہل جنت کی ارواح پر پلتے بڑھتے ہیں، ہمارے جسموں میں سے جو چیز(3) نکلے زمین اسے نگل لیتی ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۶۱) الاستيعاب (۳۵۳۹) تجرید (۳۰۳/۲)\n(2) الاستيعاب (۱۹۱۰/۴)\n(3) جامع المسانید والسنن (۹۱/۱۶)"}],[10335,"§۱۱۷۲۶ ۔ لیلی\n(1)ان سے حبیب بن زید نے روایت کی ہے ابو یعلیٰ نے تجرید سے ان کی حدیث لی ہے۔","",{"fn":"(1) تجرید (۳۰۳/۲)"}],[10336,"§۱۱۷۲۷ ۔ لینہ\nجزء بن دیزیل صغیر میں ان کی حدیث ہے۔"],[10337,"§۱۱۷۲۸ ۔ لینہ\nقباء کی جگہ کی مالکن ہیں: عمر بن شبہ نے اخبار مدینہ میں صحیح سند سے، جسے وہ عروہ تک لے گئے ہیں نقل کیا ہے، فرماتے ہیں: مسجد قباء کی جگہ لینہ نامی ایک خاتون کی ملکیت تھی، وہ وہاں اپنا گدھا باندھتی تھیں، سعد بن خیثمہ نے اس میں مسجد بنائی تو مسجد ضرار والے کہنے لگے، کیا ہم لینہ کے گدھے کے اصطبل میں نماز پڑھیں؟ اللہ کی قسم نہیں، ہم ایک علیحدہ مسجد بنائیں گے اور اس میں نماز پڑھیں گے یہاں تک کہ ابو عامر آ کر ہماری امامت کروائیں اس بارے میں اللہ تعالیٰ نے یہ آیت نازل فرمائی: \"وہ لوگ جنہوں نے مسجد ضرار بنائی۔۔۔۔\"(1) الآیۃ","",{"fn":"(1) سورۃ التوبۃ الآیۃ (۱۰۷)"}],[10338,"§۱۱۷۲۹ ۔ لیلی بنت الجودی\nابن عدی بن عمرو بن ابی عمرو، غسانی، عبد الرحمن بن ابو بکر صدیق کی زوجہ ہیں، انہوں نے نبوت کا زمانہ پایا، انہوں نے انہیں جاہلیت میں دیکھا تھا، انہیں پسند آئیں، جب دمشق فتح ہوا تو وہ وہاں گئیں، انہیں ان کی طرف رغبت تھی، جو ایک طویل قصے میں ہے، زبیر بن بکار نے ان کے سوانح میں ان کا ذکر کیا ہے۔ فرمایا: وہ تجارت کے لیے دمشق آئے، اور انہیں چٹائی پر بیٹھے دیکھا، اور ان کے گرد لڑکیاں تھیں، جب ان لوگوں نے شام میں جہاد کیا تو سیدنا عمر رضی اللہ عنہ نے ان کی طرف خط لکھا، میں نے عبد الرحمن بن ابو بکر کو غنیمت میں لیلی بنت جودی دی، جب انہوں نے ان کو قیدی بنایا تو انہیں دے دیا، وہ انہیں لے کر مدینہ آئے، سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں: ان کی محبت ان کے دل میں گھر کر گئی تھی اور جب میں انہیں ملامت کرتی تھی تو وہ کہتے: اے میری بہن! مجھے چھوڑ دو، میں اس کے دانتوں سے انار کے دانے چوستا ہوں، کافی عرصہ گزر گیا، میں ان سے اس بارے میں گفتگو کرتی تھی، ان کا اس پر یہ احسان تھا کہ انہیں ان کے گھر والوں کی طرف لوٹا دیا، میں ان سے کہتی: تم نے محبت کی تو انتہا کی، اور نفرت کی تو انتہا کی، ان کے بارے میں عبد الرحمن کے مشہور اشعار ہیں: \"میں لیلی کو یاد کرتا جبکہ ہمارے درمیان گھر کا چھجہ (سقیفہ) تھا۔ جودی کی بیٹی لیلی اور مجھے کیا ہوا۔\" زبیر کی روایت میں اسی طرح مذکور ہے۔ عمر بن شبہ کی روایت میں بحوالہ صلت بن مسعود، انہوں نے احمد بن شبویہ سے، انہوں نے سلیمان بن صالح سے، انہوں نے ابن مبارک سے، انہوں نے مصعب بن ثابت سے، انہوں نے عروہ بن زبیر سے روایت کیا ہے: ابو بکر نے انہیں غنیمت میں یہ عطا کیں۔ ہم نے امالی المحاملی کے جزء تاسع کے آخر میں اہل بغداد کی ان سے روایت سے اپنی سند کے ساتھ جسے وہ ابن ابی زناد تک لے گئے ہیں، بحوالہ ہشام بن عروہ، انہوں نے اپنے والد سے روایت کیا ہے کہ عبد الرحمن بن ابو بکر اپنے والد کی خلافت کے آخری ایام میں، اسلام کے ابتدائی سالوں میں دمشق آئے، انہوں نے لیلی بنت جودی کو دیکھا، انہوں نے ان سے خوبصورت عورت نہیں دیکھی، اور ان کے بارے میں یہ شعر کہا: میں نے لیلی کو یاد کیا۔۔۔۔ اشعار سیدنا عمر رضی اللہ عنہ نے اپنے عامل کی طرف لکھا: اگر تمہیں اللہ تعالیٰ دمشق پر فتح دیں تو جودی کی بیٹی کو عبد الرحمن کے سپرد کر دینا، انہوں نے ان کے سپرد کر دیا، وہ انہیں لے کر آئے اور اپنے خاندان کی خواتین کے پاس چھوڑا پھر روایت ذکر کی، اس میں ان کا یہ قول بھی ہے گویا میں اس کے دانتوں سے انار کے دانے چوستا ہوں، فرماتی ہیں: انہوں نے کوئی ایسا کام کیا کہ ان کے دانت گر گئے تو انہیں چھوڑ دیا پھر ان کے گھر والوں کی طرف لوٹا دیا۔ یہ اس روایت کے آخری الفاظ ہیں، یہ محاملی کی آخری مجلس تھی، جس میں انہوں نے املاء کروائی۔"],[10339,"§۱۱۷۳۰ ۔ لیلی بنت حابس التمیمیہ\nاقرع بن حابس کی بہن ہیں، جو مشہور صحابی ہیں۔ غالب بن صعصعہ بن معاویہ کی والدہ ہیں، جو مشہور شاعر فرزدق کے والد ہیں: انہوں نے نبوت کا زمانہ پایا، فرزدق نے اپنے والد کے مرثیہ میں ان کا ذکر کیا ہے، کہتے ہیں: \"صبر اس بات سے انکاری ہے کہ میں طلوع ہوتے بدر اور سورج کو نہ دیکھوں، جب دیکھتا ہوں تو مجھے غالب کی یاد دلاتے ہیں۔ دونوں ابن لیلی کے مشابہ تھے جو ابن لیلی کے مشابہ ہوگا ستاروں کی روشنی میں داخل ہو جائے گا۔\""],[10340,"§۱۱۷۳۱ ۔ لیلی بنت حکیم\n(1)ابن اثیر کا کلام گزر چکا ہے، انہوں نے کہا ہے کہ ممکن ہے کہ بنت خطیم ہوں، یوں ان سے لفظی غلطی ہوئی۔ جہاں تک مجھے معلوم ہوا ہے یہ یہی لیلی بنت حکیم ہی ہیں۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۷۲۵۴)، تجرید (۳۰۲/۲)"}],[10341,"§۱۱۷۳۲ ۔ الماردہ\nحکیم بن حزام کی حدیث میں ان کا ذکر ہے، جو مسند ابی یعلیٰ میں ہے، بعض کا قول ہے: المرادیہ"],[10342,"§۱۱۷۳۳ ۔ ماریہ القبطیہ\n(1)رسول اللہ صلی اللہ علیہ وسلم کی ام ولد ہیں، ابن سعد(2) نے عبداللہ بن عبد الرحمن بن ابی صعصعہ کے طریق سے ذکر کیا ہے فرماتے ہیں: اسکندریہ کے بادشاہ مقوقس نے ۷ھ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس سیدہ ماریہ، ان کی بہن سیرین، ہزار مثقال سونا، بیس ملائم کپڑے، دلدل نامی خچر، اور عفیر نامی گدھا بھیجا، بعض نے کہا: یعفور، ان کے ساتھ ایک خصی تھا جسے مابور کہا جاتا تھا۔ وہ بہت بوڑھا اور سیدہ ماریہ کا بھائی تھا، یہ تمام چیزیں حاطب بن ابی بلتعہ کے ساتھ بھیجیں، حاطب بن ابی بلتعہ نے ماریہ پر اسلام پیش کیا اور اس کی ترغیب دی، انہوں نے اور ان کی بہن نے اسلام قبول کر لیا، جبکہ خصی اپنے دین پر رہا، بعد میں وہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں اسلام لے آیا، سیدہ ماریہ رضی اللہ عنہا سفید رنگت اور خوبصورت تھیں، رسول اللہ صلی اللہ علیہ وسلم نے انہیں مدینہ کے بالائی حصہ میں ٹھہرایا، جو اس مال میں تھا جسے سریہ(3) ام ابراہیم کہا جاتا تھا آپ وہیں ان کے پاس آتے جاتے باندی ہونے کی وجہ سے ان سے شب باشی کرتے۔ (اگر چہ وہ آپ کی باندی تھیں لیکن ان سے آزاد عورتوں کی طرح سلوک کرتے یہی وجہ ہے کہ) ان پر پردہ لازم کر دیا، وہاں ان کے ہاں ذی الحجہ ۸ھ میں رسول اللہ صلی اللہ علیہ وسلم کے صاحبزادے کی ولادت ہوئی۔ عمرہ کے طریق سے بحوالہ عائشہ مروی ہے۔ فرماتی ہیں: ماریہ کے علاوہ کسی عورت کو مجھ سے زیادہ مقام نہیں ملا۔ یہ اس لیے کہ وہ بہت حسین و جمیل تھیں، اس لیے رسول اللہ صلی اللہ علیہ وسلم کو پسند تھیں پہلے پہل جب آپ تشریف لائے تو سیدنا حارثہ بن نعمان کے گھر انہیں ٹھہرایا۔ وہ ہمارے پڑوس میں تھیں، آپ صلی اللہ علیہ وسلم دن اور رات کے اکثر اوقات ان کے پاس رہتے، یہاں تک کہ ہمیں خدشہ ہونے لگا، یہاں تک کہ میں جزع فزع کرنے لگی تو آپ صلی اللہ علیہ وسلم نے انہیں مدینے کے بالائی حصے میں منتقل کر دیا وہیں آپ کا آنا جانا ہوتا، یہ بھی ہمیں گراں گزرتا۔ مسند میں بحوالہ واقدی مروی ہے، سیدہ ماریہ رضی اللہ عنہا حجرے کے پاس حاضر ہونے والوں میں سے تھیں۔ بلاذری کا قول ہے: سیدہ ماریہ رضی اللہ عنہا کی والدہ رومی تھیں اور سیدہ ماریہ سفید رنگت، گھنگریالے بالوں والی حسن و جمیل تھیں۔ بزار نے حسن سند سے بحوالہ عبداللہ بن بریدہ انہوں نے اپنے والد سے نقل کیا ہے، فرماتے ہیں: قبط کے امیر نے رسول اللہ صلی اللہ علیہ وسلم کو دو لونڈیاں اور ایک خچر ہدیہ دیا، آپ صلی اللہ علیہ وسلم مدینہ میں خچر پر سوار ہوتے تھے اور دونوں لونڈیوں میں سے ایک کو اپنے لیے مخصوص کر لیا، ان کے بیٹے ابراہیم کے سوانح میں ان کا ذکر گزر چکا ہے، مابور نصیبی کے سوانح اور صالح کے سوانح میں بھی ان کا تذکرہ ہے۔ واقدی کا قول ہے: مجھ سے موسیٰ بن محمد بن ابراہیم نے بحوالہ اپنے والد روایت کیا ہے، فرماتے ہیں: سیدنا ابو بکر رضی اللہ عنہ سیدہ ماریہ رضی اللہ عنہا کو خرچ بھیجتے تھے، یہاں تک کہ ان کی وفات ہو گئی پھر سیدنا عمر رضی اللہ عنہ انہیں خرچ بھیجتے یہاں تک کہ ان کی خلافت میں وہ وفات پا گئیں۔ واقدی کا قول ہے: محرم ۱۶ھ میں فوت ہوئیں، سیدنا عمر رضی اللہ عنہ ان کے جنازے کے لیے لوگوں کو جمع کر رہے تھے، اور ان پر بقیع میں نماز جنازہ پڑھی، ابن مندہ کا قول ہے: سیدہ ماریہ رضی اللہ عنہا نبی کریم صلی اللہ علیہ وسلم کی وفات کے پانچ برس بعد فوت ہوئیں۔","",{"fn":"(1) اسد الغابہ (۷۲۶۸)، الاستيعاب (۳۵۴۳)، تجرید (۳۰۳/۲)\n(2) الطبقات الکبریٰ (۱۵۳/۸، ۱۵۶)\n(3) السیر والمغازی (۲۷۱)"}],[10343,"§۱۱۷۳۴ ۔ ماریہ\n(1)نبی کریم صلی اللہ علیہ وسلم کی خادمہ تھیں، ابو عمر(2) کا قول ہے: ان کی کنیت ام رباب تھی، اہل بصرہ کے پاس ان کی حدیث ہے کہ وہ نبی صلی اللہ علیہ وسلم کے لیے جھکیں یہاں تک کہ آپ ان کا سہارا لے کر دیوار پر چڑھے جس رات مشرکوں سے آپ جان بچا کر نکلے تھے۔ میں کہتا ہوں: اسے ابن مندہ نے یعلی بن اسد کے طریق سے بحوالہ عبداللہ بن حبیب، انہوں نے ام سلیمان سے، انہوں نے اپنی والدہ سے، انہوں نے ان کی دادی ماریہ سے روایت کی، فرماتی ہیں: وہ نبی کریم صلی اللہ علیہ وسلم کے لیے جھکیں۔۔۔۔ پھر حدیث ذکر کی۔ ان کے لیے یہ عنوان قائم کیا، ماریہ، نبی کریم صلی اللہ علیہ وسلم کی باندی۔ میں کہتا ہوں: آگے آئے گا کہ ان کی والدہ کا نام مرضیہ ہے اور یہ کہ وہ صحابیہ ہیں، رہیں ام سلیمان تو مجھے ان کا نام معلوم نہیں۔","",{"fn":"(1) اسد الغابہ (۷۲۶۹) الاستيعاب (۳۵۴۲) تجرید (۳۰۳/۲)\n(2) الاستيعاب (۱۹۱۳/۴)"}],[10344,"§۱۱۷۳۵ ۔ ماریہ\n(1)نبی کریم صلی اللہ علیہ وسلم کی خادمہ ہیں۔(2) ان سے ایک حدیث منقول ہے، جو اہل کوفہ کے ہاں ہے۔ اسے ابوبکر بن عیاش نے بحوالہ مثنی بن صالح، انہوں نے ان کی دادی ماریہ سے روایت کیا ہے، فرماتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم سے مصافحہ کیا، میں نے(3) آپ کی ہتھیلی مبارک سے زیادہ ملائم کسی کا ہاتھ نہیں دیکھا۔ ابو عمر نے ان سے پہلے والی میں فرمایا: مجھے معلوم نہیں، وہ یہی ہیں یا اس کے علاوہ ہیں؟ میں کہتا ہوں: انہوں نے یہ ساری بات ابن سکن کے کلام سے لی ہے۔ ابن سکن کا قول ہے: ماریہ نبی کریم صلی اللہ علیہ وسلم کی مولاۃ، ان سے حدیث مروی ہے جو اہل کوفہ سے منقول ہے، مجھے معلوم نہیں کہ ان سے ابن عباس کے علاوہ کسی نے روایت کی ہو، پھر اسے دو طریق سے ان کے حوالے سے حدیث روایت کی، پھر فرماتے ہیں: سیدہ ماریہ سے ایک اور حدیث مروی ہے، بصریوں نے اسے روایت کیا ہے، مجھے معلوم نہیں کیا یہ وہی ہیں جن کی حدیث ابوبکر نے روایت کی یا ان کے علاوہ ہیں؟ پھر یعلی بن اسد کے طریق سے بحوالہ محمد بن حمران، انہوں نے عبداللہ بن حبیب سے، انہوں نے ام سلیمان سے، انہوں نے اپنی والدہ سے، انہوں نے اپنی دادی ماریہ سے حدیث روایت کی، فرماتی ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کے لیے جھکی یہاں تک کہ آپ دیوار کے اوپر چڑھ گئے جس رات مشرکین سے جان بچا کر نکلے تھے۔ ابونعیم کا قول ہے: ابن مندہ نے ان کا علیحدہ ذکر کیا ہے، حالانکہ وہ دونوں میرے نزدیک ایک ہیں۔ میں کہتا ہوں: ابن مندہ نے اسے دو طریق سے موصولاً ذکر کیا ہے، بحوالہ ابوبکر بن عیاش، ابو عمر کے قول کے مطابق ان میں سے ایک یہ ہیں، بحوالہ مثنی بن صالح، انہوں نے اپنی دادی سے روایت کیا ہے، اور دوسرا طریق یہ ہے: بحوالہ ابوبکر، فرماتے ہیں: اللہ کی قسم! ہم سے محمد بن مثنی بن صالح نے بحوالہ اپنی دادی روایت کیا ہے۔ واللہ اعلم! ابو عمر کا قول ہے، مثنی بن صالح اور وہ ابن مہران مولی عمرو بن حریث ہے، اسی طرح فرمایا۔","",{"fn":"(1) اسد الغابہ (۷۲۷۰) الاستيعاب (۳۵۴۱) تجرید (۳۰۳/۲)\n(2) الاستيعاب (۱۹۱۳/۴)\n(3) المعجم الکبیر (۷۷/۲۵) جامع المسانید والسنن (۹۶/۱۶)"}],[10345,"§۱۱۷۳۶ ۔ ماریہ\n(1)یا ماویہ، راویوں نے بحوالہ ابن اسحاق ان میں اختلاف کیا ہے، یونس بن بکیر وغیرہ نے ان کے حوالے سے کہا ہے: ماویہ واؤ کے ساتھ ہے، انہوں نے خبیب بن عدی کے قصہ میں ذکر کیا ہے، جب مشرکوں نے بئر معونہ کے قصے میں انہیں قیدی بنا لیا تھا، اور بیڑیاں پہنا کر انہیں قتل کرنے لگے۔ ابن اسحاق(2) کا قول ہے: مجھ سے عبداللہ بن ابی نجیح نے بحوالہ ماریہ مولاۃ حجیر بن ابی اہاب روایت کی، فرماتی ہیں: مکہ میں خبیب کو میرے گھر میں قید کیا گیا، میں نے ایک دن جھانکا تو ان کے ہاتھ میں ان کے سر سے بڑا انگور کا گچھا تھا، جس میں سے وہ کھا رہے تھے، حالانکہ اس وقت انگور کا موسم نہیں تھا۔ میں کہتا ہوں: یہ بخاری رحمہ اللہ نے صحیح میں خبیب کی شہادت کے قصہ میں بیان کیا ہے، لیکن ان کی روایت میں یہ نہیں: ان کے سر سے بڑا تھا۔ انہوں نے اپنی روایت میں فرمایا: مکہ میں اس وقت اور یہی مراد ہے، گویا انہوں نے مطلق زمین کہا اور مکہ کی سرزمین مراد لی۔ ابو عمر(3) نے بحوالہ عقیلی ان کی سند سے جسے وہ عبداللہ بن اورلین اودی تک لے گئے ہیں، بحوالہ محمد بن اسحاق ذکر کیا، وہ فرماتے ہیں کہ مجھ سے ابن نجیح نے حدیث بیان کی کہ انہوں نے بحوالہ ماریہ مولاۃ حجیر حدیث بیان کی اور اسے راء اور تخفیف کے ساتھ ذکر کیا کہ سیدنا خبیب بن عدی کو جب ان کے گھر میں قید کیا گیا، وہ اسلام لانے کے بعد بیان کرتی ہیں، فرماتی ہیں: اللہ کی قسم! انہیں میرے گھر میں قید کیا گیا، جس کا دروازہ بند تھا، جب دروازے کی رون سے میں نے جھانکا تو ان کے ہاتھ آدمی کے سر کی طرح انگور کا گچھا تھا، جس میں سے وہ کھا رہے تھے، اس وقت زمین پر انگور نہیں تھے۔ جب ان کے قتل کا وقت آیا تو انہوں نے فرمایا: اے ماریہ! مجھے کوئی تیز دھار چیز دو، جس سے صفائی کروں۔ فرماتی ہیں: میں نے اپنے ایک لڑکے کو استرا دیا اور اس سے کہا کہ یہ اس کے پاس لے جاؤ، جب وہ اس کے پاس گیا تو میں نے دل میں کہا کہ اس لوہے کے ذریعے اس لڑکے کو قتل کرنے سے اس شخص کو اپنا بدلہ مل جائے گا، تا کہ مرد کے بدلے مرد ہو جائے، تو وہ کہنے لگے مجھے اپنی زندگی کی قسم! تمہاری ماں کو جو خدشہ ہو رہا ہے اس کی ضرورت نہیں، جب اس نے استرے کے ساتھ میرے پاس بھیجا، یعنی تمہارے ساتھ، پھر اسے چھوڑ دیا۔ یہ قصہ بخاری میں بھی ہے۔ ابن سعد رحمہ اللہ(4) نے بحوالہ واقدی رحمہ اللہ یہ اسے ذکر کیا ہے، انہوں نے اہل علم میں سے کئی راویوں سے اسے نقل کیا، اس میں ہے: انہوں نے انہیں، ان کے گھر قید کیا، تا کہ حرمت والا مہینہ گزر جائے تو انہیں قتل کریں۔ وہ اسلام لانے کے بعد ان کا قصہ بیان کرتی تھیں، جبکہ ان کا اسلام سنور چکا تھا، اس میں ہے: وہ تہجد کی نماز میں قرآن پڑھتے تھے، جب عورتوں نے اسے سنا تو رونے لگیں اور انہیں ان پر رحم آگیا تو میں نے ان سے پوچھا: تمہاری کوئی حاجت ہے؟ انہوں نے فرمایا: نہیں! سوائے اس کے کہ مجھے میٹھا پانی پلاؤ، جو بتوں کے پاس ذبح کیا جائے مجھے نہ کھانے کو دو، اور جب وہ مجھے قتل کرنے کا ارادہ کریں تو مجھے خبر دینا، جب ان لوگوں نے انہیں قتل کرنے کا ارادہ کیا تو میں نے انہیں اس کی خبر دی، اللہ کی قسم! انہیں اس کا مطلق خوف نہ ہوا۔ انہوں نے کہا: میرے لیے استرا بھیج دینا، جس سے پاکیزگی حاصل کروں۔ میں نے اپنے بیٹے ابو حسین کے ہاتھ ان کے پاس استرا بھیجا، وہ انہیں دودھ پلاتی تھیں، وہ ان کا اپنا بیٹا نہیں تھا۔ پھر انہوں نے پہلے کی طرح ذکر کیا، اس میں ہے: میں اسے قتل کرنے والا نہیں ہوں اور ہمارے دین میں دھوکہ کرنا جائز نہیں۔","",{"fn":"(1) اسد الغابہ (۷۲۷۱) تجرید (۳۰۳/۲)\n(2) السیرۃ النبویۃ (۱۳۶/۳، ۱۳۷)\n(3) الاستيعاب (۱۹۱۱/۴)\n(4) الطبقات الکبریٰ (۲۶۱/۸)"}],[10346,"§۱۱۷۳۷ ۔ محبہ بنت الربیع\n(1)بن عمرو بن ابی زہیر انصاریہ۔ بنو حارث بن خزرج سے ہیں۔ ابن سعد(2) رحمہ اللہ اور ابن حبیب نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کرنے والوں میں ان کا ذکر کیا ہے۔ سعد بن ربیع کی بہن ہیں، ان سے ابودرداء عامر بن زید بن قیس انصاری خزرجی نے نکاح کیا، جس سے بلال پیدا ہوئے، ان کی والدہ کا نام ہریلہ بنت مکتبہ بن عمرو بن حدیج بن عامر بن بشم ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۷۲) تجرید (۳۰۳/۲)\n(2) الطبقات الکبریٰ (۲۶۱/۸)"}],[10347,"§۱۱۷۳۸ ۔ محجنہ\n(1)بعض کا قول ہے: ام مجن، حبشی خاتون تھیں، اور مسجد میں جھاڑو دیتی تھیں، صحیح میں بغیر نام لیے ان کا تذکرہ کیا ہے، یحییٰ بن ابی انیسہ نے ان کا نام لیا ہے، اور وہ متروک راوی ہیں، بحوالہ علقمہ بن مرثد، انہوں نے اہل مدینہ کے ایک آدمی سے روایت کی، فرماتے ہیں: اہل مدینہ میں سے ایک خاتون جنہیں مجنہ کہا جاتا تھا، مسجد کی صفائی کرتی تھیں، نبی کریم صلی اللہ علیہ وسلم نے انہیں نہ پایا تو پوچھا، لوگوں نے بتایا کہ وہ فوت ہو گئی ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم نے مجھے خبر کیوں نہ دی؟\"(2) آپ صلی اللہ علیہ وسلم تشریف لے گئے، ان کی نماز جنازہ پڑھی اور چار تکبیریں کہیں۔ یحییٰ کا قول ہے: ہم سے زہری رحمہ اللہ نے بحوالہ ابو امامہ بن سہل انہوں نے نبی کریم صلی اللہ علیہ وسلم سے یہی حدیث روایت کی۔ عبداللہ بن بریدہ کے طریق سے بحوالہ ان کے والد روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم ایک قبر سے گزرے جس کی تازی تازی تدفین ہوئی تھی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اسے کب دفن کیا گیا؟\" لوگوں نے کہا: یہ ام مجن ہے۔ جو مسجد سے خس و خاشاک شوق سے اٹھاتی تھیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم نے مجھے کیوں نہ بتایا؟\" کہنے لگے: آپ صلی اللہ علیہ وسلم سوئے ہوئے تھے، ہم نے آپ کو بیدار کرنا پسند نہ کیا۔ (الحدیث)","",{"fn":"(1) اسد الغابہ (۷۲۷۳) تجرید (۳۰۳/۲)\n(2) بخاری (۴۶۰) (۱۳۳۶)"}],[10348,"§۱۱۷۳۹ ۔ محیاۃ بنت خالد\n(1)بن سنان عبسی۔ ابو موسیٰ نے ذیل میں ان کا ذکر کیا ہے، اور محمد بن عمر رازی حافظ کے طریق سے بحوالہ عمرو بن اسحاق بن علاء، انہوں نے ابراہیم بن علاء سے وہ فرماتے ہیں کہ ہم سے ابومحمد قریشی، ہاشمی نے بحوالہ ہشام بن عروہ، انہوں نے ابن عمارہ سے، انہوں نے اپنے والد عمارہ بن حزن بن شیطان سے خالد بن سنان کے قصے میں روایت کیا، فرماتے ہیں: جب اللہ تعالیٰ نے آپ صلی اللہ علیہ وسلم کو مبعوث فرمایا تو آپ صلی اللہ علیہ وسلم کے پاس محیاۃ بنت خالد آئیں، اور اپنا نسب بیان کیا۔ آپ صلی اللہ علیہ وسلم نے ان کے لیے اپنی چادر بچھائی اور انہیں اس پر بٹھایا، فرمایا: \"میری بھتیجی! اور اس نبی کی بیٹی جسے اس کی قوم نے ضائع کر دیا۔\"(2) ابن کلبی کی روایت میں ان کا نام منقول ہے، فرماتے ہیں: میرے والد نے فرمایا: اور مجھے ابن ابی عمارہ نے خبر دی، فرماتے ہیں: ہمارے پاس خالد بن سنان آئے اور فرمایا: اے بنو عبس کی جماعت! اللہ تعالیٰ نے مجھے اس آگ کے بجھانے کا حکم دیا ہے، میرے والد نے کہا: اور میرے والد ان کے ساتھ گئے تھے، پھر طویل قصہ ذکر کیا۔ حدیث کے آخر میں ہے، ہشام بن محمد فرماتے ہیں: محیاۃ بنت خالد بن سنان نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"میری بھتیجی کو خوش آمدید! اور اس نبی کی بیٹی جسے اس کی قوم نے ضائع کر دیا، میں نے خالد بن سنان کے سوانح میں آگ بجھانے کا قصہ بہت سے طرق سے ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۷۴) تجرید (۳۰۴/۲)\n(2) اسد الغابہ (۳۹۵/۵)"}],[10349,"§۱۱۷۴۰ ۔ محیاۃ بنت ابی نائلہ\n(1)سلکان بن سلامہ بن وقش اشہلیہ، ابن سعد(2) نے ان کا ذکر کیا ہے اور فرمایا: اسلام لائیں اور بیعت کی، یہ ابن عمارہ کی روایت میں ہے، واقدی رحمہ اللہ کا قول ہے: یہ عبادہ ہیں جن کا ذکر حرف عین میں گزر چکا ہے۔","",{"fn":"(1) تجرید (۳۰۴/۲)\n(2) الطبقات الکبریٰ (۲۳۵/۸)"}]])